E["quest:93443"] = {t="quest",n="Lost Shipping Crate",z="riverglades",s="Friz Frazzlespark’s Lost Shipping Crate bears a warning against opening it without supervision. Its label directs you to return it to Powderfuse Port in the Riverglades.",h="Friz Frazzlespark’s Lost Shipping Crate bears a warning against opening it without supervision.",sec={{t="The Crate’s Label",b="A handwritten label on the Lost Shipping Crate names Friz Frazzlespark and Powderfuse Port. It warns against tampering or opening the crate without supervision, then asks that it be returned to Friz at the port in the Riverglades.",sp=0}},faq={{q="Who owns the Lost Shipping Crate?",a="The label names Friz Frazzlespark as the crate’s owner.",al={"crate owner","who does it belong to"}},{q="Where should I take the crate?",a="The label directs you to return the Lost Shipping Crate to Friz Frazzlespark at Powderfuse Port in the Riverglades.",al={"where to return crate","crate delivery"}},{q="What does the label say?",a="The handwritten label warns against tampering with or opening the crate without supervision, and says to return it to Friz Frazzlespark.",al={"crate warning","what's on the label"}},{q="What is shown on the crate’s map?",a="The label’s map marks a southeastern shoreline north of a poorly drawn temple surrounded by water and winged creatures.",al={"crate map","what's on the map"}}},kw={"crate label","crate map","friz frazzlespark","lost shipping crate","powderfuse port","riverglades"},rel={"zone:riverglades","quest:94930"},m={id=93443},src={"In-game quest text: Lost Shipping Crate"},fv=true}
E["quest:93786"] = {t="quest",n="A Message in Blood",z="riverglades",s="Krom’rosh sends you against the human farm at Meadowsbrook. He wants the farmhands slain to answer the defectors’ claim to the land.",h="Krom’rosh sends you against the human farm at Meadowsbrook.",sec={{t="The Farmhands",b="Krom’rosh points you toward Meadowsbrook Farm, southwest across the river. Human defectors claimed the farm some years ago, then reached toward Farholde, the keep on the eastern shore. Krom’rosh says earlier skirmishes lacked the numbers to prevail. Now he wants you to disrupt the farm and leave no prisoners.",sp=0}},faq={{q="Who asks me to go to Meadowsbrook?",a="Krom’rosh asks you to attack Meadowsbrook Farm and disrupt its farming.",al={"who sent me","Krom'rosh task","who is asking"}},{q="Why does Krom’rosh want the farm attacked?",a="Human defectors claimed the farm and expanded toward Farholde. Krom’rosh wants to remind them his people are present.",al={"why attack farm","why Meadowsbrook","why fight humans"}},{q="Where is Meadowsbrook Farm?",a="Meadowsbrook Farm lies southwest across the river.",al={"where is the farm","Meadowsbrook location","farm southwest"}},{q="Who are the farmhands?",a="The Meadowsbrook Farmhands are the people Krom’rosh sends you to slay.",al={"farmhands who","Meadowsbrook people","humans at farm"}},{q="What happened in the earlier skirmishes?",a="Krom’rosh says the earlier skirmishes would have favored his side if they had had more fighters.",al={"earlier fights","why skirmishes failed","Kromrosh skirmishes"}}},ang={["faction:Horde"]="As a member of the Horde, you carry out Krom’rosh’s order against human defectors who have claimed the farm."},kw={"a message in blood","farholde","farm","human defectors","krom'rosh","meadowsbrook farm","meadowsbrook farmhands","skirmishes"},rel={"topic:human"},m={faction="Horde",id=93786},src={"In-game quest text: A Message in Blood"},fv=true}
E["quest:93787"] = {t="quest",n="Food for the Taking",z="riverglades",s="Krom'rosh sends you to an Alliance farm in Meadowsbrook for its feed. Taking the supplies will hinder the humans and buy time to plan the next move.",h="Krom'rosh sends you to an Alliance farm in Meadowsbrook for its feed.",sec={{t="The Farm's Stores",b="The Alliance farm in Meadowsbrook holds feed that Krom'rosh wants taken. You are sent to the southwest to seize what you find, denying the humans supplies and buying time for another plan.",sp=0}},faq={{q="Who wants the feed taken?",a="Krom'rosh wants you to take feed from the Alliance farm in Meadowsbrook.",al={"who sent me","Kromrosh request","who wants supplies"}},{q="Where is the farm?",a="The Alliance farm is in Meadowsbrook, to the southwest.",al={"where is alliance farm","Meadowsbrook farm","farm location"}},{q="Why take the supplies?",a="Taking the supplies will deny the humans their provisions and buy time to plan the next move.",al={"why steal feed","why deny food","what is the point"}},{q="What supplies are being taken?",a="The supplies are Feed Satchels from the Alliance farm.",al={"what feed","feed satchels","what to steal"}}},ang={["faction:Horde"]="As a member of the Horde, you are asked to deny the Alliance humans the comfort and sustenance of their farm supplies."},kw={"alliance farm","feed satchels","food for the taking","humans","krom'rosh","meadowsbrook","supplies"},rel={"topic:alliance","topic:human"},m={faction="Horde",id=93787},src={"In-game quest text: Food for the Taking"},fv=true}
E["quest:93788"] = {t="quest",n="Borrowed Blades",z="riverglades",s="Kreza Darkthorn asks you to take the lumberjacks’ axes from Turner's Logging Camp. Their blades will supply materials for weapons in Rog'mar.",h="Kreza Darkthorn asks you to take the lumberjacks’ axes from Turner's Logging Camp.",sec={{t="At the Logging Camp",b="Kreza Darkthorn keeps Rog'mar's forge running while Gur'dok breaks down the blades. The human presence to the south and Twilight to the west make gathering resources difficult. You are asked to bring back the lumberjacks' axes from Turner's Logging Camp, so their materials can be fashioned into weapons.",sp=0}},faq={{q="Who wants the axes?",a="Kreza Darkthorn in Rog'mar asks you to retrieve the axes from Turner's Logging Camp.",al={"who sent me","Kreza's axes","who needs blades"}},{q="Why does Kreza want the lumberjacks' axes?",a="Gur'dok will break down the blades, and Kreza will use their materials to make weapons.",al={"why axes","what are axes for","weapon materials"}},{q="Where is Turner's Logging Camp?",a="Turner's Logging Camp is south along the river, by the mill.",al={"logging camp location","where are the lumberjacks","Turner's camp"}},{q="What makes gathering resources difficult?",a="The human presence to the south and Twilight to the west make the fight for resources difficult.",al={"why resources are hard","human presence","Twilight nearby"}}},kw={"borrowed blades","forge","gur'dok","kreza darkthorn","lumberjacks","rog'mar","turner's logging camp","weapons","woodworker's axe"},m={faction="Horde",id=93788},src={"In-game quest text: Borrowed Blades"},fv=true}
E["quest:93976"] = {t="quest",n="The Goblin Trader",z="riverglades",s="Kreza sends you to deliver a blade to an acquaintance at the docks east of Rog'mar. The recipient is known across the Kingdoms and beyond.",h="Kreza sends you to deliver a blade to an acquaintance at the docks east of Rog'mar.",sec={{t="A Blade for the Docks",b="Kreza Darkthorn has fashioned a blade with Gur'dok and asks you to carry it east of Rog'mar. Her acquaintance waits at the docks, known far beyond the Kingdoms. Kreza says the two of them are even.",sp=0}},faq={{q="Who is sending me with the blade?",a="Kreza Darkthorn sends you with a blade she fashioned with Gur'dok.",al={"who sent me","Kreza blade delivery"}},{q="Who is the blade for?",a="It is for Kreza Darkthorn's acquaintance at the docks east of Rog'mar.",al={"blade recipient","who gets the sword"}},{q="Where do I deliver the blade?",a="You deliver it to Kreza Darkthorn's acquaintance at the docks east of Rog'mar.",al={"where are the docks","dock delivery"}},{q="What does Kreza say about the debt?",a="Kreza tells you to say that she and her acquaintance are even.",al={"what does Kreza mean by even","Kreza we're even"}}},ang={["faction:Horde"]="The recipient calls the delivery one made on behalf of the Horde."},kw={"acquaintance","blade","docks","goblin trader","gur'dok","kreza darkthorn","rog'mar"},rel={"topic:horde"},m={faction="Horde",id=93976},src={"In-game quest text: The Goblin Trader"},fv=true}
E["quest:94480"] = {t="quest",n="A Gift From Our Enemies",z="riverglades",s="You bring stolen feed to Gorg in Rog'mar so its allies can be fed. Nearby gnolls and the encroaching Twilight threaten the settlement.",h="You bring stolen feed to Gorg in Rog'mar so its allies can be fed.",sec={{t="Food for Rog'mar",b="Gorg is waiting in Rog'mar for the stolen feed you gathered. The humans are not the only threat nearby: gnolls snarl from the hills, and the Twilight encroaches. Keeping Rog'mar's allies fed may help preserve their strength.",sp=0},{t="A Hearty Stew",b="The feed smells pungent and earthy, with something unpleasant beneath it. Gorg recognizes that you took it from the farmstead and says it will make a hearty stew for the allies.",sp=1}},faq={{q="Why does Gorg want the stolen feed?",a="Gorg will use the stolen feed to make a hearty stew for Rog'mar's allies.",al={"why feed","gorg feed","stolen feed for what"}},{q="What threats are near Rog'mar?",a="The humans are one threat, while gnolls snarl from nearby hills and the Twilight encroaches.",al={"gnolls nearby","twilight threat","what's near rogmar"}},{q="Who is Gorg?",a="Gorg is the one who receives the stolen feed in Rog'mar and says it can make a hearty stew.",al={"gorg who","who's gorg"}},{q="Where do I take the stolen feed?",a="Take the stolen feed to Gorg in Rog'mar.",al={"feed location","where bring feed","gorg location"}}},kw={"allies","farmstead","gnolls","gorg","hearty stew","rog'mar","stolen feed","twilight"},rel={"topic:gnoll","quest:94672"},m={faction="Horde",id=94480},src={"In-game quest text: A Gift From Our Enemies"},fv=true}
E["quest:94481"] = {t="quest",n="A Serving of Strength",z="riverglades",s="A trainer asks you to feed Rog’mar trainees at the training grounds. The stew helps keep them fed while defending the supply lines grows difficult.",h="A trainer asks you to feed Rog’mar trainees at the training grounds.",sec={{t="Food for Trainees",b="The trainees at the training grounds need food, and their trainer sends you with hearty stew. You are to feed the Rog’mar trainees to the west. Their complaints can wait; defending the supply lines has grown difficult, and the warriors are thankful for the food you bring.",sp=0}},faq={{q="Who needs the stew?",a="Rog’mar trainees at the training grounds need the stew.",al={"who is hungry","who gets fed","trainee food"}},{q="Where do I take the stew?",a="The Rog’mar trainees are at the training grounds to the west.",al={"where to feed trainees","trainees location","stew where"}},{q="Why are they being fed stew?",a="The stew keeps the trainees fed while defending the supply lines has become difficult.",al={"why stew","what's the food for","why feed trainees"}},{q="What does the trainer think of the trainees' complaints?",a="The trainer says the trainees can bring any further complaints directly to them.",al={"trainee complaints","why are they complaining","trainer mad"}},{q="Is the trainer thankful for the food?",a="Yes. The trainer and the warriors are thankful for the food, despite what the warriors say.",al={"does trainer appreciate it","thanks for stew","warriors thankful"}}},kw={"a serving of strength","rog’mar trainees","stew","supply lines","trainees","training grounds","warriors"},m={faction="Horde",id=94481},src={"In-game quest text: A Serving of Strength"},fv=true}
E["quest:94483"] = {t="quest",n="Show Them How It's Done",z="riverglades",s="A commander sends you south of the river to strike Farholde training camps. The assault is meant to hold humans near their keep and buy time for other concerns.",h="A commander sends you south of the river to strike Farholde training camps.",sec={{t="By the River",b="The commander points you toward Farholde camps south of the river, where scouts have reported human forces. You are asked to slay Farholde Priests and Farholde Scouts. Keeping the humans back from their keep will give the commander time to attend to other matters.",sp=0}},faq={{q="Who is asking me to attack the camps?",a="A commander who received scouts' reports about training camps south of the river sends you against the Farholde forces.",al={"who gave this","commander asking"}},{q="Where are the Farholde camps?",a="The training camps are south of the river.",al={"where camps","farholde location"}},{q="Who am I supposed to target?",a="The commander names Farholde Priests and Farholde Scouts as the targets.",al={"who to kill","targets"}},{q="Why attack the humans?",a="Holding the humans back near their keep is meant to buy time for the commander's other concerns.",al={"why fight humans","what is the point"}},{q="What happens after the attack?",a="The commander says the effort was swift and intends to continue elsewhere.",al={"what next","after camps"}}},kw={"farholde","humans","keep","priests","river","scouts","training camps"},m={faction="Horde",id=94483},src={"In-game quest text: Show Them How It's Done"},fv=true}
E["quest:94532"] = {t="quest",n="Gnoll Infestation",z="riverglades",s="Neza Bloodsnout at Rog'mar asks you to drive back gnolls in the hills to the southwest. Their presence disrupts trade and travel, though Twilight's encroachment has reduced their numbers.",h="Neza Bloodsnout at Rog'mar asks you to drive back gnolls in the hills to the southwest.",sec={{t="Gnolls in the Hills",b="With their numbers diminished by Twilight's encroachment, Redridge gnolls still trouble the hills southwest of Rog'mar. Neza Bloodsnout asks you to clear a path for allies by removing the threat. Trade and travelers remain disrupted while the gnolls hold their ground.",sp=0}},faq={{q="Why are the gnolls a problem?",a="The gnolls in the hills southwest of Rog'mar disrupt trade and trouble travelers.",al={"gnolls disrupting trade","why clear gnolls","gnoll threat"}},{q="Where are the gnolls?",a="They infest the hills to the southwest.",al={"gnoll hills","where are redridge gnolls"}},{q="Who asks me to deal with them?",a="Neza Bloodsnout at Rog'mar asks you to remove the gnoll threat.",al={"who gave gnoll infestation","Neza quest"}},{q="Are there fewer gnolls now?",a="Yes. Their presence has dwindled with Twilight's encroachment, but the threat remains.",al={"gnoll numbers","twilight gnoll"}},{q="What kinds of gnolls are there?",a="The gnolls named are Redridge Mystics, Redridge Trappers, and Redridge Brutes.",al={"gnoll types","mystics trappers brutes"}}},kw={"brutes","gnoll infestation","gnolls","mystics","neza bloodsnout","redridge","rog'mar","trappers","twilight"},rel={"topic:gnoll"},m={faction="Horde",id=94532},src={"In-game quest text: Gnoll Infestation"},fv=true}
E["quest:94533"] = {t="quest",n="Snargl's Snout",z="riverglades",s="Neza Bloodsnout seeks Snargl's snout as a trophy. The elder gnoll's unpleasant sounds trouble allies and scouts in the Bristle Hills.",h="Neza Bloodsnout seeks Snargl's snout as a trophy.",sec={{t="A Trophy for Neza",b="Neza Bloodsnout wants a memento for a collection, and Snargl is the gnoll she names. You are sent to the Bristle Hills to retrieve his snout. Neza expects you to be swift; the allies and scouts entering that area face trouble from Snargl's sounds.",sp=0}},faq={{q="Who is Snargl?",a="Snargl is an elder gnoll in the Bristle Hills southwest of Neza Bloodsnout.",al={"snargl","snargl gnoll","elder gnoll"}},{q="Why does Neza want Snargl's snout?",a="Neza wants Snargl's snout as a memento for a trophy collection.",al={"why snout","snargl trophy","neza collection"}},{q="Where is Snargl?",a="Snargl is in the Bristle Hills, southwest of Neza Bloodsnout.",al={"snargl location","where snargl","bristle hills gnoll"}},{q="What trouble does Snargl cause?",a="Snargl makes unpleasant sounds that trouble allies and scouts who enter the Bristle Hills.",al={"snargl sounds","why scouts troubled","gnoll noise"}},{q="What does Neza say when you return?",a="Neza says the trophy is heavier than expected and welcomes it as an addition to the collection.",al={"snargl completion","neza reaction","snout done"}}},kw={"bristle hills","gnoll","neza bloodsnout","snargl","snargl's snout","snout","trophy"},rel={"topic:gnoll"},m={faction="Horde",id=94533},src={"In-game quest text: Snargl's Snout"},fv=true}
E["quest:94535"] = {t="quest",n="Bristle Hills Bandits",z="riverglades",s="Kreza Darkthorn sends you to the Bristle Hills after gnolls attack allied miners. You are asked to recover the stolen ore from their camps.",h="Kreza Darkthorn sends you to the Bristle Hills after gnolls attack allied miners.",sec={{t="Ore from the Hills",b="Allied miners report gnoll attacks in the hills south of Kreza Darkthorn. You are asked to find the camps in the Bristle Hills and recover the stolen ore. The miners' losses are at stake.",sp=0},{t="After the Recovery",b="Kreza Darkthorn says the ore is recovered and that fire will erase any marks or scent left behind.",sp=1}},faq={{q="Who sends me after the stolen ore?",a="Kreza Darkthorn asks you to recover the ore stolen from allied miners.",al={"who is Kreza","ore giver"}},{q="Where are the bandits?",a="The gnolls are in camps in the Bristle Hills, south of Kreza Darkthorn.",al={"gnoll camps","where bandits"}},{q="Who stole the ore?",a="Gnolls in the Bristle Hills attacked allied miners and took their ore.",al={"ore thieves","who took it"}},{q="What happened to the miners?",a="Allied miners working in the hills to the south reported several attacks by gnolls.",al={"miners attacked","why stolen ore"}}},kw={"allied miners","bandits","bristle hills","gnolls","kreza darkthorn","stolen ore"},rel={"topic:gnoll"},m={faction="Horde",id=94535},src={"In-game quest text: Bristle Hills Bandits"},fv=true}
E["quest:94556"] = {t="quest",n="Jom-jom's Escape",z="riverglades",s="Jom-jom wants to return home and asks you to escort him to Clugfist at Bolder'ok.",h="Jom-jom wants to return home and asks you to escort him to Clugfist at Bolder'ok.",sec={{t="The Way Home",b="Jom-jom set out to find a friend. Now he needs you to guide him to Clugfist at Bolder'ok so he can go home.",sp=0}},faq={{q="Who is Jom-jom?",a="Jom-jom came looking for a friend and now wants to go home.",al={"who's jom-jom","jom-jom"}},{q="Where does Jom-jom want to go?",a="Jom-jom wants to return home, and you are asked to escort him to Clugfist at Bolder'ok.",al={"where is jom-jom going","jom-jom home"}},{q="Who is Clugfist?",a="Clugfist is the one Jom-jom is to be escorted to at Bolder'ok.",al={"clugfist","who's clugfist"}},{q="Why did Jom-jom come here?",a="Jom-jom came looking for a friend.",al={"why jom-jom here","jom-jom came"}},{q="Does Jom-jom consider you a friend?",a="After you save him, Jom-jom calls you a friend.",al={"jom-jom friend","little one"}}},kw={"bolder'ok","clugfist","escort","friend","home","jom-jom"},m={faction="Horde",id=94556},src={"In-game quest text: Jom-jom's Escape"},fv=true}
E["quest:94613"] = {t="quest",n="My Kingdom for a Horse",z="riverglades",s="A nearby farm has lost its horses, leaving Farholde without cavalry for its campaign against the Horde. You are sent to Wheeler’s Grange to speak with Benjy.",h="A nearby farm has lost its horses, leaving Farholde without cavalry for its campaign against the Horde.",sec={{t="The Missing Stock",b="Farholde’s warhorses come from two nearby farms, but Wheeler’s Grange has lost all of its stock. The cause is unknown, and without horses Farholde has no cavalry for its campaign against the Horde. You are sent to speak with Benjy at the grange and learn what he has to say.",sp=0}},faq={{q="Why does Farholde need the horses?",a="Farholde relies on warhorses for its cavalry, which it considers necessary for its campaign against the Horde.",al={"why horses","need warhorses","farholde cavalry"}},{q="What happened to the horses at Wheeler’s Grange?",a="All of the Wheeler family’s stock is missing, and the cause is unknown.",al={"missing horses","where horses go","wheeler horses"}},{q="Who is Benjy?",a="Benjy is at Wheeler’s Grange, where you are sent to ask about the missing horses.",al={"benjy","wheeler grange guy","who do i talk to"}},{q="Where are Farholde’s warhorses kept?",a="Farholde’s warhorses come from two nearby farms. The Wheeler family owns one of them, Wheeler’s Grange.",al={"horse farms","where horses from","warhorse farms"}}},kw={"benjy","horde","missing horses","my kingdom for a horse","farholde cavalry","warhorses","wheeler's grange"},rel={"topic:horde"},m={faction="Alliance",id=94613},src={"In-game quest text: My Kingdom for a Horse"},fv=true}
E["quest:94614"] = {t="quest",n="Freshwater Fiends",z="riverglades",s="A farmer near Wheeler's Grange asks you to drive Mudfin murlocs from the river. They threaten his animals and wildlife, and have taken over his favorite fishing spot.",h="A farmer near Wheeler's Grange asks you to drive Mudfin murlocs from the river.",sec={{t="By the River",b="The farmer's animals and the local wildlife suffer while Mudfin murlocs remain along the river near Wheeler's Grange. Their presence has also cost him his favorite fishing spot. You are asked to kill some of the murlocs, and the Riverglades folk would welcome the help.",sp=0}},faq={{q="Why does the farmer want the murlocs gone?",a="The farmer says the Mudfin murlocs are bad for his animals and the wildlife, and have settled on his favorite fishing spot.",al={"why kill murlocs","murlocs by the river"}},{q="Where are the Mudfin murlocs?",a="They are along the river near Wheeler's Grange.",al={"mudfin location","where are murlocs"}},{q="Which murlocs are involved?",a="The farmer names Mudfin Oracles and Mudfin Warriors.",al={"mudfin types","what murlocs"}},{q="What does the farmer ask me to do?",a="He asks you to kill eight Mudfin Oracles and eight Mudfin Warriors along the river near Wheeler's Grange.",al={"freshwater fiends task","kill how many murlocs"}},{q="Who would appreciate the help?",a="The farmer says the Riverglades folk would appreciate having some of the murlocs removed.",al={"who wants murlocs gone","riverglades people"}}},kw={"fishing spot","freshwater fiends","mudfin","murloc","oracle","riverglades","warrior","wheeler's grange"},rel={"zone:riverglades","topic:murloc"},m={faction="Alliance",id=94614},src={"In-game quest text: Freshwater Fiends"},fv=true}
E["quest:94615"] = {t="quest",n="Foal Play",z="riverglades",s="At Wheeler's Grange, the horses have vanished from the stables. You search for clues to help find out what happened.",h="At Wheeler's Grange, the horses have vanished from the stables.",sec={{t="A Search at the Grange",b="The stables at Wheeler's Grange may hold clues to the missing horses. Their keeper says they were gone when he rose to feed them. Outside Farholde, animals, murlocs, orcs, and other dangers could be to blame. You search near the stables to narrow down what happened.",sp=0}},faq={{q="Where did the horses go?",a="The horses disappeared from Wheeler's Grange, and you search near the stables for evidence of where they went.",al={"missing horses","horses gone","where horses"}},{q="What could have taken the horses?",a="The keeper considers animals, murlocs, orcs, or other dangers outside Farholde as possible culprits.",al={"who took horses","horse culprit","what got them"}},{q="Why are the horses important?",a="The horses are how their keeper makes a living.",al={"why horses matter","horses living","horse business"}},{q="Where should I look for clues?",a="Search near the stables at Wheeler's Grange for evidence about the missing horses.",al={"stable clues","where to search","foal play"}}},kw={"coyotes","farholde","foal play","horses","missing horses","murlocs","stables","wheeler's grange"},rel={"topic:murloc"},m={faction="Alliance",id=94615},src={"In-game quest text: Foal Play"},fv=true}
E["quest:94617"] = {t="quest",n="Coyote Huntin'",z="riverglades",s="Benjy Wheeler asks you to deal with Sootfur, the dark-furred leader of a coyote pack west of the river. The coyotes have turned to eating horses after murlocs drove them from their usual fishing ground.",h="Benjy Wheeler asks you to deal with Sootfur, the dark-furred leader of a coyote pack west of the river.",sec={{t="A Threat to the Horses",b="Benjy Wheeler says the coyotes once hunted fish along the shore, but murlocs drove them from that feeding ground. Now the pack has taken to eating horses. Its leader is a larger, dark-furred coyote called Sootfur. Benjy asks you to bring back Sootfur's pelt, hoping the rest of the pack will scatter.",sp=0},{t="Benjy's Stables",b="When you return with Sootfur's pelt, Benjy says the coyote had been rooting around in his stables. He thanks you and says he expects the horses to be safe when the stables are running again.",sp=1}},faq={{q="Who is Sootfur?",a="Sootfur is the larger, dark-furred leader of the coyote pack west of the river.",al={"sootfur","dark coyote","coyote leader"}},{q="Why are the coyotes eating horses?",a="Murlocs pushed the coyotes away from their usual fishing ground along the shore, so they began eating horses.",al={"why horses","coyotes eating horses","coyote food"}},{q="Who asks for Sootfur's pelt?",a="Benjy Wheeler asks you to bring him Sootfur's pelt.",al={"benjy","who is benjy","sootfur pelt"}},{q="Where is the coyote den?",a="The pack lives in a den west of Benjy's location, across the river.",al={"coyote den","where coyotes","den location"}}},kw={"benjy wheeler","coyote","den","horses","murlocs","pelt","sootfur","stables"},rel={"topic:murloc"},m={faction="Alliance",id=94617},src={"In-game quest text: Coyote Huntin'"},fv=true}
E["quest:94618"] = {t="quest",n="Wheeler's Fleeing Steeds",z="riverglades",s="Benjy asks you to find a horse that fled Wheeler's Grange after coyotes attacked. Feed it so it trusts you and can be led back.",h="Benjy asks you to find a horse that fled Wheeler's Grange after coyotes attacked.",sec={{t="Fled from the Grange",b="Benjy at Wheeler's Grange needs your help finding one of the horses that fled the coyote attack. Some horses were taken by coyotes, while others ran off in fear. Give a horse some feed so it will trust you and let you lead it back.",sp=0}},faq={{q="What happened to the horses?",a="Coyotes got most of the horses, while some fled from Wheeler's Grange in fear.",al={"horses at Wheeler's Grange","coyote attack horses"}},{q="Who is asking for help?",a="Benjy asks you to find a horse that fled Wheeler's Grange.",al={"who gave me this","Benjy horses"}},{q="What should I do with the feed?",a="Give some of the feed to a horse so it trusts you and can be led back.",al={"how to use the sack","feed horse"}},{q="Why are the horses being sought?",a="Benjy says the escaped horses should be found before the coyotes return.",al={"why find horses","where did they go"}}},kw={"benjy","coyotes","feed","fled horses","horses","wheeler's fleeing steeds","wheeler's grange"},m={faction="Alliance",id=94618},src={"In-game quest text: Wheeler's Fleeing Steeds"},fv=true}
E["quest:94668"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="At the Bloodmaster's Ring, you report to Jezap after proving yourself against Twilight ogres. The Bloodmaster is ready to judge whether you belong.",h="At the Bloodmaster's Ring, you report to Jezap after proving yourself against Twilight ogres.",sec={{t="At the Ring",b="The challenge at the Bloodmaster's Ring has brought you to Jezap, the ring's goblin. After you defeat the Twilight ogres, you report to him, with the Bloodmaster and Jezap watching. They are deciding whether you belong among those who approach the precipice of power.",sp=0}},faq={{q="Who do I report to at the Bloodmaster's Ring?",a="You report to Jezap at the Bloodmaster's Ring.",al={"who is Jezap","report to Jezap","bloodmaster ring goblin"}},{q="What did I do before coming here?",a="You smashed Twilight ogres that were judged weak.",al={"what happened before","twilight ogres","ring previous step"}},{q="What is the Bloodmaster looking for?",a="The Bloodmaster is judging whether you belong at the precipice of power.",al={"prove myself","what does Bloodmaster want","do I belong"}}},kw={"bloodmaster","bloodmaster's ring","goblin","jezap","precipice of power","twilight ogres"},rel={"topic:goblin"},m={faction="Horde",id=94668},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:94669"] = {t="quest",n="Pay to Play",z="riverglades",s="A collector demands a safety deposit before you can enter the Bloodmaster's Ring. Pay, and you qualify to prove your strength there.",h="A collector demands a safety deposit before you can enter the Bloodmaster's Ring.",sec={{t="The Price of Entry",b="To enter the Bloodmaster's Ring, you are asked to pay a safety deposit. The collector says the payment is required for your safety. Without it, they threaten to tell Clugfist that you refused to prove your strength to the welcoming company. Your choice decides whether you qualify for the ring.",sp=0}},faq={{q="Why do I have to pay?",a="The collector says a safety deposit is required for your safety and to qualify for the Bloodmaster's Ring.",al={"why pay","safety deposit","pay to play quest"}},{q="Who is Clugfist?",a="Clugfist is the person the collector threatens to tell if you refuse to pay.",al={"who's clugfist","clugfist","old clugfist"}},{q="What happens if I refuse?",a="The collector says they will tell Clugfist that you were unwilling to prove your strength.",al={"don't pay","refuse deposit","no deposit"}},{q="What does paying qualify me for?",a="Paying the safety deposit qualifies you for the Bloodmaster's Ring.",al={"qualify for what","ring entry","bloodmaster ring"}}},kw={"bloodmaster's ring","clugfist","pay to play","prove your strength","ring","safety deposit"},rel={"quest:94668"},m={faction="Horde",id=94669},src={"In-game quest text: Pay to Play"},fv=true}
E["quest:94670"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="The Bloodmaster's Ring challenge sends you against Buzzbeak for a chance at fame. The ring's goblin expects the fight to be easy.",h="The Bloodmaster's Ring challenge sends you against Buzzbeak for a chance at fame.",sec={{t="Into the Ring",b="The ring's goblin puts Buzzbeak before you in the ring. You are told this first fight should be easy, though the fiend is said to bring down its foe and take their belongings. Fame is promised to those who enter.",sp=0}},faq={{q="Who do I fight in the Bloodmaster's Ring?",a="You face Buzzbeak in the Bloodmaster's Ring.",al={"bloodmaster fight","who is buzzbeak","ring opponent"}},{q="What is Buzzbeak supposed to do?",a="Buzzbeak is described as a flighty fiend that can bring you down and take your belongings.",al={"buzzbeak attack","what does buzzbeak do","fiend in ring"}},{q="Why enter the ring?",a="The ring's goblin promises fame for entering the ring.",al={"ring fame","bloodmaster fame","why fight buzzbeak"}},{q="Is this fight meant to be easy?",a="The ring's goblin presents this as an easy first fight.",al={"easy ring fight","bloodmaster easy","buzzbeak hard"}}},kw={"bloodmaster","bloodmaster's ring","buzzbeak","fame","fiend","fight","ring"},rel={"quest:94668"},m={faction="Horde",id=94670},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:94672"] = {t="quest",n="Encroaching Twilight",z="riverglades",s="Tran'gul warns that Twilight's Hammer has struck a human settlement west of Rog'mar. You are sent to Sunnyglade to thin the cult's numbers before it gains a foothold nearby.",h="Tran'gul warns that Twilight's Hammer has struck a human settlement west of Rog'mar.",sec={{t="A Threat Nearby",b="The human settlement to the west has already been ravaged, and Rog'mar may be next. Tran'gul sends you to Sunnyglade, where Twilight's Hammer has begun its campaign against those it calls heretics. Its raiders and neophytes threaten to establish a foothold close to Rog'mar.",sp=0},{t="After the Fight",b="With the cult's numbers diminished, Tran'gul can seek the source of its unprecedented expansion.",sp=1}},faq={{q="Who is Tran'gul worried about?",a="Tran'gul fears Twilight's Hammer, a cult attacking those it deems heretics.",al={"who's the threat","twilight hammer threat"}},{q="What happened to the human settlement?",a="Twilight's Hammer has ravaged a human settlement west of Rog'mar.",al={"settlement west","what happened west"}},{q="Why am I going to Sunnyglade?",a="Tran'gul sends you to Sunnyglade to thin the numbers of Twilight's Hammer.",al={"why sunnyglade","what's in sunnyglade"}},{q="Who might the cult target next?",a="Tran'gul fears Rog'mar may be next after the human settlement to the west.",al={"who's next","rogmar next"}}},kw={"encroaching twilight","human settlement","rog'mar","sunnyglade","tran'gul","twilight neophytes","twilight raiders","twilight's hammer"},rel={"subzone:sunnyglade","zone:riverglades","topic:twilight-s-hammer","topic:human"},m={faction="Horde",id=94672},src={"In-game quest text: Encroaching Twilight"},fv=true}
E["quest:94678"] = {t="quest",n="Gnoll Infestation",z="riverglades",s="Cedric Dalton at Southern Watch asks you to thin the Redridge gnolls. Their numbers make the northern passage dangerous and threaten people beyond Farholde Keep.",h="Cedric Dalton at Southern Watch asks you to thin the Redridge gnolls.",sec={{t="A Threat Nearby",b="Cedric Dalton at Southern Watch faces gnolls across the hills beyond the post. Their numbers make passage north dangerous, and people outside Farholde Keep are at risk. You are asked to reduce their hold on the area by killing Redridge Mystics, Trappers, and Brutes.",sp=0}},faq={{q="Why are the gnolls a problem?",a="The gnolls are aggressive and numerous. They make passage north dangerous and threaten people living outside Farholde Keep.",al={"why gnolls","gnolls dangerous","gnoll infestation"}},{q="Who asks me to deal with the gnolls?",a="Cedric Dalton at Southern Watch asks you to reduce the gnoll threat.",al={"who gave gnoll task","Cedric Dalton","Southern Watch gnolls"}},{q="Which gnolls are involved?",a="The Redridge Mystics, Redridge Trappers, and Redridge Brutes are named as the gnolls to kill.",al={"gnoll types","Redridge gnolls","mystics trappers brutes"}},{q="Where are the gnolls?",a="They infest the hills beyond Southern Watch, making passage to the north dangerous.",al={"gnoll location","where are they","hills beyond post"}}},kw={"cedric dalton","farholde keep","gnoll infestation","gnolls","northern passage","redridge brutes","redridge mystics","redridge trappers","southern watch"},rel={"topic:gnoll","topic:twilight-s-hammer"},m={faction="Alliance",id=94678},src={"In-game quest text: Gnoll Infestation"},fv=true}
E["quest:94679"] = {t="quest",n="Snargl's Snout",z="riverglades",s="Cedric Dalton at Southern Watch wants Snargl's snout from the Bristle Hills. He believes killing a strong gnoll will weaken Redridge's ranks and frighten them.",h="Cedric Dalton at Southern Watch wants Snargl's snout from the Bristle Hills.",sec={{t="A Gnoll in the Hills",b="At Southern Watch, Cedric Dalton asks you to deal with Snargl, a notorious gnoll in a den among the Bristle Hills. He believes gnolls prize strength above all else, so Snargl's death could weaken Redridge's ranks and spread fear among them. Cedric wants you to bring back Snargl's snout.",sp=0},{t="A Trophy Returned",b="Cedric receives Snargl's snout as a trophy and says it will soon be put to use. The gnoll's death is meant to strike fear into Redridge's ranks.",sp=1}},faq={{q="Who is Snargl?",a="Snargl is a notorious gnoll in a den among the Bristle Hills.",al={"snargl who","snargl gnoll","bristle hills gnoll"}},{q="Who wants Snargl's snout?",a="Cedric Dalton at Southern Watch asks you to bring him Snargl's snout.",al={"snargl snout for who","cedric dalton request","southern watch snout"}},{q="Why does Cedric want Snargl dead?",a="Cedric believes gnolls value strength above all else, and that killing their strongest will weaken them and frighten them.",al={"why kill snargl","gnoll strength","scare redridge"}},{q="Where is Snargl?",a="Snargl is in a den among the Bristle Hills.",al={"snargl location","where snargl","bristle hills den"}}},kw={"bristle hills","cedric dalton","gnoll","redridge","snargl","snargl's snout","southern watch"},rel={"topic:gnoll"},m={faction="Alliance",id=94679},src={"In-game quest text: Snargl's Snout"},fv=true}
E["quest:94680"] = {t="quest",n="Twilight Missives",z="riverglades",s="Tran'gul seeks to learn why Twilight's Hammer cultists have grown more numerous around Sunnyglade. He asks you to bring back their missives so he can learn what they seek.",h="Tran'gul seeks to learn why Twilight's Hammer cultists have grown more numerous around Sunnyglade.",sec={{t="A Growing Presence",b="Tran'gul has seen more Twilight's Hammer cultists in the area than before. Their shadowmancers are trusted members of the order and may hold knowledge of its campaign. You are asked to bring back missives from them, so Tran'gul can learn what the cult seeks.",sp=0}},faq={{q="Who asks for the Twilight Missives?",a="Tran'gul in Rog'mar asks you to recover missives from Twilight Shadowmancers in Sunnyglade.",al={"who wants the missives","tran'gul request","who is tran'gul"}},{q="Where can I find the Twilight Shadowmancers?",a="The Twilight Shadowmancers are in Sunnyglade.",al={"shadowmancer location","where are twilight cultists","sunnyglade missives"}},{q="Why does Tran'gul want the missives?",a="Tran'gul wants to learn more about the cultists and what they seek.",al={"why get missives","what does tran'gul want to know","cultist papers"}},{q="Why is Tran'gul concerned about the cultists?",a="Tran'gul has seen Twilight's Hammer cultists in greater numbers than before, and they seem emboldened to expand their influence.",al={"why are twilight here","cultists growing","twilight numbers"}}},kw={"cultists","missives","rog'mar","sunnyglade","tran'gul","twilight missives","twilight shadowmancers","twilight's hammer"},rel={"subzone:sunnyglade","topic:twilight-s-hammer"},m={faction="Horde",id=94680},src={"In-game quest text: Twilight Missives"},fv=true}
E["quest:94727"] = {t="quest",n="Digging for Answers",z="riverglades",s="The Twilight's Hammer is digging through the Riverglades for an unknown source of power. You are sent to Sunnyglade to question one of their miners.",h="The Twilight's Hammer is digging through the Riverglades for an unknown source of power.",sec={{t="Miners in Sunnyglade",b="The Twilight's Hammer has workers digging in Sunnyglade, and you are sent to question one of the miners. Their search points to a source of power, but its nature remains unknown. The zealots keep their secrets close, so the miners may know what they seek.",sp=0}},faq={{q="What is the Twilight's Hammer digging for?",a="The Twilight's Hammer appears to be searching for a source of power in the Riverglades, but what it is remains unknown.",al={"what are they digging for","twilight hammer digging","source of power"}},{q="Why am I questioning a miner?",a="The Twilight's Hammer zealots keep their secrets, so you are sent to question one of their miners in Sunnyglade.",al={"why miner","talk to the miner","digging answers quest"}},{q="Where are the miners?",a="The miners are digging in Sunnyglade, within the Riverglades.",al={"where is sunnyglade","miner location","riverglades digging"}}},kw={"digging for answers","miner","riverglades","source of power","sunnyglade","twilight's hammer"},rel={"zone:riverglades","subzone:sunnyglade","topic:twilight-s-hammer","quest:96988"},m={faction="Horde",id=94727},src={"In-game quest text: Digging for Answers"},fv=true}
E["quest:94733"] = {t="quest",n="Our Ogre Friend",z="riverglades",s="A goblin asks you to find Gobam in Bolder'ok and bring food for Snufflesnout, Chub'chob's pet boar. Gobam is willing to help because Chub'chob is his friend.",h="A goblin asks you to find Gobam in Bolder'ok and bring food for Snufflesnout, Chub'chob's pet boar.",sec={{t="A Friend’s Request",b="After you win a few battles, the goblin asks you to find Gobam in Bolder'ok. He needs food for Snufflesnout, Chub'chob's pet boar, but says his work keeps him busy. Gobam is east of Clugfist's clubhouse, and the goblin hopes you can find him.",sp=0}},faq={{q="Who is Gobam?",a="Gobam is the shy fellow the goblin sends you to find in Bolder'ok.",al={"gobam who","who's gobam"}},{q="Where can I find Gobam?",a="Gobam is east of Clugfist's clubhouse in Bolder'ok.",al={"gobam location","where gobam"}},{q="Who is Snufflesnout?",a="Snufflesnout is Chub'chob's pet boar, and the goblin asks you to bring food for it.",al={"snufflesnout","boar food"}},{q="Why does the goblin need help?",a="The goblin says his work keeps him busy, so he asks you to find food for Snufflesnout.",al={"why help goblin","goblin busy"}},{q="Why will Gobam help?",a="Gobam says he dislikes the goblin, but he will help Chub'chob because they are good friends.",al={"gobam help","why gobam helps"}}},kw={"bolder'ok","chub'chob","clubhouse","gobam","goblin","our ogre friend","pet boar","snufflesnout"},rel={"topic:goblin"},m={faction="Horde",id=94733},src={"In-game quest text: Our Ogre Friend"},fv=true}
E["quest:94734"] = {t="quest",n="A Boar's Delight",z="riverglades",s="Gobam asks you to gather sweet berries and river plants for Snufflesnout, Chub'chob's pet. The ingredients will make a special treat.",h="Gobam asks you to gather sweet berries and river plants for Snufflesnout, Chub'chob's pet.",sec={{t="A Pet's Treat",b="Gobam wants to make something special for Snufflesnout, who loves good food. You are asked to bring back sweet berries and river plants for the treat.",sp=0}},faq={{q="Who is Gobam?",a="Gobam is asking you to bring ingredients for a special treat for Snufflesnout, Chub'chob's pet.",al={"gobam who","who asks for berries"}},{q="Who is Snufflesnout?",a="Snufflesnout is Chub'chob's pet and loves good food.",al={"snufflesnout pet","gobam's pet"}},{q="What ingredients does Gobam want?",a="Gobam asks for sweet berries and riverweed to make a treat for Snufflesnout.",al={"berry and plant","what food"}},{q="Why does Gobam want berries?",a="Gobam wants sweet berries and riverweed to make a special treat for Snufflesnout.",al={"why berries","berries for what"}}},kw={"berry","gobam","pet","riverweed","snufflesnout","sweetberry","treat"},m={faction="Horde",id=94734},src={"In-game quest text: A Boar's Delight"},fv=true}
E["quest:94737"] = {t="quest",n="A Treat for a Friend",z="riverglades",s="Gobam asks you to bring a treat to Jezap Jinglesprocket in Bolder'ok. Jezap says keeping Snufflesnout happy, by which he means Chub'chob, matters most.",h="Gobam asks you to bring a treat to Jezap Jinglesprocket in Bolder'ok.",sec={{t="Gobam's Request",b="The bundle of goods Gobam hands you is a treat for Snufflesnout, Chub'chob's pet boar, and he says she will snort with happiness when she sees it. He also asks you to tell the goblin Jezap to talk less.",sp=0}},faq={{q="Who is the treat for?",a="Gobam says the treat is for Snufflesnout, Chub'chob's pet boar.",al={"who gets the treat","snufflesnout treat"}},{q="Who should I deliver the goods to?",a="The bundle of goods is for Jezap Jinglesprocket in Bolder'ok.",al={"where deliver bundle","jezap delivery"}},{q="What message should I pass along?",a="Gobam asks you to tell Jezap to stop talking so much.",al={"what tell jezap","goblin message"}},{q="Who is Snufflesnout?",a="Snufflesnout is Chub'chob's pet boar, which Jezap promised to look after. Jezap jokes that keeping Snufflesnout happy really means keeping Chub'chob happy.",al={"snufflesnout who","snufflesnout"}}},kw={"a treat for a friend","bolder'ok","bundle of goods","chub'chob","jezap jinglesprocket","snufflesnout"},rel={"topic:goblin"},m={faction="Horde",id=94737},src={"In-game quest text: A Treat for a Friend"},fv=true}
E["quest:94739"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="The ring's goblin sends you into the pit of the Bloodmaster's Ring for a bout with Kronk. The crowd is already eager for the next round.",h="The ring's goblin sends you into the pit of the Bloodmaster's Ring for a bout with Kronk.",sec={{t="The Next Bout",b="The announcer is readying the crowd while Kronk waits as the next contestant. You are sent into the pit to face him, and the noise rises around the coming bout.",sp=0}},faq={{q="Who is Kronk?",a="Kronk is the next contestant in the Bloodmaster's Ring. The announcer says they go way back and describes him as a strong brawler.",al={"kronk","who's kronk","kronk bloodmaster"}},{q="What does the Bloodmaster want me to do?",a="You are sent into the pit of the Bloodmaster's Ring to face Kronk.",al={"what do i do","ring task","bloodmaster ring"}},{q="Why am I fighting Kronk?",a="The announcer introduces Kronk as the next contestant, and the bout is set in the Bloodmaster's Ring.",al={"why kronk","fight kronk","kronk fight"}},{q="Where does the bout take place?",a="The bout takes place in the pit of the Bloodmaster's Ring.",al={"where is the fight","the pit","ring location"}},{q="What happens after I enter the pit?",a="The announcer prepares to introduce Kronk while you ready yourself in the pit.",al={"after entering","next in the ring","what happens next"}},{q="What does the announcer say about Kronk?",a="The announcer says Kronk is not very bright, but is good at pummeling anything in his path.",al={"kronk backstory","what's kronk like","announcer kronk"}}},kw={"announcer","bloodmaster","bloodmaster's ring","bout","contestant","kronk","pit"},rel={"quest:94668"},m={faction="Horde",id=94739},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:94744"] = {t="quest",n="The Wayward Warrior",z="riverglades",s="Krom'rosh asks you to join his brother Dag'rosh at the Twilight's Hammer stronghold west of Rog'mar. The cult's foothold in Sunnyglade has weakened, and the fight is moving to its stronghold.",h="Krom'rosh asks you to join his brother Dag'rosh at the Twilight's Hammer stronghold west of Rog'mar.",sec={{t="A Brother Ahead",b="Krom'rosh sends you after Dag'rosh, who has gone ahead with a scouting party. The hills west of Rog'mar are where you are to find him. Krom'rosh says the Twilight's Hammer has lost ground in Sunnyglade, and their ogre warriors have turned against them. Now he wants you beside his brother as the battle moves to the cult's stronghold.",sp=0}},faq={{q="Who is asking me to find Dag'rosh?",a="Krom'rosh asks you to join his brother Dag'rosh at the Twilight's Hammer stronghold.",al={"who sent me","Krom'rosh","who wants Dag'rosh"}},{q="Where can I find Dag'rosh?",a="Krom'rosh says to look for Dag'rosh in the hills west of Rog'mar.",al={"where is Dag'rosh","Dag'rosh location","find Da'grosh"}},{q="Who is Dag'rosh?",a="Dag'rosh is Krom'rosh's brother. He has gone ahead with a scouting party.",al={"Dag'rosh backstory","Krom'rosh brother","who's Dag'rosh"}},{q="What happened to the Twilight's Hammer in Sunnyglade?",a="The Twilight's Hammer foothold in Sunnyglade has weakened, and its ogre warriors have turned against it.",al={"Sunnyglade cult","Twilight's Hammer foothold","what happened to the ogres"}}},kw={"dag'rosh","krom'rosh","ogre warriors","rog'mar","sunnyglade","the wayward warrior","twilight's hammer"},rel={"subzone:sunnyglade","topic:twilight-s-hammer"},m={faction="Horde",id=94744},src={"In-game quest text: The Wayward Warrior"},fv=true}
E["quest:94745"] = {t="quest",n="Carving a Path",z="riverglades",s="Da'grosh asks you to challenge the Twilight's Hammer at the Twilight's Shroud. He believes their reliance on devilry and ancient gods leaves them vulnerable.",h="Da'grosh asks you to challenge the Twilight's Hammer at the Twilight's Shroud.",sec={{t="The Shroud",b="Da'grosh points you toward the Twilight's Shroud, a fortress west of his position. He calls its Twilight's Hammer occupants cowards and scorns their reliance on devilry and ancient gods. He wants you to show them how vulnerable they are.",sp=0},{t="A Test of Strength",b="At the Twilight's Shroud, Da'grosh asks you to defeat Twilight Fanatics, Twilight Corrupters, and Twilight Champions. He insists that true strength rests in one's own hands.",sp=0}},faq={{q="Who is Da'grosh asking me to fight?",a="Da'grosh asks you to fight Twilight Fanatics, Twilight Corrupters, and Twilight Champions at the Twilight's Shroud.",al={"who do I fight","Da'grosh enemies"}},{q="Where is the Twilight's Shroud?",a="Da'grosh describes the Twilight's Shroud as a fortress just west of his position.",al={"where's the Shroud","Twilight fortress location"}},{q="Why does Da'grosh call the Twilight's Hammer weak?",a="Da'grosh believes their reliance on devilry and ancient gods makes them weak.",al={"why are they weak","Da'grosh on Twilight"}},{q="What does Da'grosh want me to prove?",a="Da'grosh wants you to show the Twilight's Hammer that they are vulnerable.",al={"what am I proving","show them vulnerable"}}},kw={"ancient gods","carving a path","da'grosh","devilry","twilight champion","twilight corrupter","twilight fanatic","twilight's hammer","twilight's shroud"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=94745},src={"In-game quest text: Carving a Path"},fv=true}
E["quest:94748"] = {t="quest",n="Break Their Chains",z="riverglades",s="Da’grosh asks you to free Rog’mar Scouts imprisoned in the Twilight’s Shroud. His warriors need to return to Rog’mar before they can fight again.",h="Da’grosh asks you to free Rog’mar Scouts imprisoned in the Twilight’s Shroud.",sec={{t="Scouts in Captivity",b="Da’grosh’s warriors were captured by the Twilight’s Hammer before their attack could begin. The cult’s champions took them to a fortress west of Da’grosh and imprisoned them. He asks you to free his Orc brothers and sisters in the Twilight’s Shroud.",sp=0},{t="After the Rescue",b="Da’grosh says his warriors are too hurt to fight and have returned to Rog’mar. He tells you that your work together continues.",sp=1}},faq={{q="Who is asking for help?",a="Da’grosh asks you to free his captured warriors.",al={"who is dagrosh","who needs help"}},{q="Who was captured?",a="The Twilight’s Hammer captured Da’grosh’s warriors, the Rog’mar Scouts.",al={"captured orcs","rogmar scouts"}},{q="Where are the scouts imprisoned?",a="The Rog’mar Scouts are imprisoned in a fortress west of Da’grosh, within the Twilight’s Shroud.",al={"scouts location","where are they held"}},{q="Who captured Da’grosh’s warriors?",a="The Twilight’s Hammer’s champions captured Da’grosh’s warriors.",al={"who took the orcs","twilight hammer captives"}}},ang={["race:Orc"]="As an Orc, Da’grosh asks you to free his Orc brothers and sisters from captivity."},kw={"break their chains","captured orcs","da’grosh","fortress","rog’mar scouts","twilight’s hammer","twilight’s shroud"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=94748},src={"In-game quest text: Break Their Chains"},fv=true}
E["quest:94768"] = {t="quest",n="Bring Me His Head",z="riverglades",s="Da'grosh rallies his freed warriors to shatter the Twilight's Hammer presence at Twilight's Shroud. With the cult thrown into disarray, you are called to breach their stronghold and take the head of Overlord Kilgar.",h="Da'grosh rallies his freed warriors to shatter the Twilight's Hammer presence at Twilight's Shroud.",sec={{t="Strike at the Stronghold",b="Recovered notes left by Tran'gul revealed that Overlord Kilgar commands the Twilight's Hammer inside Twilight's Shroud. Now that his captive warriors have broken free and thrown the cult into disorder, Da'grosh intends to strike their fortress before they can recover. He calls on you to venture into the stronghold, bring down Kilgar, and sever the head of their leadership.",sp=0},{t="A Grievance Settled",b="Deep within Twilight's Shroud, Overlord Kilgar falls to your assault. Returning with the warlord's severed head, you find Da'grosh satisfied that their captor is dead. He casts the trophy into the dirt, marking the end of Kilgar's command over the stronghold.",sp=1}},faq={{q="Who is Overlord Kilgar?",a="Overlord Kilgar commands the Twilight's Hammer cultists inside their stronghold at Twilight's Shroud. Tran'gul's notes singled him out as the leader orchestrating their presence there.",al={"who is kilgar","overlord kilgar lore","who commands twilights shroud"}},{q="Who is Da'grosh?",a="Da'grosh is a captive warrior whose fighters have regained their freedom from the cult. He seeks vengeance against Overlord Kilgar to crush the Twilight's Hammer stronghold.",al={"who is dagrosh","quest giver dagrosh","da grosh"}},{q="What is the Twilight's Shroud?",a="Twilight's Shroud is the fortress where the Twilight's Hammer cultists have established their stronghold and held prisoners.",al={"what is twilights shroud","twilight shroud location","where is the cult fortress"}},{q="Who is Tran'gul?",a="Tran'gul was an earlier quarry whose recovered notes revealed Overlord Kilgar's leadership within the fortress.",al={"who is trangul","tranguls notes","notes about kilgar"}},{q="Why does Da'grosh want Kilgar defeated?",a="With his warriors rescued and the cultists in disarray, Da'grosh wants to strike at the heart of the cult's power and avenge their captivity.",al={"why kill kilgar","why does dagrosh want his head","why defeat overlord kilgar"}},{q="Where can Overlord Kilgar be found?",a="Overlord Kilgar resides deep within the stronghold at Twilight's Shroud, behind the cult's fortified defenses.",al={"where is kilgar hiding","where to find kilgar","kilgar location"}}},ang={["class:Warrior"]="Da'grosh draws strength from his liberated warriors, calling on fellow armsmen to shatter the cult's stronghold and avenge their capture."},kw={"bring me his head","da'grosh","overlord kilgar","stronghold","tran'gul","twilight's hammer","twilight's shroud"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=94768},src={"In-game quest text: Bring Me His Head"},fv=true}
E["quest:94829"] = {t="quest",n="What We Lost",z="riverglades",s="A farmer at Elbrim's Farm mourns the people killed by Twilight Raiders. You are asked to recover their mementos and place them on the graves west of the farm.",h="A farmer at Elbrim's Farm mourns the people killed by Twilight Raiders.",sec={{t="A Farmer's Plea",b="The farmer asks you to gather the belongings of those killed when the cultists came to Elbrim's Farm. The fields once fed troops and civilians, but the farmer says the promised protection never came. Their people lie in the farm's ruins, and their kin are buried in the graveyard to the west.",sp=0},{t="At the Graves",b="The farmer wants you to bring the dead people's mementos to the graves west of Elbrim's Farm. It will not bring them back, but the farmer hopes their souls can rest with their kin.",sp=0}},faq={{q="What happened at Elbrim's Farm?",a="The farmer says cultists came to Elbrim's Farm and destroyed its crops and killed the people who worked there.",al={"elbrim farm what happened","farm destroyed","what happened here"}},{q="Who asks me to recover the mementos?",a="A farmer at Elbrim's Farm asks you to recover the belongings of the people killed by the cultists.",al={"who wants mementos","farmer request","who is asking"}},{q="Whose mementos am I collecting?",a="They belonged to the people who worked in the fields at Elbrim's Farm and were killed when the cultists came.",al={"farmers mementos","who do these belong to","mementos for who"}},{q="Where should the mementos go?",a="The farmer asks you to place the mementos on the graves in the graveyard west of Elbrim's Farm.",al={"where place mementos","which graves","graveyard location"}},{q="Why does the farmer want the mementos returned?",a="The farmer believes placing the dead people's belongings on their kin's graves will help their souls rest.",al={"why recover them","put souls to rest","why mementos"}}},kw={"cultists","elbrim's farm","farmers","farmers' mementos","graves","graveyard","twilight raiders","what we lost"},m={faction="Alliance",id=94829},src={"In-game quest text: What We Lost"},fv=true}
E["quest:94841"] = {t="quest",n="Lost Shipping Crate",z="riverglades",s="A shipping crate marked for Friz Frazzlespark has gone missing in the Riverglades. Its label asks that it be returned to Powderfuse Port.",h="A shipping crate marked for Friz Frazzlespark has gone missing in the Riverglades.",sec={{t="A Marked Crate",b="Friz Frazzlespark's crate bears a handwritten label naming Powderfuse Port in the Riverglades. A map marks a southeastern shore north of a water-surrounded temple, with winged creatures nearby. The label warns against opening the crate without supervision, and names Friz as the person to receive it.",sp=0}},faq={{q="Who owns the shipping crate?",a="The label names Friz Frazzlespark as the crate's owner.",al={"crate owner","who owns it"}},{q="Where should I take the crate?",a="The label says to return the crate to Friz Frazzlespark at Powderfuse Port in the Riverglades.",al={"where to deliver crate","crate delivery"}},{q="What does the crate's label say?",a="It identifies Friz Frazzlespark and Powderfuse Port, warns against opening the crate without supervision, and gives a return location in the Riverglades.",al={"crate label","what's written on it"}},{q="Is the crate safe to open?",a="The label says not to open it without supervision.",al={"open crate","crate warning"}}},kw={"crate","friz frazzlespark","label","lost shipping crate","map","powderfuse port","riverglades"},rel={"zone:riverglades","quest:94930"},m={id=94841},src={"In-game quest text: Lost Shipping Crate"},fv=true}
E["quest:94842"] = {t="quest",n="Unsavory Plant Food",z="riverglades",s="Halligan Turner needs ingredients for the fertilizer used by his lumber crew. You can help gather crawfish shells, manure, and Mudfin murloc heads.",h="Halligan Turner needs ingredients for the fertilizer used by his lumber crew.",sec={{t="Gathering Ingredients",b="Halligan Turner says the lumber crew makes its own fertilizer from crawfish shells, manure, and murloc heads. The manure comes from a ranch to the south, while the shells and heads lie in the river. He needs four Jumbo Crawfish Shells, four pieces of Fresh Manure, and eight Mudfin Murloc Heads before planting can begin.",sp=0}},faq={{q="What ingredients does Halligan need?",a="Halligan needs four Jumbo Crawfish Shells, four pieces of Fresh Manure, and eight Mudfin Murloc Heads.",al={"fertilizer ingredients","what does Halligan need"}},{q="What is the fertilizer made from?",a="The lumber crew's fertilizer uses crawfish shells, manure, and murloc heads in a one-to-one-to-two ratio.",al={"what's in the fertilizer","plant food ingredients"}},{q="Where does the manure come from?",a="Halligan says the manure comes from a ranch to the south.",al={"manure location","where get manure"}},{q="Where are the shells and murloc heads?",a="Halligan says you need to wade into the river for the shells and murloc heads.",al={"crawfish shells location","mudfin heads where"}},{q="Who is asking for these ingredients?",a="Halligan Turner asks for the ingredients to make fertilizer for the lumber crew.",al={"who needs plant food","Halligan Turner"}}},kw={"crawfish shells","fertilizer","fresh manure","halligan turner","jumbo crawfish shells","lumber","mudfin murloc heads","plant food"},rel={"topic:murloc"},m={faction="Alliance",id=94842},src={"In-game quest text: Unsavory Plant Food"},fv=true}
E["quest:94843"] = {t="quest",n="From Seed to Sprout",z="riverglades",s="Halligan Turner has made a planting kit from the fertilizer you supplied. He asks you to plant saplings around the lumber camp’s work sites.",h="Halligan Turner has made a planting kit from the fertilizer you supplied.",sec={{t="A New Planting",b="Halligan Turner has gathered seeds while the lumber crew works among the trees. With the fertilizer you brought, he has prepared a kit for planting them as saplings. You are asked to find places around the work sites to put them in the ground.",sp=0}},faq={{q="Who made the planting kit?",a="Halligan Turner made the planting kit using the fertilizer you supplied.",al={"who made kit","Halligan kit"}},{q="What is in the kit?",a="The kit is for planting seeds gathered from the trees and growing them into saplings.",al={"kit contents","what kit"}},{q="Where should I plant the saplings?",a="Halligan asks you to plant them around the lumber camp’s work sites.",al={"where plant","sapling spots"}},{q="Why are they planting saplings?",a="The lumber crew cuts trees and grows new ones in their place.",al={"why saplings","planting reason"}}},kw={"fertilizer","from seed to sprout","halligan turner","lumber camp","planting kit","saplings","seeds","work sites"},m={faction="Alliance",id=94843},src={"In-game quest text: From Seed to Sprout"},fv=true}
E["quest:94857"] = {t="quest",n="If a Tree Falls, and No One Hears...",z="riverglades",s="A trapped lumberjack asks you to fetch help from Turner's Logging Camp. He fears bleeding out or being eaten if he remains trapped.",h="A trapped lumberjack asks you to fetch help from Turner's Logging Camp.",sec={{t="A Call for Help",b="A lumberjack is trapped at the site of an accident. He asks you to go to Turner's Logging Camp and bring help before he bleeds out or wild animals find him.",sp=0}},faq={{q="Who is trapped?",a="A lumberjack from the nearby logging camp is trapped after an accident.",al={"trapped lumberjack","who needs help","injured worker"}},{q="What help does he need?",a="He asks you to fetch help from Turner's Logging Camp.",al={"how to help him","help trapped man","what does he need"}},{q="Why is he in danger?",a="He says he may bleed out or be eaten by wild animals if he stays trapped.",al={"why trapped","is he hurt","what happened to lumberjack"}}},kw={"accident","help","if a tree falls","logging camp","lumberjack","trapped","turner's logging camp"},m={faction="Alliance",id=94857},src={"In-game quest text: If a Tree Falls, and No One Hears..."},fv=true}
E["quest:94858"] = {t="quest",n="All That's Left",z="riverglades",s="Farmer Elbrim asks you to search the nearby barn for what remains of his family after the Twilight's Hammer attack. He hopes to bring them home to rest beside him.",h="Farmer Elbrim asks you to search the nearby barn for what remains of his family after the Twilight's Hammer...",sec={{t="A Family's Keepsakes",b="Elbrim cannot bring himself to look in the barn, where he hid those unable to defend themselves during the attack. He asks you to find his family's possessions there and bring them back. He needs to know what remains, and hopes they can be buried at home with him.",sp=0}},faq={{q="Who is asking me to search the barn?",a="Farmer Elbrim asks you to search the nearby barn for his family's possessions.",al={"who wants me at the barn","farmer elbrim","who gave this"}},{q="What happened to Elbrim's family?",a="Elbrim hid those who could not defend themselves in the barn during the Twilight's Hammer attack. He asks you to find their possessions, but does not know what remains.",al={"elbrim family","what happened at the barn","family attack"}},{q="Why did Elbrim hide them in the barn?",a="Elbrim put those unable to defend themselves in the barn because he thought they would be safe.",al={"why the barn","where did he hide them","elbrim hiding"}},{q="What does Elbrim want me to find?",a="Elbrim asks you to find his family's possessions in the nearby barn and return them to him.",al={"what am i looking for","barn things","find family stuff"}},{q="Where does Elbrim want his family buried?",a="Elbrim hopes his family can be buried at home with him.",al={"bury the family where","family burial","rest together"}}},kw={"all that's left","barn","burial","family","farmer elbrim","possessions","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Alliance",id=94858},src={"In-game quest text: All That's Left"},fv=true}
E["quest:94861"] = {t="quest",n="Helping Hands",z="riverglades",s="Hurley needs you to help save Curly, who has not returned from his lunch break. He fears there is little time to reach him.",h="Hurley needs you to help save Curly, who has not returned from his lunch break.",sec={{t="Hurley’s Concern",b="Hurley is worried because Curly did not return for lunch. He asks you to go with him and save the missing worker, and fears there is little time. Curly is a good worker despite his foolishness, and Hurley hopes he will recover and learn some sense.",sp=0}},faq={{q="Who is Curly?",a="Curly is a worker who has not returned for lunch. Hurley calls him a good worker, though he thinks Curly can be foolish.",al={"curly who","who's curly","curly backstory"}},{q="Who asks for help saving Curly?",a="Hurley asks you to go with him and save Curly.",al={"who wants help","help curly","hurley asks"}},{q="Why is Hurley worried?",a="Curly did not come back for lunch, and Hurley fears there is little time to save him.",al={"why worried","curly missing","where is curly"}},{q="What does Hurley hope for Curly?",a="Hurley hopes Curly heals well and learns some sense.",al={"curly outcome","does curly heal","curly recover"}}},kw={"curly","helping hands","hurley","lunch break","missing worker","save curly"},m={faction="Alliance",id=94861},src={"In-game quest text: Helping Hands"},fv=true}
E["quest:94877"] = {t="quest",n="Saving Sunnyglade",z="riverglades",s="Demar Brant asks you to drive Twilight's Hammer forces from Sunnyglade, a settlement in Farholde's northwest. The people there have lost their homes and receive little help from Stormwind.",h="Demar Brant asks you to drive Twilight's Hammer forces from Sunnyglade, a settlement in Farholde's northwest.",sec={{t="A Lost Settlement",b="Demar Brant speaks for Farholde's weary people, including refugees who escaped tragedy without their families. Stormwind has left them to manage with dwindling means. The Twilight's Hammer took a settlement in the northwest, and Demar asks you to clear its forces from Sunnyglade.",sp=0}},faq={{q="Who is asking for help?",a="Demar Brant asks you to drive Twilight's Hammer forces from Sunnyglade.",al={"who is Demar","Demar Brant","who gave this"}},{q="What happened to Sunnyglade?",a="The Twilight's Hammer took a settlement in Farholde's northwest.",al={"what happened here","Sunnyglade lost","who took Sunnyglade"}},{q="Who are the people in Farholde?",a="Many are refugees who escaped tragedy without their families.",al={"Farholde people","who lives there","refugees"}},{q="Why does Demar want help?",a="Farholde has lost a settlement to the Twilight's Hammer, while its people have fewer means to fend for themselves.",al={"why help Demar","why fight","what's the problem"}}},kw={"demar brant","farholde","refugees","saving sunnyglade","sunnyglade","twilight neophytes","twilight raiders","twilight shadowmancers","twilight's hammer"},rel={"subzone:sunnyglade","topic:twilight-s-hammer","topic:refugee","topic:stormwind-kingdom"},m={faction="Alliance",id=94877},src={"In-game quest text: Saving Sunnyglade"},fv=true}
E["quest:94879"] = {t="quest",n="Scraps of Knowledge",z="riverglades",s="Ashe Amberall asks you to search Sunnyglade for Twilight's Hammer documents. She hopes the pages will reveal what the cult intends.",h="Ashe Amberall asks you to search Sunnyglade for Twilight's Hammer documents.",sec={{t="Pages in Sunnyglade",b="From Farholde Keep, Ashe Amberall looks to Sunnyglade, the ruined city to the north. Demar has sent troops, yet the city remains beyond recovery. Ashe believes the Twilight's Hammer has struck before and coordinates its attacks from a central place. She asks you to look for misplaced documents in Sunnyglade, hoping enough pages will help her piece together the cult's intentions.",sp=0}},faq={{q="Who wants the Twilight Pages?",a="Ashe Amberall in Farholde Keep asks you to find the Twilight Pages.",al={"who wants the pages","Ashe pages","who asked me"}},{q="Where should I look for the pages?",a="Ashe asks you to search within Sunnyglade for Twilight Pages.",al={"where pages","Sunnyglade papers","find Twilight Pages"}},{q="What does Ashe hope to learn?",a="Ashe hopes the documents will help her piece together the Twilight's Hammer's intentions.",al={"what Ashe wants to know","why pages","Twilight plans"}},{q="Why is Ashe asking about the Twilight's Hammer?",a="Ashe believes the attack on Sunnyglade is not the Twilight's Hammer's first, and suspects the cult coordinates from a central place.",al={"why Twilight Hammer","cult attacks","what happened before"}}},kw={"ashe amberall","demar","documents","farholde keep","scraps of knowledge","sunnyglade","twilight pages","twilight's hammer"},rel={"subzone:sunnyglade","topic:twilight-s-hammer"},m={faction="Alliance",id=94879},src={"In-game quest text: Scraps of Knowledge"},fv=true}
E["quest:94881"] = {t="quest",n="Curious Trinkets",z="riverglades",s="Ashe Amberhall in Farholde Keep asks you to learn about the cult in Sunnyglade by bringing her its enchanted charms. She believes the tokens can reveal something of the cult’s magic.",h="Ashe Amberhall in Farholde Keep asks you to learn about the cult in Sunnyglade by bringing her its enchanted...",sec={{t="A Request at Farholde",b="Ashe Amberhall wants to study the cult in Sunnyglade, where magical skill earns some members favor and tokens. She believes the charms carry cultist magic. So you are asked to bring her charms taken from Twilight Shadowmancers and Twilight Neophytes.",sp=0}},faq={{q="Who is asking for the charms?",a="Ashe Amberhall, at Farholde Keep, wants to examine the cult’s charms.",al={"who wants charms","Ashe Amberhall","Ashe request"}},{q="Why does Ashe want the charms?",a="Ashe wants to learn more about the cult in Sunnyglade and believes its charms hold cultist magic.",al={"why charms","what are charms for","Ashe wants tokens"}},{q="What are Twilight Charms?",a="They are tokens given to cult members with an affinity for magic, then imbued with cultist magic.",al={"twilight charms","cult tokens","magic charms"}},{q="Who carries the charms?",a="Twilight Shadowmancers and Twilight Neophytes in Sunnyglade carry the charms Ashe seeks.",al={"where get charms","shadowmancers charms","neophyte tokens"}}},ang={["class:Druid"]="As a druid, Ashe sees you as someone who might help her investigate the cult in Sunnyglade."},kw={"ashe amberhall","cult","curious trinkets","farholde keep","sunnyglade","twilight charms","twilight neophyte","twilight shadowmancer"},rel={"subzone:sunnyglade"},m={faction="Alliance",id=94881},src={"In-game quest text: Curious Trinkets"},fv=true}
E["quest:94884"] = {t="quest",n="An Unsettling Discovery",z="riverglades",s="Claire asks you to carry samples from the cave to Ashe Amberhall at Farholde Keep. Their energy overwhelms her, and she is too weak to take them herself.",h="Claire asks you to carry samples from the cave to Ashe Amberhall at Farholde Keep.",sec={{t="A Request from the Cave",b="Claire is trapped in the cave and says she cannot carry the samples. Their power is too much for her, and she needs to rest. You are asked to bring the Filled Crystal Catalyst to Ashe Amberhall at Farholde Keep.",sp=0},{t="At Farholde Keep",b="Ashe Amberhall receives the catalyst and says Claire’s instincts were right. She believes the Twilight's Hammer did not expect such a direct response, and calls the reagents marvelous.",sp=1}},faq={{q="Who is asking me to carry the samples?",a="Claire is trapped in the cave and says she is too weak to carry the samples.",al={"who needs the samples","claire cave","who is claire"}},{q="What do I bring to Ashe Amberhall?",a="You bring the Filled Crystal Catalyst to Ashe Amberhall at Farholde Keep.",al={"what samples","filled catalyst","what do i carry"}},{q="Why can't Claire carry the samples?",a="Claire says their energy overwhelms her and that she is too weak to carry them.",al={"why can't she carry them","samples too powerful","claire too weak"}},{q="Where do I take the catalyst?",a="Take the Filled Crystal Catalyst to Ashe Amberhall at Farholde Keep.",al={"where is ashe","farholde keep delivery","where to bring it"}},{q="What does Ashe say about the reagents?",a="Ashe says Claire's instincts were right and calls the reagents marvelous.",al={"ashe's reaction","what does lady amberhall say","twilight hammer reagents"}}},kw={"an unsettling discovery","ashe amberhall","claire","farholde keep","filled crystal catalyst","reagents","samples","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Alliance",id=94884},src={"In-game quest text: An Unsettling Discovery"},fv=true}
E["quest:94885"] = {t="quest",n="Field Marshal's Log",z="riverglades",s="The Field Marshal's Log records Twilight's Hammer movements through the Riverglades. Its whereabouts may help those in Farholde understand enemy movements.",h="The Field Marshal's Log records Twilight's Hammer movements through the Riverglades.",sec={{t="The Log",b="Demar Brant in Farholde Keep is waiting for the Field Marshal's Log. Its records track Twilight's Hammer forces moving through the Riverglades, and someone in Farholde wants to see them. The author is nowhere to be found. The notes may help reveal where the enemy has been moving.",sp=0},{t="Farholde's Concern",b="Demar Brant says the notes arrived too late. Farholde already knows the dangers within Sunnyglade, and he is troubled that you have found them there too.",sp=1}},faq={{q="What is in the Field Marshal's Log?",a="The log records the comings and goings of Twilight's Hammer forces throughout the Riverglades.",al={"field marshal log","what does the log say"}},{q="Who wrote the log?",a="The author of the Field Marshal's Log is nowhere to be found.",al={"log author","who made the notes"}},{q="Who wants to see the log?",a="Someone in Farholde wants to see the log. You are asked to deliver it to Demar Brant in Farholde Keep.",al={"who gets the log","Demar Brant log"}},{q="Why does the log matter?",a="Its records of Twilight's Hammer movements may help shed light on enemy movements.",al={"why bring the log","enemy movements"}},{q="Where were the Twilight's Hammer forces moving?",a="The log records Twilight's Hammer forces throughout the Riverglades.",al={"Twilight Hammer Riverglades","where were they"}}},kw={"demar brant","enemy movements","farholde","field marshal log","field marshal's log","riverglades","sunnyglade","twilight's hammer"},rel={"zone:riverglades","subzone:sunnyglade","topic:twilight-s-hammer"},m={faction="Alliance",id=94885},src={"In-game quest text: Field Marshal's Log"},fv=true}
E["quest:94886"] = {t="quest",n="The Western Front",z="riverglades",s="Farholde's patrol has gone missing along the western borders. With Miss Amberhall's findings pointing toward a Twilight Hammer encampment, you are asked to find Sergeant Riftan near the Twilight's Shroud.",h="Farholde's patrol has gone missing along the western borders.",sec={{t="A Missing Patrol",b="A Farholde patrol vanished from the western borders, and Sergeant Riftan is among those unaccounted for. Miss Amberhall's findings raise concern that the patrol reached the Twilight Hammer's central encampment. You are asked to look for Riftan near the Twilight's Shroud to the west.",sp=0}},faq={{q="Who is missing?",a="A Farholde patrol disappeared from the western borders. Sergeant Riftan is the one you are asked to find.",al={"missing patrol","where's riftan","sergeant missing"}},{q="Where should I look for Sergeant Riftan?",a="Sergeant Riftan is near the Twilight's Shroud to the west.",al={"riftan location","find riftan","where is the sergeant"}},{q="Why is the patrol missing?",a="Miss Amberhall's findings lead Farholde to fear the patrol walked into the Twilight Hammer's central encampment.",al={"what happened to patrol","why patrol vanished","twilight hammer patrol"}},{q="Who is Miss Amberhall?",a="Miss Amberhall is the lady whose findings raise concern that the patrol reached the Twilight Hammer's central encampment.",al={"amberhall","miss amberhall info","who's amberhall"}},{q="What is happening in Sunnyglade?",a="Farholde says it can handle the cleanup in Sunnyglade itself, while you are asked to check on Sergeant Riftan.",al={"sunnyglade trouble","sunnyglade cleanup","what's in sunnyglade"}}},kw={"farholde","miss amberhall","missing patrol","sergeant riftan","sunnyglade","twilight hammer","twilight's shroud","western borders","western front"},rel={"subzone:sunnyglade"},m={faction="Alliance",id=94886},src={"In-game quest text: The Western Front"},fv=true}
E["quest:94887"] = {t="quest",n="Saving Marshal Ryan",z="riverglades",s="The Alliance needs Marshal Ryan, one of its finest scouts, found. His last reports point to a Twilight's Hammer fortress to the west, and his logbook may hold further clues.",h="The Alliance needs Marshal Ryan, one of its finest scouts, found.",sec={{t="The Missing Marshal",b="His final reports place Marshal Ryan near a Twilight's Hammer fortress to the west. You are sent to find him within the Twilight's Shroud, taking his logbook with you. The Alliance relies on his keen eye and dependable intelligence, and his reports may help reveal where he is.",sp=0}},faq={{q="Who is Marshal Ryan?",a="Marshal Ryan is one of the Alliance's best, valued for his keen eyes and reliable intelligence.",al={"marshal ryan who","who's ryan"}},{q="Where is Marshal Ryan?",a="Marshal Ryan is sought within the Twilight's Shroud, near a Twilight's Hammer fortress to the west.",al={"where ryan","find marshal ryan"}},{q="Why is Ryan missing?",a="His final reports refer to a Twilight's Hammer fortress to the west, and the Alliance has not found him.",al={"why ryan gone","what happened to marshal ryan"}},{q="Why does the Alliance want his logbook?",a="Marshal Ryan's logbook may offer clues to his whereabouts.",al={"ryan logbook why","what's in the logbook"}}},ang={["faction:Alliance"]="As an Alliance member, you are helping find Marshal Ryan, whose reports have been important to the war effort."},kw={"alliance","logbook","marshal ryan","missing marshal","saving marshal ryan","twilight's hammer","twilight's shroud"},rel={"topic:twilight-s-hammer"},m={faction="Alliance",id=94887},src={"In-game quest text: Saving Marshal Ryan"},fv=true}
E["quest:94890"] = {t="quest",n="Bring Me His Head",z="riverglades",s="Sergeant Riftan sends you back to the Twilight's Shroud, where Overlord Kilgar remains hidden in his keep. The rescued soldiers are ready to fight, and Riftan wants Kilgar brought down.",h="Sergeant Riftan sends you back to the Twilight's Shroud, where Overlord Kilgar remains hidden in his keep.",sec={{t="Back to the Keep",b="The rescued soldiers are eager to fight, and Sergeant Riftan says your strength has helped carry the assault this far. Overlord Kilgar, an orc, is hidden deep within his keep in the Twilight's Shroud. Riftan asks you to defeat him and bring back his head.",sp=0}},faq={{q="Who is Overlord Kilgar?",a="Overlord Kilgar is an orc leader hiding deep within his keep in the Twilight's Shroud.",al={"kilgar","who's kilgar","orc leader"}},{q="Why am I being sent back to the Twilight's Shroud?",a="The rescued soldiers are ready to fight, and Sergeant Riftan says the assault should continue. He asks you to return to the Twilight's Shroud and bring back Overlord Kilgar's head.",al={"why go back","twilight shroud task","what's next"}},{q="Who wants Kilgar's head?",a="Sergeant Riftan asks you to bring him Overlord Kilgar's head.",al={"riftan wants what","who asked for kilgar","bring me his head"}},{q="Where is Kilgar hiding?",a="Overlord Kilgar is hidden deep within his keep in the Twilight's Shroud.",al={"kilgar location","where's overlord","kilgar keep"}}},kw={"bring me his head","orc","overlord kilgar","rescued soldiers","sergeant riftan","twilight's shroud"},m={faction="Alliance",id=94890},src={"In-game quest text: Bring Me His Head"},fv=true}
E["quest:94891"] = {t="quest",n="News to Farholde",z="riverglades",s="Ashe Amberhall in Farholde Keep awaits your report after your work with Sergeant Riftan. Your return will show whether the venture succeeded.",h="Ashe Amberhall in Farholde Keep awaits your report after your work with Sergeant Riftan.",sec={{t="A Report for Ashe",b="Sergeant Riftan sends you back to Ashe Amberhall in Farholde Keep with a report. He gives you Kilgar's head to take with you. Ashe says she had begun to doubt her judgment while you were away, but now praises your talents.",sp=0}},faq={{q="Who wants the report?",a="Ashe Amberhall in Farholde Keep is waiting for your report.",al={"who do I report to","Ashe report","Farholde report"}},{q="What does Riftan give me?",a="Sergeant Riftan gives you Kilgar's head to take to Ashe Amberhall.",al={"what did Riftan toss back","Kilgar head","what am I carrying"}},{q="What does Ashe say when I return?",a="Ashe says she had begun to worry she misjudged your talents, then says you were right for the job.",al={"Amberhall reaction","Ashe dialogue","was Ashe worried"}},{q="What does Ashe say about Riftan?",a="Ashe asks whether Riftan is still around and says she expected you two to get along.",al={"Riftan still alive","what about Sergeant Riftan","Ashe and Riftan"}}},kw={"ashe amberhall","farholde keep","kilgar","news to farholde","report","sergeant riftan"},m={faction="Alliance",id=94891},src={"In-game quest text: News to Farholde"},fv=true}
E["quest:94892"] = {t="quest",n="Dying Wish",z="riverglades",s="Marshal Ryan is dying and asks you to carry his crest to Knight Commander Demar Brant. His final words turn toward home and Abigail.",h="Marshal Ryan is dying and asks you to carry his crest to Knight Commander Demar Brant.",sec={{t="Ryan’s Last Words",b="As Ryan’s eyes grow dull, he speaks of home and Abigail. The Marshal gives you his crest and asks you to warn Knight Commander Demar Brant. You carry the sign of his rank to Farholde Keep, where the commander awaits.",sp=0}},faq={{q="Who is dying?",a="Marshal Ryan is dying when he asks you to take his crest to Knight Commander Demar Brant.",al={"dying wish who","marshal ryan"}},{q="What does Ryan want me to do?",a="Ryan asks you to carry his crest to Knight Commander Demar Brant and warn him.",al={"ryan request","what do with crest"}},{q="Who is Abigail?",a="Ryan's final words mention Abigail and say he should have come home.",al={"abigail ryan","who's abigail"}},{q="Where do I take the crest?",a="Take Marshal Ryan's crest to Knight Commander Demar Brant in Farholde Keep.",al={"crest where","demar brant location"}}},kw={"abigail","crest","dying wish","farholde keep","knight commander demar brant","marshal ryan","ryan"},m={faction="Alliance",id=94892},src={"In-game quest text: Dying Wish"},fv=true}
E["quest:94893"] = {t="quest",n="Delivering Closure",z="riverglades",s="Demar asks you to bring Marshal Ryan’s crest to Abigail Lawson in Stormwind. Ryan’s death leaves a message for the woman he once planned to marry.",h="Demar asks you to bring Marshal Ryan’s crest to Abigail Lawson in Stormwind.",sec={{t="A Message in Stormwind",b="Abigail Lawson waits in Cathedral Square, and you carry Marshal Ryan’s crest to her for Demar. She did not join Demar and Ryan when they established Farholde Keep. Ryan and Abigail had disagreed, though Demar does not know the cause. He believes his own presence would not be welcome, so the crest must speak in his stead.",sp=0},{t="Words Left Unsaid",b="Ryan’s family died during the orc invasion, and his sense of duty against the Horde became hatred. Abigail once urged him to come live with her and her parents in Stormwind, but Ryan refused. He vowed to stay until he had driven the orcs from his home. Ryan and Abigail had not spoken since.",sp=0},{t="The Crest Received",b="When you bring the crest, Abigail speaks of Ryan’s refusal to leave his home and of their long silence. She calls Demar a hero, but warns that heroes often bring danger to those around them. Then she holds Ryan’s crest close and calls him an idiot.",sp=1}},faq={{q="Who is Abigail Lawson?",a="Abigail Lawson was Marshal Ryan’s betrothed. She lives in Stormwind City and had not joined Ryan and Demar at Farholde Keep.",al={"abigail who","who is abigail","ryan's betrothed"}},{q="Who asks me to bring Ryan’s crest?",a="Demar asks you to bring Marshal Ryan’s crest to Abigail Lawson in Stormwind City. He believes she would not welcome his presence.",al={"who sent me","demar crest","who wants the crest delivered"}},{q="Why did Ryan stay behind?",a="After Ryan’s family was killed during the orc invasion, his duty against the Horde became hatred. He vowed to remain until he had driven the orcs from his home.",al={"why ryan stayed","ryan and the orcs","his family"}},{q="Why did Abigail and Ryan stop speaking?",a="Abigail and Ryan had a disagreement, but Demar does not know its specifics. They had not spoken since.",al={"why they stopped talking","abigail and ryan","their disagreement"}},{q="What is Ryan’s crest for?",a="Demar asks you to bring Marshal Ryan’s crest to Abigail Lawson in Cathedral Square, Stormwind City.",al={"marshal crest","ryan's crest","what do i bring"}}},kw={"abigail lawson","cathedral square","delivering closure","demar","farholde keep","marshal ryan","ryan's crest","stormwind"},rel={"subzone:cathedral-square","zone:stormwind","topic:stormwind-kingdom","topic:horde"},m={faction="Alliance",id=94893},src={"In-game quest text: Delivering Closure"},fv=true}
E["quest:94894"] = {t="quest",n="The Twilight Threat",z="riverglades",s="Farholde seeks Stormwind's help against a sudden rise in Twilight's Hammer activity. You carry evidence to Bolvar Fordragon, though the Alliance has other wars to reckon with.",h="Farholde seeks Stormwind's help against a sudden rise in Twilight's Hammer activity.",sec={{t="Farholde's Plea",b="Farholde's people turn to you after Lady Amberhall hears of your dealings with the Twilight's Hammer. Their campaign began to drive the Horde from their homeland, but cultist activity has sharply increased. They fear Stormwind will not answer their pleas before Farholde faces enemies on two fronts. You carry evidence to Bolvar Fordragon in Stormwind Keep.",sp=0},{t="Stormwind's Answer",b="In Stormwind Keep, Bolvar Fordragon hears the warning from Farholde. He says the Alliance is already at war on a much wider scale and cannot spend its strength on one hamlet's private feud. More homes have been razed by the Horde than those in the Riverglades. Bolvar sees little hope that Brant will set aside his pride and bring his cavalry to the Alliance's aid.",sp=1}},faq={{q="Who asks for Stormwind's help?",a="Farholde asks Stormwind for help as Twilight's Hammer activity rises.",al={"who wants help","farholde plea","who sent me"}},{q="Why is Farholde worried?",a="Farholde fears it will be overwhelmed by enemies on two fronts if Stormwind does not hear its pleas.",al={"what's wrong in farholde","cultist problem","why worried"}},{q="What evidence do I carry?",a="You carry Kilgar's Head to Bolvar Fordragon in Stormwind Keep.",al={"what evidence","kilgar head","head delivery"}},{q="Who is Bolvar hearing from?",a="Bolvar Fordragon receives news from Farholde, whose campaign began to remove the Horde from its homeland.",al={"who sent the news","farholde report","bolvar question"}},{q="Why can't Stormwind support Farholde?",a="Bolvar says the Alliance is fighting on a much larger scale and lacks the resources to support Farholde's personal feud.",al={"why no help","stormwind support","bolvar refuses"}}},ang={["faction:Alliance"]="As an Alliance adventurer, you carry Farholde's evidence to Bolvar Fordragon while its people seek aid against the Twilight's Hammer and the Horde."},kw={"bolvar fordragon","brant","farholde","horde","kilgar","riverglades","stormwind keep","twilight's hammer"},rel={"npc:bolvar-fordragon","topic:twilight-s-hammer","zone:riverglades","zone:stormwind","subzone:stormwind-keep","topic:alliance","topic:horde"},m={faction="Alliance",id=94894},src={"In-game quest text: The Twilight Threat"},fv=true}
E["quest:94895"] = {t="quest",n="Lost Shipping Crate",z="riverglades",s="Friz Frazzlespark's shipping crate has gone missing from Powderfuse Port in the Riverglades. Its label warns against opening it without supervision, and you are asked to return it to Friz.",h="Friz Frazzlespark's shipping crate has gone missing from Powderfuse Port in the Riverglades.",sec={{t="A Marked Crate",b="A map and a warning mark the crate you carry through the Riverglades. Its label names Friz Frazzlespark and Powderfuse Port, and asks that the crate be returned there if lost. You are bringing it back to its owner.",sp=0}},faq={{q="Who owns the shipping crate?",a="The label names Friz Frazzlespark as the owner of the shipping crate.",al={"crate owner","who owns this","friz crate"}},{q="Where should I take the crate?",a="The crate is to be returned to Friz Frazzlespark at Powderfuse Port in the Riverglades.",al={"where to return crate","crate destination","powderfuse port"}},{q="What does the label warn about?",a="The label warns against tampering and says not to open the crate without supervision.",al={"crate warning","can I open it","open crate"}},{q="What is marked on the crate's map?",a="The map shows a red circle along a southeastern shoreline, north of a poorly drawn temple surrounded by water and winged creatures.",al={"crate map","what's on map","red circle map"}}},kw={"crate label","crate map","friz frazzlespark","lost shipping crate","powderfuse port","riverglades","warning"},rel={"quest:94930","zone:riverglades"},m={id=94895},src={"In-game quest text: Lost Shipping Crate"},fv=true}
E["quest:94907"] = {t="quest",n="A Small Favor",z="riverglades",s="A druid is asked to bring Twilight's Hammer magic to its source in the Twilight Shroud. Amberhall wants a cult thrall captured for questioning.",h="A druid is asked to bring Twilight's Hammer magic to its source in the Twilight Shroud.",sec={{t="A Druid's Favor",b="Amberhall asks you for help in the Twilight Shroud. The reagents you gathered are attuned to Twilight's Hammer magic, and Amberhall says they can be used in a summoning ritual. To reach the source of that power, you are asked to use a conduit to call a cult thrall and capture it with Amberhall's Soulstone.",sp=0}},faq={{q="What does Amberhall want me to do?",a="Amberhall asks you to summon a Twilight's Thrall from a conduit in the Twilight Shroud and capture it with Amberhall's Soulstone.",al={"amberhall favor","small favor","what do i do"}},{q="Why are the reagents useful?",a="The reagents are attuned to Twilight's Hammer magic, making them suitable for a summoning ritual.",al={"reagents for what","why reagents","twilight magic reagents"}},{q="Where do I use the conduit?",a="The conduit is within the Twilight Shroud.",al={"conduit location","where summon thrall","twilight shroud conduit"}},{q="Why capture the thrall?",a="Amberhall wants the Twilight's Thrall captured for questioning.",al={"why soulstone","capture thrall why","thrall questioning"}}},ang={["class:Druid"]="As a druid, you are the one Amberhall calls a good little druid before asking for this favor."},kw={"a small favor","amberhall","conduit","druid","reagents","soulstone","summoning ritual","twilight shroud","twilight's hammer","twilight's thrall"},rel={"topic:druid","topic:twilight-s-hammer"},m={faction="Alliance",id=94907},src={"In-game quest text: A Small Favor"},fv=true}
E["quest:94923"] = {t="quest",n="Hats Off",z="riverglades",s="Robbie asks you to find the birthday hat he lost by the river near the murlocs. He fears his family will learn he went there.",h="Robbie asks you to find the birthday hat he lost by the river near the murlocs.",sec={{t="A Lost Hat",b="Robbie lost the hat his sister gave him for his birthday while playing by the river. He is not allowed near the murlocs, so he cannot ask his father or Ellie to help. He suspects one of the murlocs found the hat. You are asked to look for it somewhere along the river.",sp=0}},faq={{q="Who is Robbie?",a="Robbie is a boy who lost the birthday hat his sister gave him while playing by the river.",al={"robbie","who's robbie"}},{q="What did Robbie lose?",a="Robbie lost a hat his sister gave him for his birthday.",al={"robbie's hat","lost hat"}},{q="Where did Robbie lose his hat?",a="Robbie lost his hat while playing in the river and asks you to look somewhere along the river near the murlocs.",al={"hat location","where's the hat"}},{q="Why can't Robbie ask his family for help?",a="Robbie is not allowed near the murlocs, and asking his father or Ellie for help would reveal where he had been.",al={"why not ask dad","why hide it"}},{q="Does Robbie know if a murloc took the hat?",a="Robbie guesses that one of the murlocs found and kept his hat.",al={"murloc hat","did murlocs take it"}}},kw={"birthday hat","ellie","hat","lost hat","murlocs","river","robbie"},rel={"topic:murloc"},m={faction="Alliance",id=94923},src={"In-game quest text: Hats Off"},fv=true}
E["quest:94924"] = {t="quest",n="Hunting the Hunters",z="riverglades",s="Watcher Cornelius asks you to stop Rog'mar Poachers in the Riverglades. They kill people and animals, threatening all life on the plains.",h="Watcher Cornelius asks you to stop Rog'mar Poachers in the Riverglades.",sec={{t="Poachers on the Plains",b="Rog'mar Poachers roam the Riverglades in packs, and Watcher Cornelius asks you to confront them. They kill men, lions, and horses, making them a threat to all life in the plains. Their hunting leaves no creature safe.",sp=0}},faq={{q="Who asks me to stop the poachers?",a="Watcher Cornelius asks you to stop the Rog'mar Poachers.",al={"who sent me","Cornelius request"}},{q="Who are the Rog'mar Poachers?",a="They are orcish hunters who roam the Riverglades in packs.",al={"rogmar","the poachers"}},{q="Why are the poachers a threat?",a="They kill men, lions, and horses, threatening all life in the Riverglades.",al={"why stop poachers","poacher danger"}},{q="Where do the poachers roam?",a="The Rog'mar Poachers roam the plains of the Riverglades.",al={"poachers location","where rogmar"}}},kw={"hunting the hunters","orcish poachers","poachers","riverglades","rog'mar poachers","watcher cornelius"},rel={"zone:riverglades"},m={faction="Alliance",id=94924},src={"In-game quest text: Hunting the Hunters"},fv=true}
E["quest:94925"] = {t="quest",n="A Fur Trade",z="riverglades",s="Watcher Terral seeks lion hides for Farholde’s trade with a dealer at Powderfuse Port. In return, the settlement receives specialty munitions.",h="Watcher Terral seeks lion hides for Farholde’s trade with a dealer at Powderfuse Port.",sec={{t="Farholde’s Trade",b="Farholde relies on trade for some goods, though it prizes its independence. Watcher Terral says the settlement has arranged an exchange with a dealer at Powderfuse Port. Farholde supplies goods that are dangerous to acquire, and the dealer provides specialty munitions. Now the dealer wants lion fur, and Terral asks you to bring eight Prized Lion Hides from the pride atop a large hill in the center of the plains.",sp=0}},faq={{q="What does Watcher Terral need?",a="Watcher Terral needs eight Prized Lion Hides for Farholde’s trade with a dealer at Powderfuse Port.",al={"what does Terral want","Terral hides","lion fur"}},{q="Who is Farholde trading with?",a="Farholde has arranged an exchange with a dealer at Powderfuse Port.",al={"who is the dealer","Powderfuse Port trade","fur trade dealer"}},{q="What does Farholde get in the trade?",a="The dealer provides Farholde with specialty munitions.",al={"what are the munitions for","specialty munitions","what does the dealer provide"}},{q="Where are the lions?",a="A pride of lions lives atop a large hill in the center of the plains.",al={"lion hill","where is the pride","lions in the plains"}}},kw={"a fur trade","dealer","farholde","lion fur","powderfuse port","prized lion hides","specialty munitions","watcher terral"},m={faction="Alliance",id=94925},src={"In-game quest text: A Fur Trade"},fv=true}
E["quest:94928"] = {t="quest",n="A Few Furs for Friz",z="riverglades",s="Cornelius asks you to carry lion hides to Friz Frazzlespark at Powderfuse Port. The trade is arranged, and Friz is to receive the bundle.",h="Cornelius asks you to carry lion hides to Friz Frazzlespark at Powderfuse Port.",sec={{t="A Port Delivery",b="At Powderfuse Port, Friz Frazzlespark is waiting for a bundle of lion hides. Cornelius has already arranged the trade. Deliver the hides to Friz and tell her they come from Cornelius.",sp=0}},faq={{q="Who are the hides for?",a="The bundle of lion hides is for Friz Frazzlespark at Powderfuse Port.",al={"who gets the furs","friz hides","deliver hides to who"}},{q="Where is Powderfuse Port?",a="Powderfuse Port is a goblin-run port to the northeast.",al={"where's powderfuse","powderfuse location","goblin port where"}},{q="Who sent the hides?",a="The hides are from Cornelius.",al={"who sent furs","cornelius hides","where from"}},{q="What kind of hides are they?",a="They are lion hides.",al={"what furs","lion hides","which hides"}}},kw={"a few furs for friz","cornelius","friz frazzlespark","goblin port","lion hides","powderfuse port"},rel={"topic:goblin"},m={faction="Alliance",id=94928},src={"In-game quest text: A Few Furs for Friz"},fv=true}
E["quest:94930"] = {t="quest",n="Lost Shipping Crate",z="riverglades",s="Friz Frazzlespark’s shipping crate is marked for return to Powderfuse Port in the Riverglades. Its label warns against opening it without supervision.",h="Friz Frazzlespark’s shipping crate is marked for return to Powderfuse Port in the Riverglades.",sec={{t="A Marked Crate",b="A handwritten label marks the crate as Friz Frazzlespark’s property in Powderfuse Port. It warns you not to tamper with or open the crate without supervision. If you find it lost, the label names Friz at Powderfuse Port in the Riverglades as its destination.",sp=0}},faq={{q="Who owns the crate?",a="The label identifies Friz Frazzlespark as the owner.",al={"crate owner","who is Friz","Friz crate"}},{q="Where should the crate go?",a="The label says to return the crate to Friz Frazzlespark at Powderfuse Port in the Riverglades.",al={"crate location","where return crate","Powderfuse Port crate"}},{q="Can I open the crate?",a="The label warns against opening the crate without supervision.",al={"open crate","what's inside","crate warning"}},{q="What does the map on the crate show?",a="The map has a large red circle along a southeastern shoreline, north of a water-surrounded temple and some winged creatures.",al={"crate map","red circle map","what's on label"}}},kw={"crate label","friz frazzlespark","lost shipping crate","powderfuse port","red circle map","riverglades"},rel={"zone:riverglades"},m={id=94930},src={"In-game quest text: Lost Shipping Crate"},fv=true}
E["quest:94931"] = {t="quest",n="Stolen Saws",z="riverglades",s="At the lumber mill, Halligan Turner asks you to recover saw blades stolen by gnolls. The mill needs them back.",h="At the lumber mill, Halligan Turner asks you to recover saw blades stolen by gnolls.",sec={{t="Missing Blades",b="Southern Watch keeps most gnolls away, but a few still slip into the camp at night and steal saw blades. Halligan Turner at the lumber mill asks you to look for them in the gnoll camps in Bristle Hills, where the blades may be kept. The lumber mill needs the sharp metal returned.",sp=0}},faq={{q="Who wants the saw blades back?",a="Halligan Turner at the lumber mill wants the stolen saw blades returned.",al={"who asked for saw blades","Halligan Turner saws"}},{q="Where were the saw blades stolen from?",a="A few gnolls get past Southern Watch and sneak into the lumber camp at night to take them.",al={"where did gnolls steal saws","stolen saws where"}},{q="Where might the gnolls keep the blades?",a="The gnoll camps in Bristle Hills are where the blades may be stashed.",al={"gnoll saw blade camps","where are the saws"}},{q="Why are the saw blades useful to the gnolls?",a="The gnolls likely use the sharp metal to make weapons.",al={"what do gnolls do with saws","gnolls making weapons"}},{q="Why does the lumber mill need the blades?",a="Halligan says returning the blades would save the lumber mill time and resources.",al={"why recover saw blades","mill needs saws"}}},kw={"bristle hills","gnolls","halligan turner","lumber mill","saw blades","southern watch","stolen saws"},rel={"topic:gnoll"},m={faction="Alliance",id=94931},src={"In-game quest text: Stolen Saws"},fv=true}
E["quest:94961"] = {t="quest",n="Biting the Hand",z="riverglades",s="Fuzzle offers trade to anyone who helps him get revenge. He promises to show you treasure once you bring him Twilight Finger Bones.",h="Fuzzle offers trade to anyone who helps him get revenge.",sec={{t="Fuzzle's Offer",b="Fuzzle waves a bit of gold at you as he offers a bargain. The gnoll promises more treasure if you help him get revenge. He asks you to bring him twenty Twilight Finger Bones before he shows you what he has.",sp=0}},faq={{q="Who is Fuzzle?",a="Fuzzle is a gnoll who offers you gold and promises treasure in exchange for help getting revenge.",al={"fuzzle","gnoll with gold"}},{q="What does Fuzzle want?",a="Fuzzle asks you to bring him twenty Twilight Finger Bones to help him get revenge.",al={"what does he want","fuzzle revenge"}},{q="What are the Twilight Finger Bones for?",a="Fuzzle wants twenty Twilight Finger Bones before he shows you his treasure.",al={"finger bones","twilight bones"}}},kw={"biting the hand","fuzzle","gnoll","revenge","treasure","twilight finger bones"},rel={"topic:gnoll"},m={id=94961},src={"In-game quest text: Biting the Hand"},fv=true}
E["quest:94962"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="A fight with Bonegnaw is the next bout toward becoming champion in the Bloodmaster's Ring. The ogres are waiting to see whether you can give them a battle worth watching.",h="A fight with Bonegnaw is the next bout toward becoming champion in the Bloodmaster's Ring.",sec={{t="The Next Bout",b="Your wins have not made you a champion yet, and the ring's goblin has another battle in mind. Bonegnaw is your opponent, and the goblin promises a surprise. The ogres are watching, and the next bout is meant to entertain them.",sp=0},{t="After the Fight",b="The goblin is displeased with how the bout reflects on him. The ogres, however, seem entertained, and he warns you against taking pride in the outcome.",sp=1}},faq={{q="Who is my opponent?",a="Bonegnaw is your opponent in the Bloodmaster's Ring.",al={"bonegnaw fight","who do i fight"}},{q="Am I a champion yet?",a="The ring's goblin says your wins have not made you a champion yet.",al={"bloodmaster champ","become champion"}},{q="Who is watching the fight?",a="Ogres are watching the bout in the Bloodmaster's Ring.",al={"ogres watching","who is entertained"}}},kw={"bloodmaster","bloodmaster's ring","bonegnaw","bout","champion","fight","ogres"},rel={"quest:94733"},m={faction="Horde",id=94962},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:94963"] = {t="quest",n="Biting the Hand",z="riverglades",s="Fuzzle asks you to leave with him and promises a reward once you are safe. He snarls as any would-be pursuers are threatened.",h="Fuzzle asks you to leave with him and promises a reward once you are safe.",sec={{t="Leaving with Fuzzle",b="Fuzzle is ready to leave, and he asks you to go with him. He warns that anyone who tries to stop you will be torn to shreds. Your safety comes first; he promises a reward once you are clear.",sp=0}},faq={{q="Who is asking me to leave?",a="Fuzzle asks you to leave with him.",al={"who is fuzzle","fuzzle?","who wants to leave"}},{q="What does Fuzzle threaten?",a="Fuzzle threatens to tear apart anyone who tries to stop you.",al={"what does fuzzle say","fuzzle threat","who will he attack"}},{q="When will Fuzzle give me a reward?",a="Fuzzle says he will give you a reward once you are safe.",al={"fuzzle reward","when reward","what does he promise"}},{q="What is the reward?",a="Fuzzle has amassed a hefty sum of gold, which becomes yours.",al={"what do i get","fuzzle gold","reward from fuzzle"}}},kw={"biting the hand","fuzzle","gnoll","gold","leave","reward","safe"},rel={"topic:gnoll"},m={id=94963},src={"In-game quest text: Biting the Hand"},fv=true}
E["quest:94964"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="A ring announcer calls for you to face Mog’thar in the Bloodmaster’s Ring. The crowd is waiting for its next contender.",h="A ring announcer calls for you to face Mog’thar in the Bloodmaster’s Ring.",sec={{t="The Next Contender",b="The announcer has kept the crowd excited and now presents Mog’thar as the next contender. You are called into the Bloodmaster’s Ring, with the crowd waiting to see what happens.",sp=0}},faq={{q="Who do I face in the Bloodmaster’s Ring?",a="You are called to face Mog’thar in the Bloodmaster’s Ring.",al={"mog’thar fight","who is next contender","bloodmaster ring opponent"}},{q="What does the announcer say about Mog’thar?",a="The announcer says Mog’thar is no joke.",al={"mog’thar who","next contender","is mog’thar a joke"}},{q="Why am I being sent into the ring?",a="The announcer wants to keep the crowd’s excitement going by presenting another contender.",al={"why fight mog’thar","ring fight reason","what does announcer want"}}},kw={"announcer","bloodmaster’s ring","contender","crowd","mog’thar","ring"},rel={"quest:94668"},m={faction="Horde",id=94964},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:94965"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="The goblin Jezap asks you to prove yourself to the ogres by facing Snufflesnout in the Bloodmaster's Ring. Her favorite treat will draw her into the fight, though Chub'chob may not take kindly to the result.",h="The goblin Jezap asks you to prove yourself to the ogres by facing Snufflesnout in the Bloodmaster's Ring.",sec={{t="A Test for You",b="Jezap sets out a treat before you enter the Bloodmaster's Ring. Snufflesnout is fond of it, and the sight of it rouses her. Your trial is to face Chub'chob's companion while proving yourself to the ogres.",sp=0},{t="After the Fight",b="Chub'chob's companion is Snufflesnout, and defeating her leaves a mess between you and the ogres. Take care around them now.",sp=1}},faq={{q="Who is Snufflesnout?",a="Snufflesnout is Chub'chob's companion and is fond of a particular treat.",al={"snufflesnout","snuffle snout","chubchob's pet"}},{q="Why is there a treat?",a="Jezap uses Snufflesnout's favorite treat to draw her into the Bloodmaster's Ring.",al={"snufflesnout treat","what's the treat for","feed snufflesnout"}},{q="What is the Bloodmaster's Ring?",a="It is the ring where you face Snufflesnout to prove yourself to the ogres.",al={"bloodmaster ring","the ring","where do i fight snufflesnout"}},{q="Why am I fighting Snufflesnout?",a="Jezap says proving yourself to the ogres matters above all, and facing Snufflesnout is your trial.",al={"snufflesnout fight","why fight her","prove myself to ogres"}}},kw={"bloodmaster ring","bloodmaster's ring","chub'chob","ogres","snufflesnout","treat"},rel={"quest:94733","quest:94668"},m={faction="Horde",id=94965},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:94968"] = {t="quest",n="Eye of Mugg",z="riverglades",s="Krom'rosh sends you into Krol'dok Stronghold as the Twilight cult's foothold proves larger than expected. He asks for proof that their leader is dead.",h="Krom'rosh sends you into Krol'dok Stronghold as the Twilight cult's foothold proves larger than expected.",sec={{t="Krol'dok Stronghold",b="Krom'rosh fears more allies will be sacrificed if the Twilight cult keeps ravaging these lands. Few who entered the cave survived, and the cult's foothold is larger than he believed. Now you are to enter Krol'dok Stronghold and return with proof of the leader's death.",sp=0}},faq={{q="Who is asking me to enter Krol'dok Stronghold?",a="Krom'rosh sends you into Krol'dok Stronghold to bring back proof that the Twilight cult's leader is dead.",al={"who sent me","Krom'rosh request"}},{q="What is wrong at the stronghold?",a="The Twilight cult has a larger foothold than Krom'rosh expected and has been ravaging the lands and sacrificing allies.",al={"what's happening there","Twilight cult problem"}},{q="Why does Krom'rosh want me to go in?",a="Krom'rosh wants the cult stopped before it can continue ravaging the lands and sacrificing allies.",al={"why go inside","why enter stronghold"}},{q="What proof does Krom'rosh ask for?",a="He asks for proof that the Twilight cult's leader is dead.",al={"proof needed","what do I bring back"}},{q="Did many who entered the cave survive?",a="Few who managed to enter the cave survived.",al={"cave survivors","who made it out"}}},kw={"cave","cult leader","eye of mugg","krol'dok stronghold","krom'rosh","sacrifices","twilight cult"},m={faction="Horde",id=94968},src={"In-game quest text: Eye of Mugg"},fv=true}
E["quest:94972"] = {t="quest",n="Tome of Twilight",z="riverglades",s="At Krol'dok Stronghold, you are asked to recover the Tome of Twilight. Its contents may aid the fight against the cultists.",h="At Krol'dok Stronghold, you are asked to recover the Tome of Twilight.",sec={{t="A Hidden Record",b="The stronghold’s secrets may hold useful knowledge about the cultists. You are asked to search Krol'dok Stronghold and recover the Tome of Twilight, so its information can be brought back.",sp=0}},faq={{q="What am I looking for?",a="You are asked to recover the Tome of Twilight from Krol'dok Stronghold.",al={"tome of twilight","what tome","which book"}},{q="Why does the tome matter?",a="The tome may contain information useful in the fight against the cultists.",al={"why get tome","what's it for","cultist info"}},{q="Where is the Tome of Twilight?",a="The Tome of Twilight is to be recovered from Krol'dok Stronghold.",al={"where tome","kroldok tome","stronghold book"}}},kw={"cultists","information","krol'dok stronghold","secrets","tome of twilight"},m={faction="Horde",id=94972},src={"In-game quest text: Tome of Twilight"},fv=true}
E["quest:94973"] = {t="quest",n="Krol'dok Moulding",z="riverglades",s="A moulding found near Rog'mar appears to be part of a key. Someone in the settlement may know what it opens.",h="A moulding found near Rog'mar appears to be part of a key.",sec={{t="A Curious Mould",b="You have a moulding that seems made for a key. In Rog'mar, someone may know what the piece is for. If it came from the stronghold, it may be important.",sp=0}},faq={{q="What is the moulding for?",a="The moulding appears to be for a key.",al={"mould piece","what is this mould","key mould"}},{q="Who can identify the moulding?",a="Someone in Rog'mar may know about the mould.",al={"who knows about the mould","ask about mould","where to take mould"}},{q="Why might it matter?",a="If the moulding is from the stronghold, it must be important.",al={"is the mould important","stronghold mould","why care about mould"}}},kw={"key","krol'dok moulding","mould","moulding","rog'mar","stronghold"},m={faction="Horde",id=94973},src={"In-game quest text: Krol'dok Moulding"},fv=true}
E["quest:94974"] = {t="quest",n="Key Ingredients",z="riverglades",s="Kreza Darkthorn needs leather and iron for a key moulding. You gather the materials while she keeps the embers hot.",h="Kreza Darkthorn needs leather and iron for a key moulding.",sec={{t="Materials for the Moulding",b="Kreza Darkthorn has a worn moulding that may be used to fashion a key. You bring her four Thick Leather and twelve Iron Bar while she keeps the embers hot. The moulding should hold, and Kreza is ready to see what can be done.",sp=0}},faq={{q="What does Kreza need?",a="Kreza asks you to bring four Thick Leather and twelve Iron Bar.",al={"what materials","key ingredients","kreza needs what"}},{q="What are the materials for?",a="The materials are for fashioning a key from a crude, worn moulding.",al={"why leather and iron","key for what","moulding materials"}},{q="Who is keeping the embers hot?",a="Kreza Darkthorn says she will keep the embers hot while you gather the materials.",al={"who tends embers","kreza embers","embers hot"}},{q="What does Kreza say about the moulding?",a="Kreza says the moulding is crude and worn, but may still be used to fashion a key.",al={"moulding condition","is moulding usable","key mould"}}},kw={"embers","iron bar","key","key ingredients","kreza darkthorn","moulding","thick leather"},m={faction="Horde",id=94974},src={"In-game quest text: Key Ingredients"},fv=true}
E["quest:94975"] = {t="quest",n="A Token of Vengeance",z="riverglades",s="An ally asks you to find the Twilight’s Hammer hiding in a cave network near Krol'dok Stronghold. Their attacks have hurt your allies and threaten the land.",h="An ally asks you to find the Twilight’s Hammer hiding in a cave network near Krol'dok Stronghold.",sec={{t="The Hidden Caves",b="The scouts have reported Twilight’s Hammer cultists moving beneath the rugged ground near Krol'dok Stronghold. Your ally says their attacks have caused great pain to your allies and that the cultists are claiming the land. You are asked to find their hiding place and bring back fifteen cultist ears as a message of vengeance.",sp=0}},faq={{q="Who am I looking for?",a="You are looking for Twilight’s Hammer cultists hiding in a cave network near Krol'dok Stronghold.",al={"who are the cultists","twilight hammer here","cultist ears"}},{q="Why are the cultists being hunted?",a="The giver says the cultists have inflicted pain on their allies and are claiming the land.",al={"why vengeance","why fight them","what did they do"}},{q="What do the scouts know?",a="Scouts reported cultist movement beneath the rugged terrain, in a hidden cave network to the north.",al={"scouts report","where are cultists","cultist movements"}},{q="What am I asked to bring back?",a="You are asked to collect fifteen Cultist Ears from the Twilight’s Hammer at Krol'dok Stronghold.",al={"what do i collect","ears quest","how many ears"}}},kw={"a token of vengeance","cultist ears","cultists","hidden cave","krol'dok stronghold","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=94975},src={"In-game quest text: A Token of Vengeance"},fv=true}
E["quest:94980"] = {t="quest",n="Krol'dok Moulding",z="riverglades",s="The Krol'dok moulding looks as though it belongs to a key. Someone in Farholde Keep may know more about it.",h="The Krol'dok moulding looks as though it belongs to a key.",sec={{t="A Key's Mould",b="You have a moulding that appears to be for a key. Someone in Farholde Keep may know what the mould is for, and you bring it to them to learn more.",sp=0}},faq={{q="What is the Krol'dok moulding?",a="The Krol'dok moulding appears to be for a key.",al={"kroldok moulding","krol'dok mold","what is this mould"}},{q="Who might know about the mould?",a="Someone in Farholde Keep may know about the mould.",al={"who knows about the mould","mould expert","ask about mould"}},{q="What happens when I bring the moulding?",a="The person you bring it to says they will see what can be done with it.",al={"moulding outcome","what do they say","key mould"}}},kw={"farholde keep","key","krol'dok moulding","mould","moulding"},m={faction="Alliance",id=94980},src={"In-game quest text: Krol'dok Moulding"},fv=true}
E["quest:94981"] = {t="quest",n="Key Ingredients",z="riverglades",s="Alphonse Dumas needs materials to fashion a key from a crude moulding. You are asked to bring him Thick Leather and Iron Bars.",h="Alphonse Dumas needs materials to fashion a key from a crude moulding.",sec={{t="Materials for the Key",b="Alphonse Dumas keeps the embers hot while you gather what he needs. The moulding is crude, but the right materials may let him fashion a key.",sp=0}},faq={{q="What does Alphonse need?",a="Alphonse Dumas asks you to bring four Thick Leather and twelve Iron Bars.",al={"materials needed","what do I bring","key ingredients"}},{q="What is Alphonse making?",a="Alphonse hopes to fashion a key from a crude moulding using the right materials.",al={"what is he crafting","what is the key for","key moulding"}},{q="Where do I take the materials?",a="Bring the Thick Leather and Iron Bars to Alphonse Dumas.",al={"who gets the ingredients","bring materials to whom"}}},kw={"alphonse dumas","embers","iron bars","key","key ingredients","moulding","thick leather"},m={faction="Alliance",id=94981},src={"In-game quest text: Key Ingredients"},fv=true}
E["quest:94982"] = {t="quest",n="Eye of Mugg",z="riverglades",s="Commander Brant asks you to find the Twilight presence in Krol'dok Stronghold and bring back proof of its leader's death. The caves hold a threat to efforts to drive the Twilight from these lands.",h="Commander Brant asks you to find the Twilight presence in Krol'dok Stronghold and bring back proof of its...",sec={{t="The Hidden Caves",b="Commander Brant has heard that scouts found caves northwest along the mountains, concealed by their natural surroundings. Many who went inside to learn more have not returned, and Brant fears they are lost. Watchers have also seen Twilight figures entering and leaving the caves in darkness. You are asked to locate the stronghold and return with proof of its leader's demise.",sp=0}},faq={{q="Who sends me to Krol'dok Stronghold?",a="Commander Brant asks you to locate the Twilight stronghold and return with proof of its leader's death.",al={"who is commander brant","brant sent me","who gave this quest"}},{q="Where is Krol'dok Stronghold?",a="The caves are northwest along the mountains, hidden by natural surroundings.",al={"where is krol'dok","kroldok location","where are the caves"}},{q="Why is Commander Brant concerned about the caves?",a="Many who went into the caves seeking information have not returned, and Brant fears they may be lost.",al={"why find the caves","what's wrong there","missing scouts"}},{q="Who has been seen near the caves?",a="Watchers have reported a Twilight presence moving in and out of the caves, often in darkness.",al={"twilight in caves","who is in krol'dok","twilight presence"}},{q="What does Brant ask me to bring back?",a="Brant asks you to return with proof that the stronghold's leader is dead.",al={"what proof do i need","leader proof","what to return with"}}},kw={"caves","commander brant","eye of mugg","krol'dok stronghold","missing scouts","mountains","twilight"},m={faction="Alliance",id=94982},src={"In-game quest text: Eye of Mugg"},fv=true}
E["quest:94983"] = {t="quest",n="Twilight Mementos",z="riverglades",s="Sergeant Riftan sends you north to Krol'dok Stronghold after scouts confirm a Twilight's Hammer hideout. He asks you to bring back proof of the cultists' defeat.",h="Sergeant Riftan sends you north to Krol'dok Stronghold after scouts confirm a Twilight's Hammer hideout.",sec={{t="Scouts' Reports",b="Scouts have brought Sergeant Riftan grim accounts of a cultist hideout. Their reports confirm what others have said. A cave lies north, concealed by its surroundings, and Riftan believes it gives the cult a foothold deep in the mountains. He sends you to Krol'dok Stronghold to bring back proof that the Twilight's Hammer cultists have been defeated.",sp=0}},faq={{q="Who is asking me to go north?",a="Sergeant Riftan asks you to seek out the Twilight's Hammer cultists at Krol'dok Stronghold and return with proof of their defeat.",al={"who sent me","sergeant riftan"}},{q="What did the scouts find?",a="The scouts' accounts confirmed reports of a cultist hideout, with a concealed cave to the north.",al={"scouts report","what did they discover"}},{q="Where is the hideout?",a="The hideout is in a cave to the north, concealed by its surroundings. Riftan believes it is a foothold deep in the mountains.",al={"cultist cave","where are cultists"}},{q="What proof does Riftan want?",a="Riftan asks you to bring back proof that the cultists at Krol'dok Stronghold have been defeated.",al={"what proof","cultist proof"}},{q="Who are the cultists?",a="They are members of the Twilight's Hammer, whose hideout has been confirmed by the scouts' reports.",al={"twilight cult","twilights hammer"}}},kw={"cave","cultist bangles","cultist hideout","krol'dok stronghold","scouts","sergeant riftan","twilight mementos","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Alliance",id=94983},src={"In-game quest text: Twilight Mementos"},fv=true}
E["quest:94984"] = {t="quest",n="Tome of Twilight",z="riverglades",s="The Twilight forces persist, and a clue points north of Sunnyglade. You are asked to find Nar'gurk and recover information from his stronghold.",h="The Twilight forces persist, and a clue points north of Sunnyglade.",sec={{t="A Trail North",b="The Twilight forces still come from somewhere unknown, so you are sent to Krol'dok Stronghold. A Twilight creature mentioned shadow magic and an ogre named Nar'gurk there. You are asked to kill him and recover any valuable information that may explain where the forces come from.",sp=0}},faq={{q="What am I looking for?",a="You are looking for Nar'gurk in Krol'dok Stronghold and any valuable information there.",al={"nar gurk","tome info","twilight stronghold"}},{q="Where is Krol'dok Stronghold?",a="Krol'dok Stronghold is north of Sunnyglade.",al={"where's the stronghold","kroldok location"}},{q="Why am I looking for Nar'gurk?",a="A Twilight creature mentioned Nar'gurk and shadow magic while being asked where its former masters came from.",al={"why nar gurk","twilight clue"}},{q="What information might be there?",a="The information sought may help explain where the persistent Twilight forces are coming from.",al={"what info","tome of twilight info"}}},kw={"krol'dok stronghold","nar'gurk","shadow magic","sunnyglade","tome of twilight","twilight","twilight forces"},rel={"subzone:sunnyglade"},m={faction="Alliance",id=94984},src={"In-game quest text: Tome of Twilight"},fv=true}
E["quest:94992"] = {t="quest",n="Rescue Roundup",z="riverglades",s="A lost horse named Biscuit nudges you, ready to follow you back to Wheeler's Grange. Her return means the grange is back in business.",h="A lost horse named Biscuit nudges you, ready to follow you back to Wheeler's Grange.",sec={{t="Biscuit Returns",b="Wheeler's lost horse is named Biscuit, and she bows her head before nudging your arm. You bring her back to Wheeler's Grange. Wheeler is grateful to have Biscuit home, though Biscuit will be alone for a while. The grange is open for business again.",sp=0}},faq={{q="Who is Biscuit?",a="Biscuit is Wheeler's horse, who has been lost and needs to be brought back to Wheeler's Grange.",al={"biscuit horse","lost horse","who's biscuit"}},{q="Where does Biscuit need to go?",a="Biscuit needs to be brought back to Wheeler's Grange.",al={"where bring horse","biscuit location","horse destination"}},{q="Why is Wheeler grateful?",a="Wheeler is grateful because you bring Biscuit back to the grange.",al={"why thanks","saved biscuit","wheeler thank you"}},{q="Is Biscuit alone?",a="Wheeler says Biscuit will be alone for a while and hopes to find some of her stable-mates.",al={"biscuit alone","where stablemates","other horses"}},{q="Is Wheeler's Grange open?",a="With Biscuit back, Wheeler's Grange is back in business.",al={"grange open","wheeler business","grange back"}}},kw={"biscuit","demar","horse","lost horse","rescue roundup","stable-mates","wheeler's grange"},m={faction="Alliance",id=94992},src={"In-game quest text: Rescue Roundup"},fv=true}
E["quest:94997"] = {t="quest",n="Lingering Essence",z="riverglades",s="Riftan asks you to bring a satchel of cursed mementos to Ashe Amberhall at Farholde Keep. He hopes her studies can reveal what energies the objects hold.",h="Riftan asks you to bring a satchel of cursed mementos to Ashe Amberhall at Farholde Keep.",sec={{t="At the Keep",b="At Farholde Keep, Ashe Amberhall takes the satchel from you and hears that Riftan sent it. She says his long fight against the cultists has made her worry that fatigue is clouding his judgment. Yet she admits his concerns may have grounds, and turns her attention to the objects.",sp=0}},faq={{q="Who is asking me to bring the satchel?",a="Riftan asks you to take the Satchel of Cursed Mementos to Ashe Amberhall.",al={"who sent me","Riftan satchel","who is Riftan"}},{q="Who is Ashe Amberhall?",a="Ashe Amberhall is a respected scholar whose field of study may help her examine the energies in the objects.",al={"Ashe who","who is Ashe","Amberhall"}},{q="Where do I take the mementos?",a="Bring the Satchel of Cursed Mementos to Ashe Amberhall at Farholde Keep.",al={"where to take satchel","Farholde Keep","satchel destination"}},{q="What is in the satchel?",a="The satchel contains cursed mementos, and Riftan wants Ashe to examine what energies they hold.",al={"what's in the bag","cursed mementos","satchel contents"}},{q="Why does Riftan want Ashe to examine them?",a="Riftan hopes Ashe's studies can reveal what energies are contained within the objects.",al={"why Ashe","what's the satchel for","lingering essence"}},{q="What does Ashe think of Riftan's concern?",a="Ashe worries that fatigue from Riftan's long fight against cultists may cloud his mind, though she says his concerns may be founded.",al={"does Ashe trust Riftan","Riftan tired","Ashe's opinion"}}},kw={"ashe amberhall","cultists","cursed mementos","energies","farholde keep","lingering essence","riftan","satchel of cursed mementos"},m={faction="Alliance",id=94997},src={"In-game quest text: Lingering Essence"},fv=true}
E["quest:94998"] = {t="quest",n="Curios of Curiosity",z="riverglades",s="You carry a satchel of unusual mementos to Melanie Sable. Their fine craftsmanship may make them useful.",h="You carry a satchel of unusual mementos to Melanie Sable.",sec={{t="A Satchel for Melanie",b="Someone who examined the mementos sends you to Melanie Sable with the satchel. They believe the objects are safe, though their origin remains unknown. Their workmanship is unusual, and Melanie may find a use for them.",sp=0}},faq={{q="Who should I take the mementos to?",a="Take the satchel of mementos to Melanie Sable, as the examiner asks.",al={"where take the satchel","who is Melanie Sable"}},{q="What are the mementos?",a="They are remnants of something, but the examiner does not know exactly what.",al={"what's in the satchel","what are these curios"}},{q="Why are the mementos unusual?",a="Their craftsmanship is described as quite unique and intricate.",al={"what's special about them","curios craftsmanship"}},{q="Are the mementos safe?",a="The examiner asks you to tell Melanie that the mementos are safe.",al={"is the satchel safe","are they dangerous"}}},kw={"craftsmanship","curios of curiosity","melanie sable","mementos","remnants","satchel of mementos"},m={faction="Alliance",id=94998},src={"In-game quest text: Curios of Curiosity"},fv=true}
E["quest:94999"] = {t="quest",n="Eyes for the Watchman",z="riverglades",s="Eleanor asks you to carry a care package to Watcher Fredericks at Southern Watch. Her ranch duties keep her from delivering it herself.",h="Eleanor asks you to carry a care package to Watcher Fredericks at Southern Watch.",sec={{t="A Gift for Fredericks",b="Watcher Fredericks patrols past Eleanor's ranch, and she has prepared a small gift for him. With her brother to watch and the ranch to tend, she asks you to carry it to Southern Watch, west of her home.",sp=0}},faq={{q="Who is the package for?",a="Eleanor's care package is for Watcher Fredericks, who is stationed at Southern Watch.",al={"who gets it","package for who"}},{q="Why can't Eleanor deliver it herself?",a="Eleanor needs to watch her little brother and tend to the ranch.",al={"why not Eleanor","why can't she go"}},{q="Where is Watcher Fredericks?",a="Watcher Fredericks is stationed at Southern Watch, west of Eleanor's ranch.",al={"where's Fredericks","Southern Watch location"}},{q="Why did Eleanor prepare a gift?",a="Fredericks sometimes patrols past the ranch, and Eleanor wants to show her appreciation.",al={"why the package","what's it for"}},{q="How does Fredericks react to the package?",a="Fredericks thanks you for delivering Eleanor's gift and says he will return the favor sometime.",al={"Fredericks reaction","did he like it"}}},kw={"care package","eleanor","patrol","ranch","southern watch","watcher fredericks"},m={faction="Alliance",id=94999},src={"In-game quest text: Eyes for the Watchman"},fv=true}
E["quest:95033"] = {t="quest",n="On the Other Side",z="riverglades",s="Tan'jani sends you to Camp Mojache in Feralas to seek help from Witch Doctor Uzer'i. Though known for his magic, Uzer'i is also a hunter.",h="Tan'jani sends you to Camp Mojache in Feralas to seek help from Witch Doctor Uzer'i.",sec={{t="Tan'jani's Friend",b="Across Feralas, Camp Mojache is where you can find Witch Doctor Uzer'i, an old friend of Tan'jani. Tan'jani says Uzer'i works with magic, but is also a hunter. You are sent to speak with him, leaving the wide open plains behind.",sp=0}},faq={{q="Who sent me to Uzer'i?",a="Tan'jani sends you to Witch Doctor Uzer'i, an old friend.",al={"tan'jani sent me","who is ol tanjani"}},{q="Where can I find Uzer'i?",a="Witch Doctor Uzer'i is at Camp Mojache in Feralas.",al={"uzer'i location","where is the witch doctor"}},{q="Why am I being sent to Uzer'i?",a="Tan'jani says Uzer'i is looking for help and asks you to speak with him.",al={"why talk to uzeri","what does tanjani want"}},{q="What does Uzer'i do?",a="Witch Doctor Uzer'i works with magic and is also a hunter.",al={"uzeri job","witch doctor hunter"}}},kw={"camp mojache","feralas","hunter","magic","on the other side","tan'jani","witch doctor uzer'i"},rel={"npc:witch-doctor-uzer-i","subzone:camp-mojache","zone:feralas"},m={faction="Horde",id=95033},src={"In-game quest text: On the Other Side"},fv=true}
E["quest:95059"] = {t="quest",n="Frazzlespark's Crate",z="riverglades",s="A goblin has a delivery for Knight Commander Demar Brant at Farholde Keep. You are asked to carry Frazzlespark's Crate to him.",h="A goblin has a delivery for Knight Commander Demar Brant at Farholde Keep.",sec={{t="A Keepward Delivery",b="Frazzlespark sends you southwest to Farholde Keep, where Knight Commander Demar Brant is waiting. The crate is meant for him, and the goblin makes a point of using his full name. At the keep, Demar calls the goblin a means to an end, part of the dealings he says keep his own people safe and successful.",sp=0}},faq={{q="Who is waiting for the crate?",a="Knight Commander Demar Brant is waiting for Frazzlespark's Crate at Farholde Keep.",al={"who wants the crate","demar brant delivery"}},{q="Where do I take Frazzlespark's Crate?",a="Take Frazzlespark's Crate to Knight Commander Demar Brant at Farholde Keep, southwest of Frazzlespark.",al={"crate location","where's farholde keep"}},{q="Why does Demar want his full name used?",a="Frazzlespark remarks that Demar always makes the goblin use his full name, but gives no reason.",al={"demar full name","why knight commander"}},{q="Why does Frazzlespark call it a special delivery?",a="Frazzlespark calls it a special delivery, and says Demar Brant is waiting for it at Farholde Keep.",al={"crate delivery","what's special about crate"}},{q="Why does this delivery matter?",a="Demar Brant says certain dealings must be done to ensure the safety and success of his people, and calls the goblin nothing more than a means to an end.",al={"why deliver crate","goblin safety"}}},kw={"crate","demar brant","farholde keep","frazzlespark","frazzlespark's crate","goblin delivery","knight commander"},rel={"quest:95062","topic:goblin"},m={faction="Alliance",id=95059},src={"In-game quest text: Frazzlespark's Crate"},fv=true}
E["quest:95062"] = {t="quest",n="Frazzlespark's Crate",z="riverglades",s="A delivery from Frazzlespark is bound for Old Krom'rosh at Rog'mar. Carry the crate there quickly and carefully.",h="A delivery from Frazzlespark is bound for Old Krom'rosh at Rog'mar.",sec={{t="A Careful Delivery",b="Frazzlespark has a package for Old Krom'rosh, who is waiting at Rog'mar just west of here. You are asked to carry it quickly and carefully, though the reason is left unspoken. Krom'rosh's dealings help accomplish the group's goals.",sp=0}},faq={{q="Who is waiting for Frazzlespark's crate?",a="Old Krom'rosh is waiting for Frazzlespark's crate at Rog'mar.",al={"who gets the crate","crate for krom'rosh","kromrosh package"}},{q="Where is Rog'mar?",a="Rog'mar is just west of Frazzlespark.",al={"where's rog'mar","rogmar location","rog'mar place"}},{q="What should I do with the crate?",a="Carry Frazzlespark's crate to Old Krom'rosh at Rog'mar, quickly and carefully.",al={"deliver crate","frazzlespark delivery","what to do"}},{q="Why does the crate need careful delivery?",a="Frazzlespark advises you to deliver it quickly and carefully but gives no reason.",al={"why careful","why rush the crate","crate reason"}},{q="Why does Krom'rosh make these kinds of dealings?",a="Krom'rosh says such dealings help accomplish their goals.",al={"krom'rosh dealings","why relationships","what are dealings for"}}},kw={"crate","delivery","frazzlespark","frazzlespark's crate","krom'rosh","old krom'rosh","package","rog'mar"},m={faction="Horde",id=95062},src={"In-game quest text: Frazzlespark's Crate"},fv=true}
E["quest:95063"] = {t="quest",n="Bloodmaster's Ring",z="riverglades",s="You have angered Chub'chob in Bolder'ok's Bloodmaster's Ring. The arena's fee offers no protection from death, and you are left to face him alone.",h="You have angered Chub'chob in Bolder'ok's Bloodmaster's Ring.",sec={{t="The Arena's Challenge",b="The warning comes after your bouts in Bolder'ok's Bloodmaster's Ring, where you have already drawn Chub'chob's ire. The attendant reminds you that the entry fee will not cover an accidental death. From here, you face Chub'chob, Bloodmaster of Bolder'ok, alone.",sp=0},{t="A New Standing",b="When you return to Clugfist, you bring word that you have become champion of the Bloodmaster's Ring. Your victory earns you a new friend among the clan. You can now fight and feast with the ogres.",sp=1}},faq={{q="Who is Chub'chob?",a="Chub'chob is the Bloodmaster of Bolder'ok, and you have angered him in the ring.",al={"chubchob","bloodmaster","who is chub'chob"}},{q="Where is the Bloodmaster's Ring?",a="The Bloodmaster's Ring is at Bolder'ok.",al={"bloodmaster ring location","bolder'ok arena","where do i fight"}},{q="Who do I tell about becoming champion?",a="You share the news that you have become champion of the Bloodmaster's Ring with Clugfist at Bolder'ok.",al={"champion news","tell clugfist","who gets the news"}},{q="Does the entry fee cover accidental death?",a="No. The attendant warns that the entry fee does not cover accidental death.",al={"death fee","arena fee","does fee protect me"}}},kw={"arena","bloodmaster","bloodmaster's ring","bolder'ok","chub'chob","clugfist","ogres"},rel={"quest:94668"},m={faction="Horde",id=95063},src={"In-game quest text: Bloodmaster's Ring"},fv=true}
E["quest:95064"] = {t="quest",n="Preventative Measures",z="riverglades",s="Watcher Cornelius at Terral's Watch fears the orcs are pressing farther into the plains. He asks you to curb their growing presence.",h="Watcher Cornelius at Terral's Watch fears the orcs are pressing farther into the plains.",sec={{t="Orcs in the Plains",b="At Terral's Watch, Watcher Cornelius sees the orcs claiming land by the river and spreading into the plains. He asks you to kill Rog'mar trainees, hoping to halt their advance.",sp=0}},faq={{q="Who asks for help?",a="Watcher Cornelius at Terral's Watch asks you to stop the orcs' growing presence.",al={"who needs help","cornelius request"}},{q="Why is Cornelius concerned about the orcs?",a="The orcs have claimed land by the river, and their presence is growing in the plains.",al={"why fight orcs","orcs in plains"}},{q="Which orcs does Cornelius want killed?",a="Cornelius asks you to kill Rog'mar trainees.",al={"rog'mar trainees","which orcs"}},{q="Where does Cornelius ask for help?",a="Cornelius asks for help at Terral's Watch.",al={"terral's watch","where is cornelius"}}},kw={"orcs","plains","preventative measures","rog'mar trainees","terral's watch","watcher cornelius"},m={faction="Alliance",id=95064},src={"In-game quest text: Preventative Measures"},fv=true}
E["quest:95118"] = {t="quest",n="Saltwater Savages",z="riverglades",s="A port keeper asks you to thin the Murlocs along Eastwind Shore. The nuisance has become a constant complaint from sailors, fishermen, and his children.",h="A port keeper asks you to thin the Murlocs along Eastwind Shore.",sec={{t="Complaints at the Port",b="The port keeper has heard enough complaints from sailors, fishermen, and even his children. Murlocs trouble him, but he still has a port to run. He asks you to kill some along Eastwind Shore, hoping for a little peace from the noise around him.",sp=0}},faq={{q="Why does the port keeper want the Murlocs killed?",a="Sailors, fishermen, and the port keeper's children keep complaining about them. He calls them a nuisance and wants some peace while he runs the port.",al={"why kill murlocs","murlocs bothering port"}},{q="Which Murlocs is he asking about?",a="He asks you to kill Murloc Oracles and Murloc Warriors along Eastwind Shore.",al={"murloc types","oracles and warriors"}},{q="Where are the Murlocs?",a="The port keeper points you to Eastwind Shore.",al={"eastwind shore murlocs","where murlocs"}},{q="Does killing these Murlocs solve the problem?",a="The port keeper expects more Murlocs to return soon, though he hopes their deaths will give him some peace until then.",al={"murlocs come back","is it over"}}},kw={"eastwind shore","fishermen","murloc","murloc oracle","murloc warrior","port keeper","sailors","saltwater savages"},rel={"topic:murloc"},m={id=95118},src={"In-game quest text: Saltwater Savages"},fv=true}
E["quest:95119"] = {t="quest",n="Unfriendly Competition",z="riverglades",s="A Powderfuse Port proprietor asks you to curb the Eastsea crew's raids on cargo and ships. Their nearest members are along the Eastwind Shore.",h="A Powderfuse Port proprietor asks you to curb the Eastsea crew's raids on cargo and ships.",sec={{t="Along the Shore",b="Ships sink and cargo goes missing, cutting into the proprietor's business at Powderfuse Port. The Eastsea crew's buccaneers and musketeers are the ones closest to the port, along the Eastwind Shore to the north. The proprietor wants you to deal with them first; the rest of the crew's operation remains a concern.",sp=0}},faq={{q="Who is asking for help?",a="A proprietor at Powderfuse Port asks you to deal with the Eastsea crew.",al={"who gave this","port owner","powderfuse guy"}},{q="Who are the Eastsea crew?",a="The Eastsea crew are described as destructive and bloodthirsty, and they steal cargo and sink ships.",al={"eastsea pirates","eastsea guys","who are eastsea"}},{q="Why does the proprietor want them stopped?",a="The crew steals cargo and sinks ships, costing the proprietor money.",al={"why fight eastsea","cargo theft","why are ships sinking"}},{q="Where are the Eastsea crew closest to the port?",a="The crew members closest to Powderfuse Port are along the Eastwind Shore to the north.",al={"eastwind shore","where are the pirates","north beach"}}},kw={"cargo theft","eastsea buccaneers","eastsea crew","eastsea musketeers","eastwind shore","powderfuse port","sinking ships","unfriendly competition"},m={id=95119},src={"In-game quest text: Unfriendly Competition"},fv=true}
E["quest:95120"] = {t="quest",n="WANTED: Old Rot-Chum",z="riverglades",s="Wharfmaster Whizzbuzz offers a reward for proof of Old Rot-Chum’s demise. The aggressive murloc has been attacking small vessels in the southern waters.",h="Wharfmaster Whizzbuzz offers a reward for proof of Old Rot-Chum’s demise.",sec={{t="A Threat at Sea",b="Sailors and swimmers in the waters to the south face attacks on rowboats and other small vessels. Local fishermen call the aggressive murloc behind them Old Rot-Chum. Wharfmaster Whizzbuzz offers a reward for proof that the creature is dead, and asks you to bring it to him.",sp=0}},faq={{q="Who is Old Rot-Chum?",a="Old Rot-Chum is the nickname local fishermen give an especially aggressive murloc.",al={"old rot-chum","rot chum","who's rot-chum"}},{q="Where has Old Rot-Chum been seen?",a="Old Rot-Chum has been seen in the waters to the south, near islands infested with murlocs.",al={"where is old rot-chum","rot-chum location","where's the murloc"}},{q="What has Old Rot-Chum been attacking?",a="Old Rot-Chum has been attacking rowboats and other small vessels.",al={"what is rot-chum attacking","boat attacks","murloc and rowboats"}},{q="Who offers the reward?",a="Wharfmaster Whizzbuzz offers a reward in exchange for proof of Old Rot-Chum’s demise.",al={"who wants rot-chum proof","wharfmaster reward","who pays for old rot-chum"}},{q="What proof does Whizzbuzz ask for?",a="Wharfmaster Whizzbuzz asks you to bring proof of Old Rot-Chum’s demise.",al={"what proof for rot-chum","bring proof","proof of demise"}}},kw={"murloc","murloc islands","old rot-chum","rowboats","small vessels","southern waters","wharfmaster whizzbuzz"},rel={"topic:murloc"},m={id=95120},src={"In-game quest text: WANTED: Old Rot-Chum"},fv=true}
E["quest:95121"] = {t="quest",n="A Taste of the Sea",z="riverglades",s="Fimbo Greasemitz wants fresh seafood for a new stew at his cafe on the water. You gather local ingredients to change up the menu.",h="Fimbo Greasemitz wants fresh seafood for a new stew at his cafe on the water.",sec={{t="A New Dish",b="Fimbo Greasemitz runs a cafe on the water, where roasted boar and fish fill the menu each day. He wants to try a seafood stew and asks you to bring him murloc eyes and Sand Crawler meat from nearby beaches.",sp=0}},faq={{q="Who is Fimbo Greasemitz?",a="Fimbo Greasemitz runs a cafe on the water and wants to add seafood stew to its menu.",al={"who's fimbo","fimbo cafe","fimbo greasemitz"}},{q="What ingredients does Fimbo need?",a="Fimbo asks for murloc eyes and Sand Crawler meat for his seafood stew.",al={"stew ingredients","what meat","murloc eyes"}},{q="Why does Fimbo want seafood?",a="He wants a new seafood stew recipe to shake up the cafe's daily menu of roasted boar and fish.",al={"why stew","new menu","cafe food"}},{q="Where can you find the ingredients?",a="Fimbo says the murloc eyes and Sand Crawler meat can be found along the nearby beaches.",al={"where meat","where ingredients","beach stuff"}}},ang={["profession:Cooking"]="As a cook, you can see Fimbo seeking fresh local ingredients for a seafood stew."},kw={"beach","cafe","fimbo greasemitz","fish","murloc eyes","roasted boar","sand crawler meat","seafood stew"},rel={"topic:murloc"},m={id=95121},src={"In-game quest text: A Taste of the Sea"},fv=true}
E["quest:95122"] = {t="quest",n="Unchecked Expansion",z="riverglades",s="Wharfmaster Whizzbuzz says the Eastsea pirates north of here are a greater threat than those you fought before. Their raid left Windstead burned, and he wants their advance inland stopped.",h="Wharfmaster Whizzbuzz says the Eastsea pirates north of here are a greater threat than those you fought...",sec={{t="Windstead in Ashes",b="Windstead lies burned after the Eastsea pirates ransacked it and carried off its plunder. Wharfmaster Whizzbuzz asks you to thin the ranks of the raiders and bombardiers north of here. He fears the pirates may push their turf farther inland.",sp=0}},faq={{q="Who asks for help against the Eastsea pirates?",a="Wharfmaster Whizzbuzz asks you to thin the Eastsea pirates' ranks.",al={"who wants help","whizzbuzz task","wharfmaster"}},{q="What happened to Windstead?",a="The Eastsea pirates ransacked Windstead, took its plunder, and burned it to the ground.",al={"windstead burned","what happened here","why is windstead gone"}},{q="Which pirates are the target?",a="Wharfmaster Whizzbuzz names Eastsea Raiders and Eastsea Bombardiers as the pirates to thin.",al={"pirate types","who do i fight","eastsea raiders"}},{q="Why does Whizzbuzz want their ranks thinned?",a="He wants to stop the pirates from pushing their turf farther inland.",al={"why stop pirates","pirates inland","why fight eastsea"}}},kw={"eastsea bombardiers","eastsea pirates","eastsea raiders","pirate","unchecked expansion","wharfmaster whizzbuzz","windstead"},rel={"topic:pirate"},m={id=95122},src={"In-game quest text: Unchecked Expansion"},fv=true}
E["quest:95123"] = {t="quest",n="A Blast Ye Scurvy Dogs!",z="riverglades",s="Wharfmaster Whizzbuzz wants gunpowder to destroy Eastsea pirate ships. You are sent to look for powder kegs near the demolished Winstead.",h="Wharfmaster Whizzbuzz wants gunpowder to destroy Eastsea pirate ships.",sec={{t="Powder for the Wharfmaster",b="The ships are Whizzbuzz's next concern, after the Eastsea pirates themselves. He believes they may have stored gunpowder near the freshly demolished Winstead to the north. You are sent to find the powder kegs; he will explain his plan later.",sp=0}},faq={{q="Who is asking for the powder?",a="Wharfmaster Whizzbuzz wants gunpowder for a plan against the Eastsea ships.",al={"who wants the kegs","whizzbuzz powder","who sent me"}},{q="Why does Whizzbuzz want gunpowder?",a="He wants to take out the Eastsea ships so they cannot flee for reinforcements.",al={"why powder","what's the powder for","eastsea ship plan"}},{q="Where might the pirates have stored the powder?",a="Whizzbuzz thinks the pirates may have stored gunpowder near the freshly demolished Winstead to the north.",al={"powder location","where are the kegs","winstead powder"}},{q="What is Whizzbuzz's plan?",a="Whizzbuzz says he will explain his plan later; for now, he wants you to find the powder.",al={"what's his plan","whizzbuzz plan","what will happen"}}},kw={"eastsea pirates","gunpowder","pirate ships","powder kegs","wharfmaster whizzbuzz","winstead"},rel={"topic:pirate"},m={id=95123},src={"In-game quest text: A Blast Ye Scurvy Dogs!"},fv=true}
E["quest:95124"] = {t="quest",n="Admiral Lamora",z="riverglades",s="Wharfmaster Whizzbuzz sends you after Admiral Lamora, who sails on an Eastsea boat northeast of his position. Lamora’s loot could help Whizzbuzz recover some of what the plundering cost him.",h="Wharfmaster Whizzbuzz sends you after Admiral Lamora, who sails on an Eastsea boat northeast of his position.",sec={{t="Whizzbuzz's Losses",b="Wharfmaster Whizzbuzz wants Admiral Lamora dead and his loot returned. Lamora is aboard one of the Eastsea’s boats northeast of Whizzbuzz. You are to find which boat he uses and where he keeps his plunder. If it is locked away, Whizzbuzz suspects Lamora carries the key.",sp=0}},faq={{q="Who is sending me after Admiral Lamora?",a="Wharfmaster Whizzbuzz sends you after Admiral Lamora and asks you to bring back Lamora’s loot.",al={"who wants Lamora dead","Whizzbuzz's request","admiral Lamora quest"}},{q="Where is Admiral Lamora?",a="Lamora is aboard one of the Eastsea’s boats northeast of Wharfmaster Whizzbuzz.",al={"where's Lamora","Lamora location","which Eastsea boat"}},{q="Why does Whizzbuzz want Lamora dead?",a="Whizzbuzz says Lamora’s plundering has cost him a fortune, and he wants to recover some of his losses.",al={"why kill Lamora","Whizzbuzz revenge","Lamora and Whizzbuzz"}},{q="What does Whizzbuzz want from Lamora?",a="Whizzbuzz wants Lamora dead and his loot brought back. He suspects Lamora carries the key if the stash is locked.",al={"what to get from Lamora","Lamora's loot","what's the stash"}},{q="What happens after I return?",a="Whizzbuzz says he was unsure you would survive meeting Lamora, then offers to do you a favor and says he may call on you again.",al={"what does Whizzbuzz say","return to Whizzbuzz","Whizzbuzz thanks"}}},kw={"admiral lamora","eastsea","key","loot","plundering","stash","wharfmaster whizzbuzz"},m={id=95124},src={"In-game quest text: Admiral Lamora"},fv=true}
E["quest:95156"] = {t="quest",n="Stuff 'Em and Stick 'Em",z="riverglades",s="Ember needs hay from Wheeler’s farmstead to repair worn training dummies. The recruits need sound targets for their battle training.",h="Ember needs hay from Wheeler’s farmstead to repair worn training dummies.",sec={{t="Worn Targets",b="At the training grounds, Ember needs hay to mend the dummies used by the recruits. Their wear may leave the trainees unprepared for battle. A farmstead outside the keep belongs to Wheeler, who may have hay to spare. Ember offers to compensate him for any supplies he can provide.",sp=0},{t="Fresh Targets",b="Ember expects to put several targets back in order as soon as the hay arrives. The recruits’ training depends on dummies that can withstand their practice.",sp=1}},faq={{q="Why does Ember need hay?",a="Ember needs hay to repair worn training dummies at the training grounds.",al={"hay for ember","why hay","training dummy hay"}},{q="Who is Wheeler?",a="Wheeler is the man who runs the small farmstead outside the keep, where Ember hopes hay can be spared.",al={"wheeler farm","who has hay","farmstead man"}},{q="Why are the dummies being repaired?",a="The dummies are showing wear, and Ember worries the recruits may be unprepared for battle without repairs.",al={"worn dummies","training targets broken","why fix targets"}},{q="Will Wheeler be paid for the hay?",a="Ember says Wheeler will be compensated if he can spare supplies.",al={"does wheeler get paid","compensation for hay","pay for bundles"}},{q="What will Ember do with the hay?",a="Ember plans to use the hay to repair several training targets right away.",al={"what is hay for","fix targets","hay purpose"}}},kw={"ember","farmstead","hay","recruits","stuff 'em and stick 'em","training dummies","training grounds","wheeler"},m={faction="Alliance",id=95156},src={"In-game quest text: Stuff 'Em and Stick 'Em"},fv=true}
E["quest:95162"] = {t="quest",n="Paletusk Harvesting",z="riverglades",s="Na'zok asks you to gather paletusk meat near Bolder'ok. The ranch feeds nearby ogres and supplies Rog'mar as the war advances.",h="Na'zok asks you to gather paletusk meat near Bolder'ok.",sec={{t="Meat for the Ranch",b="Na'zok needs more meat at the ranch near Bolder'ok, where ogres let Na'zok stay while the meat keeps coming. As the war advances, the need for food grows, and the ogres are beginning to eye Na'zok as their next meal. You are asked to gather chunks of boar meat for the hungry ogres and Rog'mar.",sp=0}},faq={{q="Who is asking for meat?",a="Na'zok asks you to gather boar meat near Bolder'ok for the ogres and Rog'mar.",al={"who needs meat","na'zok request","who is na'zok"}},{q="Why does Na'zok need the meat?",a="The ranch is one of Na'zok's few food sources, and the ogres let Na'zok stay as long as meat keeps coming.",al={"why meat","why gather boar","hungry ogres"}},{q="Who is Rog'mar?",a="Rog'mar is a settlement, not a person. Na'zok wants enough meat left over to supply it.",al={"rog'mar meat","meat for rog'mar"}},{q="Where is Na'zok?",a="Na'zok is near Bolder'ok.",al={"na'zok location","where is the ranch"}},{q="What meat is needed?",a="Na'zok asks for chunks of boar meat from paletusk.",al={"boar meat","paletusk meat","meat chunks"}}},kw={"boar meat","bolder'ok","na'zok","ogres","paletusk","paletusk harvesting","ranch","rog'mar"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=95162},src={"In-game quest text: Paletusk Harvesting"},fv=true}
E["quest:95163"] = {t="quest",n="Drive Them Back",z="riverglades",s="Na'zok asks you to bring escaped Young Paletusks back to his farm near Bolder'ok. The piglets have crossed the river, and their pens need them back.",h="Na'zok asks you to bring escaped Young Paletusks back to his farm near Bolder'ok.",sec={{t="The Escaped Piglets",b="Na'zok's farm near Bolder'ok has more pigs loose in the valley than in its pens. Gorgegut has not been an ideal farmhand, though he keeps humans away. Some of the Young Paletusks have crossed the river, and they are too small to be harvested in the field. Na'zok gives you a stick to send them back to their pens.",sp=0}},faq={{q="Why are the piglets out of their pens?",a="Some Young Paletusks have escaped across the river from Na'zok's farm.",al={"escaped piglets","pigs loose","why pigs outside"}},{q="Who is Gorgegut?",a="Gorgegut is Na'zok's farmhand, though Na'zok says he has been less than ideal.",al={"Gorgegut farmhand","who Gorgegut","pig farm guy"}},{q="Why bring the Young Paletusks back?",a="The Young Paletusks are too small to be harvested in the field, so Na'zok wants them returned to the farm.",al={"return piglets","why bring pigs back","young paletusk"}},{q="Where is Na'zok's farm?",a="Na'zok's farm is near Bolder'ok.",al={"Na'zok farm location","farm near Bolder'ok","where pig farm"}}},kw={"bolder'ok","escaped piglets","farm","gorgegut","na'zok","paletusk","pigs","young paletusks"},m={faction="Horde",id=95163},src={"In-game quest text: Drive Them Back"},fv=true}
E["quest:95165"] = {t="quest",n="See Ya, Scallywags!",z="riverglades",s="A wharfmaster has a plan for the Eastsea’s three boats. You are to plant timed charges in their hulls, then leave him to set them off.",h="A wharfmaster has a plan for the Eastsea’s three boats.",sec={{t="Charges Aboard",b="The wharfmaster puts the gunpowder you stole to use, making timed charges for the Eastsea’s boats. You are to place one in the hull of each vessel, near its cannons. Once they are set, get clear so he can trigger the explosives.",sp=0}},faq={{q="What does the wharfmaster want me to do?",a="Plant a remote explosive charge in the hull of each of the Eastsea’s three boats, near the cannons.",al={"what am i supposed to do","eastsea boats task"}},{q="Why use the gunpowder I stole?",a="The wharfmaster uses the gunpowder to make timed charges for the boats.",al={"stolen gunpowder","what is the powder for"}},{q="Why plant the charges near the cannons?",a="The wharfmaster says the gunpowder will make the explosives more powerful near the cannons.",al={"charge near cannons","where do charges go"}},{q="How many boats are involved?",a="You are to place charges on each of the Eastsea’s three boats.",al={"how many ships","three boats"}},{q="What does the wharfmaster know about explosives?",a="He says he used to make a less honest living.",al={"wharfmaster explosives","why can he make bombs"}}},kw={"boats","cannons","eastsea","gunpowder","remote explosive","see ya scallywags","timed charges","wharfmaster"},m={id=95165},src={"In-game quest text: See Ya, Scallywags!"},fv=true}
E["quest:95183"] = {t="quest",n="Step One: Rock",z="riverglades",s="Hamur in Bolder'ok wants good rocks from the river nearby. Bring them so he can make a tiny weapon for a tiny creature.",h="Hamur in Bolder'ok wants good rocks from the river nearby.",sec={{t="Hamur's Request",b="Hamur in Bolder'ok says you are too small to wield a good ogre weapon. He offers to make you a tiny one if you bring him good rocks. He wants rocks from the river outside Bolder'ok, where only the best stones will do.",sp=0}},faq={{q="Who is Hamur?",a="Hamur is in Bolder'ok and offers to make you a tiny weapon if you bring him good rocks.",al={"hamur who","who wants rocks"}},{q="Where do I find the rocks?",a="Hamur asks for good rocks from the river outside Bolder'ok.",al={"rock location","where rocks"}},{q="Why does Hamur want rocks?",a="Hamur says he will use the good rocks to make a tiny weapon for a tiny creature.",al={"why rocks","rocks for what"}},{q="What kind of rocks does Hamur want?",a="Hamur wants good rocks from the river outside Bolder'ok; he says not every rock is suitable.",al={"good rocks","which rocks"}}},kw={"bolder'ok","good rocks","hamur","ogre weapon","river","tiny weapon"},m={faction="Horde",id=95183},src={"In-game quest text: Step One: Rock"},fv=true}
E["quest:95184"] = {t="quest",n="The Sharpest of Blades",z="riverglades",s="Ember Bladewhisper wants sharpening stones for the Farholde recruits. A seasoned blade can mean the difference between victory and death.",h="Ember Bladewhisper wants sharpening stones for the Farholde recruits.",sec={{t="Blades for Recruits",b="At the Farholde training grounds, Ember Bladewhisper sees that the recruits know little of the difference between a practice sword and a veteran's well-kept blade. You are asked to bring her sharpening stones so the recruits can learn what a keen edge means.",sp=0}},faq={{q="Who needs sharpening stones?",a="Ember Bladewhisper at the Farholde training grounds asks for sharpening stones.",al={"who wants stones","Ember Bladewhisper stones"}},{q="Why does Ember want the stones?",a="She wants the recruits to understand how a sharpened blade differs from a training sword.",al={"why sharpening stones","what are stones for"}},{q="Where should I bring the stones?",a="Bring the sharpening stones to Ember Bladewhisper at the Farholde training grounds.",al={"where to take stones","Farholde stones"}},{q="What kind of stones does Ember need?",a="Ember asks for Solid Sharpening Stones.",al={"which stones","stone type"}}},kw={"ember bladewhisper","farholde","recruits","sharpening stones","solid sharpening stones","training grounds"},m={faction="Alliance",id=95184},src={"In-game quest text: The Sharpest of Blades"},fv=true}
E["quest:95219"] = {t="quest",n="From Port to Port",z="riverglades",s="A port seller sends you with a carefully packed cask to Feathermoon Stronghold. The long journey calls for care.",h="A port seller sends you with a carefully packed cask to Feathermoon Stronghold.",sec={{t="A Distant Customer",b="A seller has a customer at Feathermoon Stronghold in Feralas, and you carry a cask of Powderfuse Port there. The seller says it is packed airtight, but warns that something could set it off. Handle the cask with care on the way to Mardrack Greenwell.",sp=0}},faq={{q="What am I delivering?",a="You are carrying a cask of Powderfuse Port to Mardrack Greenwell at Feathermoon Stronghold.",al={"what's in the cask","powderfuse port delivery","port cask"}},{q="Where am I taking the cask?",a="The cask is bound for Mardrack Greenwell at Feathermoon Stronghold in Feralas.",al={"where to deliver it","feathermoon delivery","feralas cask"}},{q="Why should I handle it carefully?",a="The seller warns that something could set off the airtight-packed cask.",al={"is the cask dangerous","why careful","what might set it off"}},{q="Who packed the cask?",a="One of the seller's men packed the cask airtight.",al={"who packed the port","airtight packing","seller's guy"}}},kw={"cask","delivery","feathermoon stronghold","feralas","from port to port","mardrack greenwell","powderfuse port"},rel={"subzone:feathermoon-stronghold-classic","zone:feralas"},m={faction="Alliance",id=95219},src={"In-game quest text: From Port to Port"},fv=true}
E["quest:95254"] = {t="quest",n="WANTED: Trapclaw",z="riverglades",s="Fimbo Greasemitz wants Trapclaw's pincer after the huge crab steals bait and cuts fishing lines beneath the docks. Bring it to him, and he promises a meal made with his secret spice blend.",h="Fimbo Greasemitz wants Trapclaw's pincer after the huge crab steals bait and cuts fishing lines beneath the...",sec={{t="Under the Docks",b="Fimbo Greasemitz is after crab meat, and Trapclaw has been crawling beneath the docks. The large crab steals bait and cuts fishing lines. Fimbo asks you to bring him Trapclaw's pincer, which he plans to use for a meal.",sp=0}},faq={{q="Who is asking for Trapclaw's pincer?",a="Fimbo Greasemitz wants Trapclaw's pincer for the crab meat.",al={"who wants the pincer","Fimbo Greasemitz request"}},{q="What is Trapclaw doing?",a="Trapclaw crawls beneath the docks, stealing bait and cutting fishing lines.",al={"why Trapclaw","crab under docks"}},{q="Why does Fimbo want the pincer?",a="Fimbo wants crab meat, and asks for Trapclaw's pincer.",al={"what's the pincer for","crab meat request"}},{q="What does Fimbo promise to make?",a="Fimbo says he'll make a dish with butter and his secret spice blend.",al={"what meal","Fimbo's dish"}}},kw={"bait","crab","crab meat","docks","fimbo greasemitz","fishing lines","pincer","trapclaw"},m={id=95254},src={"In-game quest text: WANTED: Trapclaw"},fv=true}
E["quest:95260"] = {t="quest",n="Terrors From the Deep",z="riverglades",s="At Powderfuse Port, you seek a sailor who can identify a sea monster painted on a hide. The strange image may point to a beast in these waters.",h="At Powderfuse Port, you seek a sailor who can identify a sea monster painted on a hide.",sec={{t="A Painted Beast",b="A painted hide brings you to Powderfuse Port, where a sailor may recognize the beast. Fish guts and squid ink form a long-necked shape rising from the waves. If it belongs to a real monster in these waters, someone who sails here may know it.",sp=0}},faq={{q="What is painted on the hide?",a="The hide shows a long-necked sea monster rising from the waves, painted with fish guts and squid ink.",al={"what's on the hide","sea monster picture"}},{q="Where can someone identify the monster?",a="Powderfuse Port is the nearest port, and a sailor there may recognize the creature.",al={"where do I go","powderfuse port sailor"}},{q="Is the sea monster real?",a="The painting raises the possibility that a sea monster lurks in these waters, but you are looking for a sailor who can identify it.",al={"real sea beast","monster real?"}}},kw={"fish guts","painted hide","powderfuse port","sailor","sea monster","squid ink","terrors from the deep"},m={id=95260},src={"In-game quest text: Terrors From the Deep"},fv=true}
E["quest:95261"] = {t="quest",n="It Takes Guts",z="riverglades",s="Argo Brinewhistle asks you for beast entrails and Rotflesh mushrooms as bait for a long-necked creature he has seen near the islands. He hopes the catch will make others believe his tale.",h="Argo Brinewhistle asks you for beast entrails and Rotflesh mushrooms as bait for a long-necked creature he...",sec={{t="Argo's Bait",b="Argo Brinewhistle says he has seen a long-necked monster around the islands while out on his boat. He wants you to gather beast entrails and Rotflesh mushrooms for bait. The mushrooms grow in a cave by Windstead, and Argo hopes to catch the creature.",sp=0}},faq={{q="Who is Argo Brinewhistle?",a="Argo Brinewhistle is a fisherman who says he has seen a long-necked monster around the islands.",al={"who's argo","argo fisherman","argo backstory"}},{q="What does Argo want for bait?",a="Argo asks you to bring him beast entrails and Rotflesh mushrooms.",al={"what bait does argo need","argo entrails","smelly bait"}},{q="Where do Rotflesh mushrooms grow?",a="Rotflesh mushrooms grow in a cave by Windstead.",al={"rotflesh location","where mushrooms grow","windstead cave"}},{q="Why does Argo need the bait?",a="Argo wants bait so he can catch the long-necked creature he says he has seen near the islands.",al={"why bait","what is argo catching","long neck monster"}},{q="Why doesn't anyone believe Argo?",a="Argo says people dismiss his story because they see him as a drunkard fisherman.",al={"why they doubt argo","argo drunkard","who believes argo"}}},kw={"argo brinewhistle","bait","beast entrails","islands","it takes guts","long-necked monster","rotflesh mushrooms","windstead"},m={id=95261},src={"In-game quest text: It Takes Guts"},fv=true}
E["quest:95267"] = {t="quest",n="The Monster Surfaces",z="riverglades",s="Argo Brinewhistle wants you to use a ball of bait to lure a sea monster from the waters near the murloc islands. He asks you to bring its head back for the boat.",h="Argo Brinewhistle wants you to use a ball of bait to lure a sea monster from the waters near the murloc...",sec={{t="Wreckage in the Water",b="Argo Brinewhistle points you toward the murloc islands, where you found a drawing. There, fresh wreckage marks the water where the bait should be thrown. The sea monster is the danger Argo wants drawn out, and its head is meant for the boat.",sp=0}},faq={{q="What does Argo want me to do?",a="Argo wants you to use the Big Ball o' Bait near fresh wreckage in the water by the murloc islands, then bring the monster's head to him.",al={"Argo bait quest","sea monster bait","monster surfaces quest"}},{q="Where do I throw the bait?",a="Argo points you to fresh wreckage in the water near the murloc islands, where you found a drawing.",al={"where bait","murloc islands bait","fresh wreckage"}},{q="Why does Argo want the monster's head?",a="Argo wants to make a decoration of the creature's head for the boat.",al={"monster head why","boat decoration","head for boat"}},{q="What is the bait called?",a="It is called the Big Ball o' Bait.",al={"big ball bait","ball o guts","bait name"}}},kw={"argo brinewhistle","big ball o' bait","boat decoration","monster head","murloc islands","sea monster","wreckage"},rel={"topic:murloc"},m={id=95267},src={"In-game quest text: The Monster Surfaces"},fv=true}
E["quest:95278"] = {t="quest",n="It Is Time, Brother...",z="riverglades",s="A missive must reach Krom'rosh at Rog'mar as the danger grows. Da'grosh's warning recalls an old hope for the village and the Horde.",h="A missive must reach Krom'rosh at Rog'mar as the danger grows.",sec={{t="A Warning for Rog'mar",b="The threat has grown beyond what was first thought, and Rog'mar needs warning. You carry a missive to Krom'rosh, with no time to stop for anyone along the way.",sp=0},{t="An Old Hope",b="Da'grosh once urged the village's kin to become great warriors of the Horde and protect their people from danger. Krom'rosh now sees a chance for that hope to be tested.",sp=1}},faq={{q="Who needs to be warned?",a="Rog'mar must be warned because the threat is greater than first thought.",al={"who needs warning","warn who"}},{q="Who receives the missive?",a="Krom'rosh at Rog'mar receives the missive.",al={"deliver missive to who","who gets the letter"}},{q="Why can't I stop along the way?",a="The missive must reach Krom'rosh, and the warning says not to stop for anyone on the path.",al={"why no stopping","can't stop"}},{q="What did Da'grosh tell the village as a child?",a="Da'grosh urged the village's kin to become great warriors of the Horde and save their people from danger.",al={"dagrosh childhood","what did dagrosh say"}}},ang={["faction:Horde"]="As a member of the Horde, you hear Da'grosh's childhood hope that the village's kin might become warriors who save their people.",["class:Warrior"]="As a warrior, you are named in Da'grosh's hope for the village's kin to become great warriors of the Horde."},kw={"da'grosh","horde","krom'rosh","missive","rog'mar","village","warning","warriors"},rel={"topic:horde"},m={faction="Horde",id=95278},src={"In-game quest text: It Is Time, Brother..."},fv=true}
E["quest:95288"] = {t="quest",n="Smuggler's Paradise",z="riverglades",s="At Powderfuse Port, Friz Frazzlespark sends you after Eastsea pirates who took her stolen goods. She calls it your first lesson in dealing with backstabbers.",h="At Powderfuse Port, Friz Frazzlespark sends you after Eastsea pirates who took her stolen goods.",sec={{t="Friz's Lesson",b="Friz Frazzlespark at Powderfuse Port wants you to reclaim goods taken by Eastsea pirates. She says she stole them first, and calls taking them back your first lesson as her lackey.",sp=0},{t="A First Lesson",b="Friz says you have learned your first lesson well. She offers her wisdom without charge, then points you toward another assignment.",sp=1}},faq={{q="Who is Friz Frazzlespark?",a="Friz Frazzlespark is the goblin who asks you to reclaim her stolen goods from Eastsea pirates.",al={"Friz","who's Friz","goblin at Powderfuse Port"}},{q="What did the Eastsea pirates take?",a="The Eastsea pirates took a shipment of goods that Friz says she had stolen first.",al={"pirates goods","what was stolen","smuggled goods"}},{q="Where does Friz want the goods returned?",a="Friz asks you to collect the goods for her at Powderfuse Port.",al={"where is Friz","Powderfuse Port","where to take goods"}},{q="Why does Friz want the goods back?",a="Friz says the pirates took goods she had stolen first, and calls taking them back a lesson in dealing with backstabbers.",al={"why retrieve goods","why does Friz care","backstabber reason"}}},kw={"eastsea pirates","friz frazzlespark","goblin","powderfuse port","smuggled goods","smuggler's paradise","stolen goods"},rel={"topic:goblin","topic:pirate"},m={faction="Alliance",id=95288},src={"In-game quest text: Smuggler's Paradise"},fv=true}
E["quest:95293"] = {t="quest",n="Smuggler's Special",z="riverglades",s="Friz sends you to Captain Bentcoin on Eastwind Shore with a crate called The Friz Special. The delivery is her answer to his attempt to muscle in on her turf.",h="Friz sends you to Captain Bentcoin on Eastwind Shore with a crate called The Friz Special.",sec={{t="Friz's Answer",b="Captain Bentcoin threatens you when you step onto his ship. Friz has sent you with a crate called The Friz Special, meant for the captain on Eastwind Shore. Her goods were supposed to come straight to her, and she believes Bentcoin is trying to muscle in on her turf. She calls this her second lesson and presents the crate as a fitting answer to his bargaining.",sp=0},{t="The Crate",b="When Bentcoin receives the crate from Friz, he takes it as a sign that she knows she has been beaten. Then he hears a ticking sound.",sp=1}},faq={{q="Who is Friz?",a="Friz sent you to Captain Bentcoin with a crate called The Friz Special after goods meant for her were diverted.",al={"friz","who sent me","friz special giver"}},{q="Who is Captain Bentcoin?",a="Captain Bentcoin is the captain Friz sends you to meet on his ship along Eastwind Shore.",al={"bentcoin","captain guy","eastwind captain"}},{q="What am I delivering?",a="You are carrying The Friz Special, a crate Friz made for Captain Bentcoin.",al={"friz special","the crate","what do i bring"}},{q="Why is Friz sending a gift?",a="Friz says goods you procured from the Eastsea pirates were meant to be shipped directly to her, and she believes Bentcoin is trying to muscle in on her turf.",al={"why gift bentcoin","friz delivery","trade war"}},{q="Where do I find Captain Bentcoin?",a="Captain Bentcoin is on his ship along Eastwind Shore.",al={"bentcoin location","where is captain","eastwind shore"}},{q="What does Bentcoin say when I arrive?",a="Bentcoin threatens to keelhaul you for stepping aboard his ship and demands a reason to spare you.",al={"bentcoin reaction","what does captain say","step on ship"}}},kw={"captain bentcoin","crate","eastsea pirates","eastwind shore","friz","smuggler's special","the friz special","trade war"},rel={"topic:pirate"},m={faction="Alliance",id=95293},src={"In-game quest text: Smuggler's Special"},fv=true}
E["quest:95294"] = {t="quest",n="Smuggler's Bargain",z="riverglades",s="An Eastsea pirate offers Friz Frazzlespark a bargain to leave her business alone. You carry his message back to her in Powderfuse Port.",h="An Eastsea pirate offers Friz Frazzlespark a bargain to leave her business alone.",sec={{t="A Captain's Offer",b="Friz Frazzlespark has drawn the Eastsea pirates' attention, and one of them offers to keep his crew from interfering with her business. In return, he proposes a profitable arrangement. You carry his message back to Friz in Powderfuse Port, where she will hear who claims command.",sp=0},{t="Friz's Lesson",b="Friz answers the pirate's offer with a warning about the cost of crossing her. Her words leave the bargain's terms in doubt.",sp=1}},faq={{q="What does the pirate offer Friz?",a="An Eastsea pirate offers to keep his crew from interfering with Friz's business and proposes a profitable arrangement.",al={"eastsea pirate offer","friz bargain"}},{q="Who do I report back to?",a="You return to Friz Frazzlespark in Powderfuse Port.",al={"where return","who gets the message"}},{q="What message does the captain send?",a="He wants Friz to know that a new captain is in charge and foresees a profitable relationship.",al={"captain message","what tell friz"}},{q="Who is the new captain?",a="Friz questions who the captain is, and the message does not name him.",al={"captain who","pirate boss"}}},kw={"captain","eastsea pirates","friz frazzlespark","goblin","pirate","powderfuse port","smuggler's bargain"},rel={"topic:goblin","topic:pirate"},m={id=95294},src={"In-game quest text: Smuggler's Bargain"},fv=true}
E["quest:95295"] = {t="quest",n="I Know a Guy",z="riverglades",s="Friz sends you to Booty Bay to meet her contact, Ruzzgot. The contact gets goods from the local freebooters and will explain what comes next.",h="Friz sends you to Booty Bay to meet her contact, Ruzzgot.",sec={{t="A Contact in Booty Bay",b="Friz says her contact is Ruzzgot, waiting in Booty Bay. He gets goods from the pirates there, whom Friz calls freebooters. Find Ruzzgot, and he will explain the rest.",sp=0}},faq={{q="Who is Friz's contact?",a="Friz names Ruzzgot as his contact in Booty Bay.",al={"friz contact","who is Ruzzgot","booty bay contact"}},{q="Where does Friz send me?",a="Friz sends you to Booty Bay to meet Ruzzgot.",al={"where to go","where is Ruzzgot","booty bay"}},{q="What does Ruzzgot do?",a="Ruzzgot gets goods from the local pirates in Booty Bay.",al={"what does the contact do","ruzzgot goods","pirate goods"}},{q="Why does Friz call the pirates freebooters?",a="Friz says some people call pirates freebooters, and jokes that the word contains “free booty.”",al={"freebooter meaning","pirates or freebooters","why freebooters"}}},kw={"booty bay","contact","freebooters","friz","goods","i know a guy","pirates","ruzzgot"},rel={"subzone:booty-bay","topic:pirate"},m={id=95295},src={"In-game quest text: I Know a Guy"},fv=true}
E["quest:95296"] = {t="quest",n="Shipping and Handling",z="riverglades",s="Your employer asks you to carry a crate to Steamwheedle Port. A goblin there is expected to pay his dues.",h="Your employer asks you to carry a crate to Steamwheedle Port.",sec={{t="A Crate to Deliver",b="Your employer is busy negotiating in town, so she gives you a crate for her associate. She expects you to take a ship from the docks to Steamwheedle Port in Tanaris. There, Wharfmaster Steamfizzle is the one to speak with, and a goblin's dues are at stake.",sp=0}},faq={{q="Who gave me the crate?",a="Your employer gives you the crate while she handles negotiations in town.",al={"crate delivery","who sent me","shipping job"}},{q="Where does the crate go?",a="The crate is meant for your employer's associate at Steamwheedle Port in Tanaris.",al={"crate destination","where to deliver","steamwheedle delivery"}},{q="Who do I speak with at Steamwheedle Port?",a="At Steamwheedle Port, the named contact is Wharfmaster Steamfizzle.",al={"wharfmaster","steamfizzle","port contact"}},{q="Why am I carrying a crate?",a="Your employer asks you to deliver the crate because she is busy negotiating in town.",al={"why crate","what's in the crate","delivery reason"}},{q="What is the goblin supposed to do?",a="Your employer expects a goblin at Steamwheedle Port to pay his dues.",al={"goblin dues","pay his dues","why goblin"}}},kw={"crate","delivery","dues","goblin","shipping and handling","steamwheedle port","tanaris","wharfmaster steamfizzle"},rel={"subzone:steamwheedle-port","zone:tanaris","topic:goblin"},m={id=95296},src={"In-game quest text: Shipping and Handling"},fv=true}
E["quest:95329"] = {t="quest",n="Out in the Field",z="riverglades",s="A watcher at Terral's Watch observes the plains for movements by the Horde. You are asked to get his status report.",h="A watcher at Terral's Watch observes the plains for movements by the Horde.",sec={{t="A Remote Watch",b="A tower watches over the northern plains from Terral's Watch. Watcher Cornelius is stationed there alone to track movement among the Horde's forces. His post is remote, and he is known to speak little. You are asked to speak with him and bring back a status report.",sp=0}},faq={{q="Who is Cornelius?",a="Cornelius is the watcher stationed alone at Terral's Watch, where he observes the plains for movement by the Horde.",al={"watcher cornelius","who's the watcher","cornelius report"}},{q="What is Terral's Watch?",a="Terral's Watch is an observation post overlooking the northern plains, used to track movement by the Horde's forces.",al={"terral watch","watch tower","tower in the north"}},{q="What report am I meant to get?",a="You are asked to speak with Watcher Cornelius at Terral's Watch and get a status report.",al={"status report","what does cornelius need","cornelius task"}},{q="Why is Cornelius stationed alone?",a="Cornelius is stationed alone at the remote watch post. He is known to be taciturn, and that is given as the reason for his assignment there.",al={"why is he alone","cornelius post","why assigned there"}}},kw={"cornelius","horde","observation tower","out in the field","status report","terral's watch","watcher"},rel={"topic:horde"},m={faction="Alliance",id=95329},src={"In-game quest text: Out in the Field"},fv=true}
E["quest:95330"] = {t="quest",n="Love Thy Neighbor",z="riverglades",s="Cassandra Wheeler asks you to bring her farm's surplus produce to Halligan Turner at Turner's Logging Camp. She hopes the workers can enjoy some variety in their meals.",h="Cassandra Wheeler asks you to bring her farm's surplus produce to Halligan Turner at Turner's Logging Camp.",sec={{t="A Neighbor's Gift",b="Cassandra Wheeler farms north of Farholde and brings her harvest there to sell. She sets aside what remains for people who could use a lift. The logging camp lies north of her farm, beside the river, and she thinks its workers could use fruit and vegetables. You carry her surplus to Halligan Turner, the camp foreman.",sp=0},{t="At the Camp",b="Halligan Turner receives the goods with gratitude. The workers have little beyond meat and bread, so he plans to share the produce among them. He hopes to return Cassandra's kindness in time.",sp=1}},faq={{q="Who is asking for the delivery?",a="Cassandra Wheeler asks you to carry her farm's surplus produce to Halligan Turner.",al={"who wants this","cassandra request","farm goods quest"}},{q="Who is Halligan Turner?",a="Halligan Turner is the foreman at Turner's Logging Camp.",al={"halligan who","logging camp foreman","turner guy"}},{q="Where is the logging camp?",a="Turner's Logging Camp is north of Cassandra's farm, beside the river.",al={"where's turner's camp","camp location","logging camp"}},{q="What goods does Cassandra send?",a="She sends surplus fruit and vegetables from her farm.",al={"what am i delivering","farm produce","cassandra's goods"}},{q="Why does Cassandra set aside farm goods?",a="After harvest, Cassandra saves what she does not sell to give to people who could use a lift.",al={"why give food","cassandra's reason","helping neighbors"}},{q="What do the logging camp workers usually eat?",a="Halligan says the workers eat little besides meat and bread.",al={"what do loggers eat","camp workers' food","meat and bread"}}},kw={"cassandra wheeler","farholde","farm goods","fruit","halligan turner","love thy neighbor","turner's logging camp","vegetables"},m={faction="Alliance",id=95330},src={"In-game quest text: Love Thy Neighbor"},fv=true}
E["quest:95417"] = {t="quest",n="The Purple Ones",z="riverglades",s="Clubtoe asks you to look for ogres missing from the caves beneath Sunnyglade. Some who return are changed, and he wants to understand why.",h="Clubtoe asks you to look for ogres missing from the caves beneath Sunnyglade.",sec={{t="Clubtoe's Concern",b="Clubtoe has watched friends go into the caves beneath Sunnyglade and fail to return. Some come back purple and no longer act like his friends. He asks you to search the caves for the missing ogres, though he fears you may return changed as well.",sp=0},{t="In the Caves",b="Beneath Sunnyglade, you find an ogre dead among dark runes. The powers of the Twilight Hammer's ritual have overwhelmed him.",sp=1}},faq={{q="Who is Clubtoe?",a="Clubtoe is an ogre whose friends have gone missing in the caves beneath Sunnyglade.",al={"clubtoe","who's clubtoe"}},{q="Why does Clubtoe ask me to search the caves?",a="Some of Clubtoe's friends do not return from the caves, and some who come back are purple and act differently.",al={"missing ogres","find clubtoe's friends","cave ogres"}},{q="Where are the missing ogres?",a="Clubtoe asks you to look for the missing ogres in the caves beneath Sunnyglade.",al={"where ogres go","sunnyglade cave","ogres missing"}},{q="What is strange about the ogres who return?",a="Some return purple and no longer act like Clubtoe's friends.",al={"purple ogres","why purple","ogres act weird"}}},kw={"caves","clubtoe","dark runes","missing ogres","ogres","purple","sunnyglade","the purple ones","twilight hammer"},rel={"subzone:sunnyglade"},m={faction="Horde",id=95417},src={"In-game quest text: The Purple Ones"},fv=true}
E["quest:95418"] = {t="quest",n="Spread the Word",z="riverglades",s="Clubtoe asks you to bring Chogg'Zac's head to Tran'gul in Rog'mar after he leaves the Twilight's Hammer. Word of the defection may lead to more of the cult's ogres breaking free.",h="Clubtoe asks you to bring Chogg'Zac's head to Tran'gul in Rog'mar after he leaves the Twilight's Hammer.",sec={{t="A Message for Tran'gul",b="Chogg'Zac's head is to go back to your friends, and Tran'gul in Rog'mar is the one to receive it. Clubtoe says he is done with the Twilight's Hammer and plans to join Clugfist, the biggest ogre he knows, with many others. Clubtoe means to stay where he is until the coast is clear. Now Tran'gul must hear what Clubtoe has chosen.",sp=0},{t="News from the Cave",b="Tran'gul hears that the cave held another surprise. You have convinced one of the Twilight's Hammer ogres to defect, and he spoke of others of his kind. Tran'gul says they must act on this news at once.",sp=1}},faq={{q="Who is Clubtoe?",a="Clubtoe is an ogre who says he is done with the Twilight's Hammer and plans to join the free ogres.",al={"clubtoe","clubtoe ogre","who is clubtoe"}},{q="Who is Clugfist?",a="Clugfist is the biggest ogre Clubtoe knows, and Clubtoe says he left the Twilight's Hammer with many friends.",al={"clugfist","clugfist ogre","biggest ogre"}},{q="What does Clubtoe ask me to bring?",a="Clubtoe asks you to take Chogg'Zac's head back to his friends.",al={"chogg head","chogg'zac head","what to take"}},{q="Where do I take Chogg'Zac's head?",a="You are to deliver Chogg'Zac's head to Tran'gul in Rog'mar.",al={"where to take head","tran'gul","rog'mar"}},{q="Why is Tran'gul concerned?",a="Tran'gul learns that one Twilight's Hammer ogre has defected and mentioned others of his kind.",al={"tran'gul reaction","twilight cave","why act now"}}},kw={"chogg'zac","clubtoe","clugfist","ogre defection","rog'mar","spread the word","tran'gul","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=95418},src={"In-game quest text: Spread the Word"},fv=true}
E["quest:95420"] = {t="quest",n="Land of Giants",z="riverglades",s="An orc asks you to carry Chogg’s head to an ogre city in the northern hills. The offering may open a way to renew an old bond with the ogres.",h="An orc asks you to carry Chogg’s head to an ogre city in the northern hills.",sec={{t="An Old Bond",b="The orcs see a chance to renew their old alliance with ogres. Reports place the clan’s home in a stronghold among the northern hills, and Chogg’s head is meant to speak for you. Carry it to the ogre city and offer it as a token of friendship. The clan may hear your proposal, if they do not trample you first.",sp=0},{t="At Clugfist’s Door",b="At the ogre city, you present Chogg’s head to Clugfist. He recognizes that you have defeated Chogg’Zac and asks what you want with him. The offer of friendship has opened a chance to speak with the clan’s leader.",sp=1}},faq={{q="Why am I bringing Chogg’s head to the ogres?",a="The orcs hope Chogg’s head will serve as a token of friendship and help renew their old alliance with the ogres.",al={"chogg head","why take chogg head","ogre head offering"}},{q="Where is the ogre clan’s home?",a="Reports place the clan’s stronghold in the hills far to the north.",al={"ogre city location","where are the ogres","northern hills ogres"}},{q="Who is Clugfist?",a="Clugfist is the massive ogre you meet at the ogre city. He asks what you want with him.",al={"clugfist who","ogre leader","clug fist"}},{q="Who is Chogg’Zac?",a="Chogg’Zac is the ogre Clugfist says you have defeated.",al={"chogg zac","chogg backstory","who is chogg"}},{q="What do the orcs want from the ogres?",a="The orcs hope to call upon their old alliance with ogres and present a proposal to the clan.",al={"orc ogre alliance","what do orcs want","ogre friendship"}}},ang={["race:Orc"]="As an orc, you carry an offer rooted in the honored history of orcs fighting beside ogres."},kw={"chogg","chogg’zac","clugfist","land of giants","northern hills","ogre city","ogres","orc alliance"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=95420},src={"In-game quest text: Land of Giants"},fv=true}
E["quest:95424"] = {t="quest",n="Might Makes Right",z="riverglades",s="Clugfist challenges you to prove your strength in Bolder'ok. Twilight's Hammer ogres are the test.",h="Clugfist challenges you to prove your strength in Bolder'ok.",sec={{t="Clugfist's Test",b="Clugfist judges strength by blood, and sends you against the Twilight Maulers and Twilight Firecallers in Bolder'ok. He doubts your size, yet gives you the chance to show what you can do. The challenge puts your strength against the Twilight ogres.",sp=0}},faq={{q="Who is Clugfist?",a="Clugfist is the ogre in Bolder'ok who challenges you to prove your strength.",al={"clugfist","who's clugfist","ogre guy"}},{q="What does Clugfist want me to do?",a="Clugfist asks you to kill Twilight Maulers and Twilight Firecallers in Bolder'ok.",al={"what does clugfist want","clugfist task","what do i kill"}},{q="Why does Clugfist doubt me?",a="Clugfist calls you tiny and questions whether you are strong.",al={"why doubt me","too tiny","clugfist thinks weak"}},{q="What is Bolder'ok like?",a="Bolder'ok is where Clugfist says ogres value strength and blood.",al={"bolderok","bolder'ok ogres","what happens here"}}},kw={"bolder'ok","clugfist","might makes right","ogres","skyborne","twilight firecallers","twilight maulers","twilight's hammer"},rel={"topic:twilight-s-hammer","topic:skyborne"},m={faction="Horde",id=95424},src={"In-game quest text: Might Makes Right"},fv=true}
E["quest:95425"] = {t="quest",n="Unworthy Champion",z="riverglades",s="Clugfist in Bolder'ok wants you to recover Skullbasher from Klunk. He no longer considers Klunk worthy of the weapon.",h="Clugfist in Bolder'ok wants you to recover Skullbasher from Klunk.",sec={{t="Clugfist's Demand",b="Clugfist sends you after Klunk, who left Bolder'ok and took ogres with him to a cave east of the water. He wants his weapon back and calls Klunk weak. Skullbasher is the mark of a champion in Clugfist's eyes, and he means to choose another.",sp=0}},faq={{q="Who is Klunk?",a="Klunk was once Clugfist's champion, but Clugfist now calls him weak.",al={"klunk who","klunk backstory"}},{q="Who is Clugfist?",a="Clugfist is the ogre who gave Klunk a mighty weapon and now wants it back.",al={"clugfist who","clugfist ogre"}},{q="Why does Clugfist want Skullbasher?",a="Clugfist says Skullbasher belongs to him and calls Klunk unworthy of it.",al={"why take skullbasher","clugfist weapon"}},{q="Where did Klunk go?",a="Klunk left Bolder'ok with ogres and went to a cave east of the water.",al={"klunk location","where klunk go"}},{q="What is Skullbasher?",a="Skullbasher is the mighty weapon Clugfist gave Klunk.",al={"skullbasher weapon","klunk's weapon"}},{q="What does Clugfist plan to do next?",a="Clugfist says he will choose a new champion someday.",al={"new champion","clugfist plans"}}},kw={"bolder'ok","cave","clugfist","klunk","ogre champion","skullbasher","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=95425},src={"In-game quest text: Unworthy Champion"},fv=true}
E["quest:95426"] = {t="quest",n="Rog'mar Supplies",z="riverglades",s="A local contact asks you to hinder Rog'mar by taking supply shipments from its training grounds to the north. The delay could leave Horde forces less ready for battle.",h="A local contact asks you to hinder Rog'mar by taking supply shipments from its training grounds to the north.",sec={{t="A Supply Shortage",b="A contact near Rog'mar sees a chance to slow the orcs' growth. You are asked to take their supply shipments from the training grounds north of Rog'mar. Supply deliveries here are difficult, and the theft is meant to delay the Horde's preparations for battle.",sp=0}},faq={{q="What am I being asked to do?",a="You are asked to take Horde supply shipments from the training camps north of Rog'mar.",al={"rog'mar supplies","steal shipments","supply theft"}},{q="Why take the supplies?",a="The theft is intended to delay Rog'mar's growth and keep Horde forces from being as ready for battle.",al={"why steal supplies","slow rog'mar","horde supplies"}},{q="Where are the shipments?",a="The Horde supply shipments are at the training camps north of Rog'mar.",al={"where are supplies","training camps","north of rog'mar"}}},kw={"horde","rog'mar","shipment","supplies","supply delivery","training camps"},rel={"topic:horde"},m={faction="Alliance",id=95426},src={"In-game quest text: Rog'mar Supplies"},fv=true}
E["quest:95427"] = {t="quest",n="Twilight No More!",z="riverglades",s="Clubtoe asks you to confront Chogg'Zac in the Sunnyglade cave. He blames them for his friends' deaths and their promise to make ogres strong.",h="Clubtoe asks you to confront Chogg'Zac in the Sunnyglade cave.",sec={{t="Clubtoe's Plea",b="Clubtoe says his friends are dead and blames Chogg'Zac. They promised to make ogres strong, but he says they lied. So he asks you to help him turn against them in the Sunnyglade cave. He wants their heads, and he will smash no more rocks for them.",sp=0},{t="A New Name",b="After Chogg'Zac die, Clubtoe cries out in triumph. He says he is done smashing rocks for tinies and done losing friends. He names himself Twilight no more.",sp=1}},faq={{q="Who is Clubtoe?",a="Clubtoe is an ogre who says Chogg'Zac promised to make ogres strong. He blames them for his friends' deaths.",al={"clubtoe","who's clubtoe","clubtoe backstory"}},{q="Why does Clubtoe want Chogg'Zac dead?",a="Clubtoe says Chogg'Zac lied about making ogres strong and blames them for his friends' deaths.",al={"why kill chogg'zac","chogg zac reason","chogg'zac quest"}},{q="Where are Chogg'Zac?",a="Chogg'Zac are in the Sunnyglade cave.",al={"chogg'zac location","where chogg zac","sunnyglade cave"}},{q="What does Clubtoe want from you?",a="Clubtoe asks you to kill Chogg'Zac and collect their heads.",al={"clubtoe wants what","what to get for clubtoe","clubtoe heads"}}},kw={"cave","chogg'zac","clubtoe","friends","ogres","sunnyglade","twilight"},rel={"subzone:sunnyglade","topic:skyborne"},m={faction="Horde",id=95427},src={"In-game quest text: Twilight No More!"},fv=true}
E["quest:95428"] = {t="quest",n="Clugfist's Decree",z="riverglades",s="Clugfist permits you to remain in Bolder'ok for now after the Skyborne defeat the Twilight's Hammer. He asks you to tell the others that the clan will fight again soon.",h="Clugfist permits you to remain in Bolder'ok for now after the Skyborne defeat the Twilight's Hammer.",sec={{t="Word for Rog'mar",b="Krom'rosh in Rog'mar is waiting to hear from you. Clugfist lets you stay in Bolder'ok for now and asks you to carry word to the other Skyborne. The clan expects bloodshed again soon.",sp=0},{t="Trust and Alliances",b="Krom'rosh sees the Bolder'ok clan as a possible ally for the Horde. Their recent fight for freedom from the Twilight's Hammer echoes the Horde's own bloody history. Your report may help the Horde continue to earn their trust.",sp=1}},faq={{q="What does Clugfist want me to do?",a="Clugfist asks you to tell the other Skyborne that the Bolder'ok clan expects to fight again soon.",al={"clugfist decree","what am i supposed to report","clugfist's orders"}},{q="Where do I report?",a="Clugfist directs you to report to Krom'rosh in Rog'mar.",al={"report to kromrosh","where is krom'rosh","rogmar report"}},{q="Can I stay in Bolder'ok?",a="Clugfist permits you to remain in Bolder'ok for now.",al={"stay in bolderok","clugfist lets me stay","bolder'ok permission"}},{q="Who are the Bolder'ok?",a="The Bolder'ok are a clan that recently fought for freedom from the Twilight's Hammer.",al={"bolderok clan","who is clugfist","clugfist people"}},{q="Why does the Horde care about the Bolder'ok?",a="Krom'rosh believes the Bolder'ok could become powerful allies if the Horde continues to earn their trust.",al={"horde and bolderok","bolderok allies","why does kromrosh care"}}},ang={["faction:Horde"]="As a member of the Horde, the Bolder'ok may become powerful allies if your people continue to earn their trust."},kw={"bolder'ok","bolderok","clugfist","decree","horde","krom'rosh","rog'mar","skyborne","twilight's hammer"},rel={"topic:skyborne","topic:twilight-s-hammer","topic:horde"},m={faction="Horde",id=95428},src={"In-game quest text: Clugfist's Decree"},fv=true}
E["quest:95431"] = {t="quest",n="Rumblings of Discontent",z="riverglades",s="A scout asks you to find a Bolder'ok warrior in a cave west of here. Ogre dissidents seek the freedom their Bolder'ok kin have found.",h="A scout asks you to find a Bolder'ok warrior in a cave west of here.",sec={{t="A Scout's Request",b="A scout has found dissidents among the ogres who seek the freedom of their Bolder'ok kin. Word of your deeds has reached the scout, who asks you to find a Bolder'ok warrior in a cave west of here and join his effort to rally his people.",sp=0},{t="A Familiar Name",b="In the cave, the Bolder'ok warrior Crag'rog recognizes you as a fighter for Clugfist.",sp=1}},faq={{q="Who am I looking for?",a="A Bolder'ok warrior is in a nearby cave west of the scout.",al={"bolder'ok warrior","ogre in cave"}},{q="Why am I being sent to find him?",a="The scout asks you to join the warrior's effort to rally the ogres seeking freedom.",al={"why find bolder'ok","what does scout want"}},{q="Who is Crag'rog?",a="Crag'rog is the Bolder'ok warrior in the cave.",al={"cragrog","who's crag'rog"}},{q="What do the ogre dissidents want?",a="The dissidents seek the same freedom as their Bolder'ok kin.",al={"ogre rebels","bolder'ok freedom"}}},kw={"bolder'ok","clugfist","crag'rog","freedom","ogre dissidents","rumblings of discontent"},m={faction="Horde",id=95431},src={"In-game quest text: Rumblings of Discontent"},fv=true}
E["quest:95432"] = {t="quest",n="Rise Up!",z="riverglades",s="Crag'rog asks you to help free ogres from the Twilight. He wants them back home for stew.",h="Crag'rog asks you to help free ogres from the Twilight.",sec={{t="Ogres and Twilight",b="Crag'rog wants ogres freed from the Twilight, and he welcomes your help. Together, you recruit ogre miners to join the fight. Crag'rog says the ogres can then go home for stew.",sp=0},{t="Crag'rog's Count",b="Crag'rog says many ogres are free, and the weak, cowardly ogres are dead. He counts only one cowardly ogre left.",sp=1}},faq={{q="Who is Crag'rog?",a="Crag'rog is an ogre who wants ogres freed from the Twilight.",al={"cragrog","who's crag'rog"}},{q="Why does Crag'rog want to free ogres?",a="He heard you were freeing ogres, and now he wants to free them too.",al={"why free ogres","ogres freedom"}},{q="Who does Crag'rog fight alongside?",a="Crag'rog fights the Twilight alongside you.",al={"who helps crag'rog","tiny class"}},{q="What does Crag'rog ask you to recruit?",a="Crag'rog asks you to recruit ogre miners.",al={"recruit ogres","ogre miners"}},{q="What does Crag'rog say about the ogres afterward?",a="Crag'rog says many ogres are free, and only one cowardly ogre remains.",al={"what happened to ogres","crag'rog completion"}}},kw={"crag'rog","free ogres","ogre miners","ogres","rise up","stew","twilight"},m={faction="Horde",id=95432},src={"In-game quest text: Rise Up!"},fv=true}
E["quest:95433"] = {t="quest",n="Death to the Executioner",z="riverglades",s="Clugfist asks you to face Morg, the ogre guarding the way out of Twilight. He wants Morg’s mace returned to Bolder’ok.",h="Clugfist asks you to face Morg, the ogre guarding the way out of Twilight.",sec={{t="A Way Out",b="Clugfist, in Bolder’ok, asks you to take on Morg in the Twilight Shroud. The executioner is an ogre nearly as large as Clugfist, and Clugfist says he relies on smaller allies for protection. Bring the mace back to him, and Twilight’s Hammer will know the ogres challenge them no more.",sp=0},{t="Bolder’ok’s Answer",b="Crag’rog says you have joined him in the fight, and Clugfist asks what you bring. Morg is dead, and Clugfist praises your tricks. He says Twilight’s Hammer has crumpled beneath Bolder’ok’s might, and the ogres are free.",sp=1}},faq={{q="Who is Morg?",a="Morg is an executioner in the Twilight Shroud, an ogre nearly as large as Clugfist.",al={"morg who","executioner morg","twilight ogre"}},{q="Why does Clugfist want Morg dead?",a="Clugfist says Morg stands in the way as he leaves Twilight, and that Morg relies on smaller allies for protection.",al={"why kill morg","clugfist wants morg","morg problem"}},{q="What does Clugfist want you to bring back?",a="Clugfist wants Morg’s Executioner’s Mace returned to him in Bolder’ok.",al={"morg mace","bring back what","executioner's mace"}},{q="Where is Morg?",a="Morg is in the Twilight Shroud.",al={"morg location","where executioner","twilight shroud"}}},ang={["race:Tauren"]="As a tauren, Clugfist calls you a tiny tauren full of tricks after Morg is dead."},kw={"bolder'ok","clugfist","crag'rog","executioner morg","executioner's mace","morg","twilight shroud","twilight's hammer"},rel={"topic:twilight-s-hammer"},m={faction="Horde",id=95433},src={"In-game quest text: Death to the Executioner"},fv=true}
E["quest:95561"] = {t="quest",n="Apple of My Eye",z="riverglades",s="At Farholde Keep, Tessa Dawnbright asks you to find apples for fussy baby Emma. She hopes to make the child a mash.",h="At Farholde Keep, Tessa Dawnbright asks you to find apples for fussy baby Emma.",sec={{t="A Fussy Child",b="Tessa Dawnbright is caring for baby Emma in Farholde Keep, where the child's cries ring through the keep. Tessa says her hands are full while her husband is away gathering supplies. She asks you to find fresh apples so she can make Emma a mash.",sp=0}},faq={{q="Who is asking for apples?",a="Tessa Dawnbright asks you to find apples for baby Emma at Farholde Keep.",al={"Tessa apples","who needs apples","apple quest giver"}},{q="Why does Tessa need apples?",a="Tessa hopes to make a mash for fussy baby Emma.",al={"why apples","apples for baby","what are apples for"}},{q="Where does Tessa need help?",a="Tessa asks for help at Farholde Keep.",al={"where is Tessa","Farholde apples","apple location"}},{q="Why can't Tessa get the supplies herself?",a="Tessa says her hands are too full caring for Emma while her husband is out for supplies.",al={"Tessa husband","where is her husband","why can't she go"}}},kw={"apple mash","apple of my eye","baby","emma","farholde keep","fresh apples","tessa dawnbright"},m={faction="Alliance",id=95561},src={"In-game quest text: Apple of My Eye"},fv=true}
E["quest:95562"] = {t="quest",n="Cut Off the Heads",z="riverglades",s="Apprentice Claire asks you to end the threat beneath Sunnyglade. The cave’s master is Chogg'Zac, and Claire wants its heads brought back.",h="Apprentice Claire asks you to end the threat beneath Sunnyglade.",sec={{t="Claire's Plea",b="Before you enter the caves beneath Sunnyglade, Apprentice Claire tells you why she came. Lady Amberhall sent her to gather samples, but Claire chose to return because Sunnyglade was once her home. Monsters still taint the place, and she wants their master slain. Chogg'Zac waits below, and Claire asks you to bring back the heads.",sp=0},{t="After the Fight",b="When you return, Claire asks whether Chogg'Zac and the ogres are dead. She accepts your deed as right and urges you to leave with her.",sp=1}},faq={{q="Who is asking me to go beneath Sunnyglade?",a="Apprentice Claire asks you to kill Chogg'Zac in the caves beneath Sunnyglade and retrieve the heads.",al={"who sent me","Claire task","apprentice Claire"}},{q="Why did Claire come to Sunnyglade?",a="Sunnyglade was Claire's home before the war took it from her, and she could not rest while monsters remained there.",al={"why Claire here","Claire home","Sunnyglade backstory"}},{q="Who is Chogg'Zac?",a="Chogg'Zac is the master in the caves beneath Sunnyglade.",al={"Chogg Zac","cave master","ogre boss"}},{q="What does Claire want me to bring back?",a="Claire asks you to retrieve the heads after killing Chogg'Zac.",al={"bring what back","heads for Claire","what to retrieve"}}},kw={"apprentice claire","caves","chogg'zac","cut off the heads","lady amberhall","ogres","sunnyglade"},rel={"subzone:sunnyglade","topic:horde"},m={faction="Alliance",id=95562},src={"In-game quest text: Cut Off the Heads"},fv=true}
E["quest:95601"] = {t="quest",n="The Purple Ones",z="riverglades",s="Clubtoe asks you to stop Twilight's Hammer rituals in Sunnyglade. The rites empower some ogres and kill others.",h="Clubtoe asks you to stop Twilight's Hammer rituals in Sunnyglade.",sec={{t="Rites in Sunnyglade",b="In Sunnyglade, Clubtoe sends you against Twilight Ritualists and Empowered Brutes. A dead ogre appears to be one of the friends Clubtoe sought. The rituals strengthen some members and kill more, so Clubtoe wants the ritualists and their creations stopped before they spread.",sp=0}},faq={{q="Who is Clubtoe?",a="Clubtoe is the one asking you to stop the Twilight Ritualists in Sunnyglade.",al={"clubtoe","who's clubtoe"}},{q="What are the Purple Ones doing?",a="The Twilight Ritualists perform rites on their members. Some are empowered, while more are killed.",al={"purple ones","what are the purple ones doing"}},{q="Why does Clubtoe want the rituals stopped?",a="Clubtoe fears the ritualists and their monstrosities will spread.",al={"why stop rituals","why kill ritualists"}},{q="What happened to Clubtoe's friends?",a="A dead ogre appears to be one of the friends Clubtoe was searching for.",al={"clubtoe friends","where friends"}},{q="Where is Clubtoe?",a="Clubtoe is in Sunnyglade.",al={"clubtoe location","sunnyglade clubtoe"}}},kw={"clubtoe","empowered brutes","ogre","sunnyglade","the purple ones","twilight ritualists","twilight's hammer"},rel={"subzone:sunnyglade","topic:twilight-s-hammer"},m={faction="Horde",id=95601},src={"In-game quest text: The Purple Ones"},fv=true}
E["quest:95602"] = {t="quest",n="Sickening Lights",z="riverglades",s="Clubtoe asks you to smash the shining ritual circles beneath Sunnyglade. The light makes him sick, and he fears Chogg'Zac's anger if he acts alone.",h="Clubtoe asks you to smash the shining ritual circles beneath Sunnyglade.",sec={{t="A Sickening Glow",b="Clubtoe works in the caves beneath Sunnyglade, smashing rock for Chogg'Zac. He finds shining lights in the stone, and the others draw pictures with them. The glow makes Clubtoe feel sick, though he fears Chogg'Zac will punish him for breaking the pictures. You are asked to destroy the Twilight Ritual Circles, and Clubtoe hopes the light will trouble him no more.",sp=0}},faq={{q="Who is asking me to break the circles?",a="Clubtoe asks you to destroy the Twilight Ritual Circles beneath Sunnyglade.",al={"who is Clubtoe","clubtoe quest","who wants lights smashed"}},{q="Why does Clubtoe want the lights smashed?",a="The light makes Clubtoe feel sick, and he wants to smash the shining pictures.",al={"why smash lights","lights make Clubtoe sick","clubtoe hate light"}},{q="Who is Chogg'Zac?",a="Chogg'Zac is Clubtoe's boss, and Clubtoe fears he will be angry if the circles are broken.",al={"chogg zac","Clubtoe's boss","big boss"}},{q="What are the shiny pictures?",a="They are Twilight Ritual Circles found throughout the caves beneath Sunnyglade. Clubtoe calls them shining pictures.",al={"shiny pictures","twilight circles","what are the lights"}},{q="What does Clubtoe do in the caves?",a="Clubtoe smashes rock for Chogg'Zac and has found shining light in the stone.",al={"Clubtoe work","smashing rocks","what is Clubtoe doing"}},{q="Does Clubtoe feel better after the circles are smashed?",a="After you smash the circles, Clubtoe says he already feels better.",al={"Clubtoe completion","did smashing help","lights make him better"}}},kw={"caves","chogg'zac","clubtoe","light","shiny pictures","sickening lights","sunnyglade","twilight ritual circles"},rel={"subzone:sunnyglade"},m={faction="Horde",id=95602},src={"In-game quest text: Sickening Lights"},fv=true}
E["quest:95603"] = {t="quest",n="Bats in the Belfry",z="riverglades",s="Sister Rowland asks you to clear bats from Farholde Cathedral. She hopes the church will serve the Light again when the fighting ends.",h="Sister Rowland asks you to clear bats from Farholde Cathedral.",sec={{t="The Cathedral",b="Sister Rowland asks for your help at Farholde Cathedral, where dusk bats roost in the upper stories. She and brother Lowley now serve Farholde in a more secular capacity, and the church has fallen into disuse. Rowland wants to keep it in working order, though she fears the fighting may last a long while.",sp=0}},faq={{q="Why are there bats in the cathedral?",a="A colony of bats has made its roost in the upper stories of Farholde Cathedral.",al={"cathedral bats","bats in belfry","why bats"}},{q="Who asks me to clear the bats?",a="Sister Rowland asks you to remove the roosting bats from Farholde Cathedral.",al={"who gave this","sister rowland","rowland bats"}},{q="Why does Sister Rowland want the church kept in working order?",a="Sister Rowland hopes the Light can return to the church once the fighting ends.",al={"why keep church","church upkeep","rowland church"}},{q="What happened to the church?",a="The church has fallen into disuse since Sister Rowland and brother Lowley began serving Farholde in a more secular capacity.",al={"church abandoned","why disused","farholde church"}}},kw={"bats in the belfry","brother lowley","church","farholde cathedral","light","roosting dusk bats","sister rowland"},rel={"topic:light"},m={faction="Alliance",id=95603},src={"In-game quest text: Bats in the Belfry"},fv=true}
E["quest:95613"] = {t="quest",n="Keeping the Light On",z="riverglades",s="Sister Rowland asks you to bring Holy Candles to Farholde Keep. She keeps them burning in the church crypt for the fallen, so their sacrifices are remembered.",h="Sister Rowland asks you to bring Holy Candles to Farholde Keep.",sec={{t="Candles for the Fallen",b="Sister Rowland at Farholde Keep asks you for Holy Candles. Though service no longer takes place at the church, she keeps candles lit on the graves of the fallen in its crypt. Their flames are a sign that the dead are remembered and their sacrifices were not in vain. Marla, a friend of Sister Rowland, may have candles to spare in the house just outside the church.",sp=0}},faq={{q="Why does Sister Rowland keep candles lit?",a="Sister Rowland keeps candles lit on the graves in the church crypt so the fallen are remembered and their sacrifices are not in vain.",al={"why candles","crypt candles","candles for dead"}},{q="Where does Sister Rowland want the candles brought?",a="Sister Rowland asks you to bring Holy Candles to her at Farholde Keep.",al={"where bring candles","candle delivery","Rowland candles"}},{q="Who is Marla?",a="Marla is a friend of Sister Rowland who lives in the house just outside the church and may have candles to spare.",al={"Marla candles","who has candles","candle source"}},{q="Is there still service at the church?",a="No service is held at the church now, though Sister Rowland continues to keep candles burning in its crypt.",al={"church service","church closed","no service"}}},kw={"church","crypt","fallen","farholde keep","holy candles","keeping the light on","marla","sister rowland"},m={faction="Alliance",id=95613},src={"In-game quest text: Keeping the Light On"},fv=true}
E["quest:95615"] = {t="quest",n="In Memoriam",z="riverglades",s="Sister Rowland asks you to relight memorial candles at Farholde Keep. The small act honors the dead and helps keep the church alive.",h="Sister Rowland asks you to relight memorial candles at Farholde Keep.",sec={{t="Candles for the Fallen",b="At Farholde Keep, Sister Rowland asks you to tend the chapel graveyard. Place fresh candles on three graves where the old flames have gone out, and give the fallen a quiet remembrance.",sp=0}},faq={{q="Who asks me to light the candles?",a="Sister Rowland at Farholde Keep asks you to light memorial candles in the chapel graveyard.",al={"who is sister rowland","sister rowland candles"}},{q="Where do the candles go?",a="Place the memorial candles on graves in the chapel graveyard at Farholde Keep.",al={"candle location","where are the graves"}},{q="How many graves need candles?",a="Sister Rowland asks you to place three memorial candles on graves.",al={"number of candles","how many candles"}},{q="Why light the candles?",a="The candles honor those who have died and help keep the church alive.",al={"why candles","what is this for"}}},kw={"chapel graveyard","church","farholde keep","graves","in memoriam","light","memorial candles","sister rowland"},rel={"topic:light"},m={faction="Alliance",id=95615},src={"In-game quest text: In Memoriam"},fv=true}
E["quest:95642"] = {t="quest",n="Abominable Magics",z="riverglades",s="Apprentice Claire asks you to gather samples of Twilight's Hammer magic in a cave beneath Sunnyglade. Farholde needs the samples so she can study the cult's witchcraft.",h="Apprentice Claire asks you to gather samples of Twilight's Hammer magic in a cave beneath Sunnyglade.",sec={{t="Claire's Request",b="Claire sent by Ashe Amberhall investigates Twilight's Hammer in the Riverglades, where cultists dig for something. She needs a sample of their witchcraft to understand it. You carry a Crystal Catalyst enchanted to absorb the cult's power from runes or cultists, and Claire says Farholde urgently needs what it gathers.",sp=0},{t="A Potent Sample",b="When you return, Claire touches the crystal and flinches at the magic crackling within it. The gathered power is stronger than she feared, and she says it must be handled with care.",sp=1}},faq={{q="Who is asking for the samples?",a="Apprentice Claire asks you to gather samples of Twilight's Hammer magic for her.",al={"who wants samples","Claire sample request"}},{q="Why does Claire need the samples?",a="Claire wants to study the cult's witchcraft, and she says Farholde urgently needs the samples.",al={"why samples","what are samples for"}},{q="Where are the cultists digging?",a="Twilight's Hammer is digging for something within the Riverglades.",al={"where is Twilight Hammer digging","cult digging"}},{q="What does the Crystal Catalyst do?",a="The enchanted Crystal Catalyst absorbs the power of Twilight's Hammer magic from runes or cultists.",al={"crystal thing","catalyst purpose"}},{q="Who sent Claire to investigate?",a="Ashe Amberhall sent Claire to investigate Twilight's Hammer.",al={"who sent Claire","Amberhall"}}},kw={"abominable magics","apprentice claire","ashe amberhall","crystal catalyst","farholde","riverglades","sunnyglade","twilight's hammer","witchcraft"},rel={"zone:riverglades","subzone:sunnyglade","topic:twilight-s-hammer","topic:light"},m={faction="Alliance",id=95642},src={"In-game quest text: Abominable Magics"},fv=true}
E["quest:95643"] = {t="quest",n="Indiscriminate Purge",z="riverglades",s="An apprentice of Lady Amberhall asks you to face void-infused ogres beneath Sunnyglade. The Twilight’s Hammer will feel the losses.",h="An apprentice of Lady Amberhall asks you to face void-infused ogres beneath Sunnyglade.",sec={{t="Below Sunnyglade",b="Lady Amberhall’s apprentice was taken by ogres and their masters in the caves beneath Sunnyglade. She asks you to put down the Twilight Ritualists and Empowered Brutes there. The losses will strike the Twilight’s Hammer.",sp=0}},faq={{q="Who asks for help beneath Sunnyglade?",a="Lady Amberhall’s apprentice asks you to kill the ogres in the caves beneath Sunnyglade.",al={"amberhall apprentice","who is asking","lady amberhall quest"}},{q="What is in the caves?",a="The caves beneath Sunnyglade hold void-infused ogres and their masters.",al={"sunnyglade cave","what ogres","cave enemies"}},{q="Who are the ogres’ masters?",a="The apprentice identifies the ogres’ masters as Twilight Ritualists.",al={"ogre masters","twilight ritualists","who controls ogres"}},{q="Which ogres does the apprentice name?",a="She names Empowered Brutes among the beasts in the caves.",al={"empowered brutes","what ogres to kill","ogre names"}},{q="Why does the apprentice ask you to kill them?",a="She says that nothing good comes from fanatics with a purpose, empowered or otherwise.",al={"why kill ogres","why purge","why help amberhall"}},{q="What does the apprentice say about her own abilities?",a="She says she is usually capable of handling things on her own, but the ogres captured her.",al={"apprentice captured","amberhall apprentice capable","what happened to her"}}},kw={"apprentice","empowered brutes","indiscriminate purge","lady amberhall","sunnyglade","twilight ritualists","twilight's hammer","void-infused ogres"},rel={"subzone:sunnyglade","topic:twilight-s-hammer"},m={faction="Alliance",id=95643},src={"In-game quest text: Indiscriminate Purge"},fv=true}
E["quest:95792"] = {t="quest",n="Clear 'em Out",z="riverglades",s="Gelinda Coppergleam wants the dragons cleared from a cave rich in mineral deposits. She offers a reward and a share if her mining venture turns a profit.",h="Gelinda Coppergleam wants the dragons cleared from a cave rich in mineral deposits.",sec={{t="A Cave Venture",b="Gelinda Coppergleam has found mineral deposits in the cave behind her, but Cinderscale dragons are in the way. She asks you to clear them out so she can bring in a mining crew. In return, she offers a reward and promises you a cut if the venture earns a profit.",sp=0}},faq={{q="Who is Gelinda Coppergleam?",a="Gelinda Coppergleam is planning a mining venture in a cave rich with mineral deposits.",al={"gelinda","who's gelinda","coppergleam"}},{q="What does Gelinda want cleared out?",a="Gelinda asks you to clear the Cinderscale whelps and warriors from the cave.",al={"clear em out","what's in the cave","dragon problem"}},{q="What is in the cave?",a="The cave has untapped mineral deposits, along with Cinderscale whelps and warriors.",al={"cave minerals","mineral deposits","what's behind gelinda"}},{q="What does Gelinda offer?",a="Gelinda offers a reward and promises you a share once her mining venture turns a profit.",al={"what's the reward","gelinda's deal","mining cut"}}},kw={"cave","cinderscale warriors","cinderscale whelps","clear 'em out","gelinda coppergleam","mineral deposits","mining"},m={id=95792},src={"In-game quest text: Clear 'em Out"},fv=true}
E["quest:95882"] = {t="quest",n="WANTED: Scoutmaster Vargas",z="riverglades",s="Neza Bloodsnout wants Scoutmaster Vargas stopped after his scouting has hindered the Horde. His eye is demanded as proof that he is gone.",h="Neza Bloodsnout wants Scoutmaster Vargas stopped after his scouting has hindered the Horde.",sec={{t="Neza's Pursuit",b="Neza Bloodsnout has already taken one of Scoutmaster Vargas's eyes, but the human escaped. His scouting makes it harder for the Horde to track Alliance movements. Now Neza asks you to bring back Vargas's other eye as proof that the scoutmaster is no more.",sp=0},{t="The Report",b="Neza hears that Vargas is dead and says the Riverglades are safer for the Horde. She regrets that he did not live blind after all he had seen.",sp=1}},faq={{q="Who is Scoutmaster Vargas?",a="Scoutmaster Vargas is a human leading an Alliance scouting party on a small island northeast of Rog'mar.",al={"vargas","who's vargas"}},{q="Why does Neza want Vargas dead?",a="Vargas's scouting has made it harder for the Horde to track enemy movements, and Neza says he knows she is hunting him.",al={"why kill vargas","neza vargas"}},{q="Where was Vargas seen?",a="An Alliance scouting party led by Vargas was seen on a small island northeast of Rog'mar.",al={"vargas island","where is scoutmaster"}},{q="What does Neza ask me to bring back?",a="Neza asks you to bring her Scoutmaster Vargas's other eye as proof that he is gone.",al={"vargas eye","what proof"}},{q="Who is Neza Bloodsnout?",a="Neza Bloodsnout is in Rog'mar and wants proof that Scoutmaster Vargas is no more.",al={"neza","who wants vargas"}},{q="What does Neza say after Vargas dies?",a="Neza accepts that Vargas is dead and says the Riverglades are safer for the Horde.",al={"vargas ending","what happens after"}}},ang={["faction:Horde"]="As a member of the Horde, you help Neza remove an Alliance scoutmaster whose tracking has hindered Horde movements."},kw={"alliance scout","neza bloodsnout","riverglades","rog'mar","scouting party","scoutmaster vargas","scoutmaster's eye"},rel={"zone:riverglades","topic:horde","topic:alliance","topic:human"},m={faction="Horde",id=95882},src={"In-game quest text: WANTED: Scoutmaster Vargas"},fv=true}
E["quest:95912"] = {t="quest",n="WANTED: Blademaster Kaijo",z="riverglades",s="Ember Bladewhisper seeks Blademaster Kaijo at a trainee camp north of the Horde outpost. His banner is meant to weaken the orcs’ morale and strengthen the resolve of Ember’s trainees.",h="Ember Bladewhisper seeks Blademaster Kaijo at a trainee camp north of the Horde outpost.",sec={{t="A Faltering Fight",b="Ember Bladewhisper fears that each fallen orc is replaced by a more capable soldier. She believes a blademaster is training them, and says Kaijo is likely at the trainee camp north of the Horde outpost. You are asked to bring his banner to Farholde Keep.",sp=0},{t="A Banner's Purpose",b="Ember says the orc threat seems endless, and her soldiers’ resolve is fading. She hopes Kaijo’s banner will show her trainees that the Horde is nothing to fear.",sp=0}},faq={{q="Who is Blademaster Kaijo?",a="Ember Bladewhisper identifies Kaijo as a blademaster who is likely training orcs at a trainee camp north of the Horde outpost.",al={"who is kaijo","kaijo backstory"}},{q="Why does Ember want Kaijo found?",a="Ember believes Kaijo is training a new generation of capable orc soldiers and fears their numbers will recover.",al={"why find kaijo","kaijo wanted reason"}},{q="Where does Ember think Kaijo is?",a="Ember says Kaijo is likely at the trainee camp north of the Horde outpost.",al={"where kaijo","kaijo location"}},{q="What does Ember want brought to Farholde Keep?",a="Ember asks you to bring the Blademaster’s Banner to her at Farholde Keep.",al={"kaijo banner","bring what to farholde"}},{q="Why does Ember want the banner?",a="Ember hopes the banner will weaken orc morale and reassure her trainees that the Horde is nothing to fear.",al={"banner purpose","why take kaijo banner"}},{q="What worries Ember about the fight?",a="Ember fears the orc threat is unending and that her soldiers’ resolve is flagging.",al={"ember worried","orc threat"}}},kw={"blademaster kaijo","blademaster's banner","ember bladewhisper","farholde keep","horde outpost","kaijo","orc trainees","trainee camp"},rel={"topic:horde"},m={faction="Alliance",id=95912},src={"In-game quest text: WANTED: Blademaster Kaijo"},fv=true}
E["quest:95913"] = {t="quest",n="Fit for a Princess",z="riverglades",s="Tessa Dawnbright needs warm coyote pelts for her daughter Emma’s bassinet in Farholde Keep. She hopes softer bedding will help the baby sleep and bring quiet to Farholde.",h="Tessa Dawnbright needs warm coyote pelts for her daughter Emma’s bassinet in Farholde Keep.",sec={{t="A Mother's Request",b="Tessa rocks Emma in Farholde Keep, hoping to settle her crying daughter. Her husband made a bassinet, but Tessa worries its blankets are too old. She asks you to bring coyote pelts to line Emma’s bed, hoping the warmer bedding will soothe her.",sp=0},{t="A Welcome Return",b="Tessa greets you when you return with the pelts. She finds them warm and soft, and says they are for Emma. Tessa looks tired as she cares for her baby.",sp=0}},faq={{q="Who is Tessa Dawnbright?",a="Tessa Dawnbright is Emma’s mother in Farholde Keep.",al={"who's tessa","tessa dawnbright"}},{q="Who is Emma?",a="Emma is Tessa Dawnbright’s daughter.",al={"tessa's baby","emma baby"}},{q="Why does Tessa need coyote pelts?",a="Tessa wants to line Emma’s bassinet with warm, soft pelts because she worries the blankets are too old.",al={"why pelts","coyote pelts for tessa"}},{q="Where does Tessa live?",a="Tessa is in Farholde Keep.",al={"where is tessa","farholde tessa"}},{q="What is wrong with Emma?",a="Emma is crying, and Tessa is trying to help her sleep.",al={"why is baby crying","emma crying"}}},kw={"baby","bassinet","blankets","coyote pelts","emma","farholde keep","tessa dawnbright"},m={faction="Alliance",id=95913},src={"In-game quest text: Fit for a Princess"},fv=true}
E["quest:95934"] = {t="quest",n="Proof of Profit",z="riverglades",s="Gelinda Coppergleam has found signs of cubic draconia in the caves, but needs a crystal to prove it exists. She asks you to bring her one so she can show others its worth.",h="Gelinda Coppergleam has found signs of cubic draconia in the caves, but needs a crystal to prove it exists.",sec={{t="A Crystal for Proof",b="Gelinda Coppergleam's surveying tools show signs of a new mineral in the caves, which she calls cubic draconia. Readings alone will not convince people, so she asks you to bring back a crystal as proof. Dragons are in the caves, and Gelinda says there may be crystals showing through the dirt.",sp=0}},faq={{q="Who is Gelinda Coppergleam?",a="Gelinda Coppergleam has found signs of cubic draconia in the caves using her surveying tools.",al={"Gelinda","who's Gelinda","coppergleam"}},{q="What is cubic draconia?",a="Cubic draconia is a mineral Gelinda believes she has found in the caves.",al={"cubic draconia","new mineral","what mineral"}},{q="Why does Gelinda want a crystal?",a="Gelinda wants a crystal to prove that cubic draconia exists, since people prefer to see one rather than inspect her readings.",al={"why crystal","proof of profit","what's the proof"}},{q="Where can I find cubic draconia?",a="Gelinda says there may be crystals showing through the dirt in the caves.",al={"where's draconia","crystal location","find cubic draconia"}},{q="Are there dragons in the caves?",a="Yes. Gelinda warns that dragons are in the caves.",al={"dragons cave","cave danger","dragons"}},{q="What if I can't get a crystal out?",a="Gelinda offers to lend you dynamite if you have trouble getting cubic draconia out of the ground.",al={"can't dig it","need dynamite","crystal stuck"}}},ang={["profession:Mining"]="As a miner, you can bring Gelinda Coppergleam a cubic draconia crystal to prove the mineral exists."},kw={"caves","crystal","cubic draconia","dynamite","gelinda coppergleam","mineral","proof of profit","surveying tools"},m={id=95934},src={"In-game quest text: Proof of Profit"},fv=true}
E["quest:95943"] = {t="quest",n="Foreman's Plight",z="riverglades",s="Bertrand Ironbrow in Farholde Keep asks you to find the Foreman's Crate and bring it back. Its return is what he seeks.",h="Bertrand Ironbrow in Farholde Keep asks you to find the Foreman's Crate and bring it back.",sec={{t="A Missing Crate",b="In Farholde Keep, Bertrand Ironbrow is looking for the Foreman's Crate. You are asked to locate it and bring it back to him.",sp=0}},faq={{q="Who wants the crate?",a="Bertrand Ironbrow in Farholde Keep asks you to find the Foreman's Crate and return it to him.",al={"who asked for it","Bertrand Ironbrow crate"}},{q="What am I looking for?",a="You are looking for the Foreman's Crate.",al={"what crate","foreman crate"}},{q="Where do I bring it?",a="Bring the Foreman's Crate back to Bertrand Ironbrow in Farholde Keep.",al={"where return crate","bring crate"}}},kw={"bertrand ironbrow","crate","farholde keep","foreman's crate","foreman's plight"},m={faction="Alliance",id=95943},src={"In-game quest text: Foreman's Plight"},fv=true}
E["quest:95951"] = {t="quest",n="Fetch 'n' Fletch",z="riverglades",s="Tan’jani offers to teach you how to make spears for the Horde’s headhunters. You are sent to Turner's Logging Camp for wood to shape into spears.",h="Tan’jani offers to teach you how to make spears for the Horde’s headhunters.",sec={{t="Wood for Spears",b="Tan’jani, a headhunter, asks you to gather wood at Turner's Logging Camp, the human camp to the west. With a knife, you can sharpen the lumber into spears for sticking humans before they see you coming. Tan’jani wants you to bring the spears back.",sp=0}},faq={{q="Who is Tan’jani?",a="Tan’jani is a headhunter who offers to teach you to make spears.",al={"tan’jani who","who's tanjani"}},{q="What does Tan’jani want me to get?",a="Tan’jani asks you to gather wood from peasant woodpiles in Turner's Logging Camp and shape it into makeshift spears.",al={"what wood","get spears"}},{q="Where is the wood?",a="The wood is at peasant woodpiles in Turner's Logging Camp, the human camp to the west.",al={"wood location","where wood"}},{q="Why does Tan’jani want spears?",a="Tan’jani says headhunters use spears to strike humans before they see them coming.",al={"why spears","headhunter spears"}}},kw={"fetch 'n' fletch","headhunters","horde","makeshift spears","tan’jani","turner's logging camp","wood bundles"},rel={"quest:95955"},m={faction="Horde",id=95951},src={"In-game quest text: Fetch 'n' Fletch"},fv=true}
E["quest:95955"] = {t="quest",n="Stick 'Em",z="riverglades",s="Tan'jani in Rog'mar teaches you to throw spears with practice in the Riverglades. Freshwater Crocolisks make his targets, and he hopes the lesson will shape you into a headhunter.",h="Tan'jani in Rog'mar teaches you to throw spears with practice in the Riverglades.",sec={{t="A Crocolisk Target",b="Tan'jani in Rog'mar has spears for you and wants you to learn to throw them. The Riverglades are full of Freshwater Crocolisks, which he calls dangerous. He sets them up as targets for your practice.",sp=0},{t="A Headhunter's Promise",b="After your practice, Tan'jani praises your work and says you have the makings of a real headhunter. He asks you to remember him if you become well known.",sp=1}},faq={{q="Who is Tan'jani?",a="Tan'jani is the one who gives you spears and teaches you to throw them in Rog'mar.",al={"tran'jani","who's tran'jani","old troll"}},{q="Why does Tan'jani send me after crocolisks?",a="Tan'jani uses the Freshwater Crocolisks of the Riverglades as targets for spear-throwing practice.",al={"why crocolisks","crocolisk practice","stick crocs"}},{q="What does Tan'jani want me to do?",a="Tan'jani wants you to practice throwing spears at Freshwater Crocolisks in the Riverglades.",al={"what do i do","stick 'em","spear targets"}},{q="Where is this happening?",a="Tan'jani gives you the spears in Rog'mar and points you toward the Riverglades for practice.",al={"where's tran'jani","riverglades quest","rog'mar"}},{q="What does Tan'jani say about the crocolisks?",a="Tan'jani warns that the Freshwater Crocolisks are dangerous and can snap you up if you are not quick.",al={"are crocs dangerous","crocolisk danger","snap you up"}}},kw={"freshwater crocolisk","headhunter","riverglades","rog'mar","spear throwing","spears","stick 'em","tan'jani","tran'jani"},rel={"zone:riverglades"},m={faction="Horde",id=95955},src={"In-game quest text: Stick 'Em"},fv=true}
E["quest:95961"] = {t="quest",n="Stepped Out",z="riverglades",s="Tessa asks you to find Gray at Powderfuse Port. He has been away longer than expected, and she wants him home with her and Emma.",h="Tessa asks you to find Gray at Powderfuse Port.",sec={{t="Tessa's Request",b="Tessa's baby, Emma, is crying as Tessa asks you to look for Gray. He left a while ago and has not come back. She says he often goes to Powderfuse Port, where his bright appearance should make him easy to recognize.",sp=0}},faq={{q="Who is Tessa looking for?",a="Tessa asks you to find Gray, Emma's father, at Powderfuse Port.",al={"who is gray","find tessa's husband","where is tessa's gray"}},{q="Why does Tessa want Gray home?",a="Tessa says Emma lights up when she sees her father, and she wants to know why he has not come back.",al={"why is tessa worried","why she needs gray","emma's father"}},{q="Where does Tessa think Gray went?",a="Tessa says Gray seems to go to Powderfuse Port often.",al={"gray location","where is gray","powderfuse port"}},{q="How can I recognize Gray?",a="Tessa says Gray shines as brightly as the sun.",al={"what does gray look like","gray appearance","who shines brightly"}}},kw={"emma","family","gray dawnbright","missing husband","powderfuse port","stepped out","tessa"},m={faction="Alliance",id=95961},src={"In-game quest text: Stepped Out"},fv=true}
E["quest:95982"] = {t="quest",n="Not My Circus",z="riverglades",s="Jasper Geartoggle asks you to help keep abandoned animals fed in Powderfuse Port. He needs Briny Seafood Stew before the hungry beasts cause trouble.",h="Jasper Geartoggle asks you to help keep abandoned animals fed in Powderfuse Port.",sec={{t="Hungry Beasts",b="In Powderfuse Port, Jasper Geartoggle asks you for help with the animals left in his care. Their owners blame him when a horse, wolf, or other beast dies or runs away. He needs Briny Seafood Stew to keep them in check, before hunger drives them into a stampede.",sp=0}},faq={{q="Who is asking for help?",a="Jasper Geartoggle asks you to help feed the animals left in his care.",al={"who needs help","who is jasper","jasper geartoggle"}},{q="What does Jasper need?",a="Jasper needs Briny Seafood Stew for the animals in his care.",al={"what food does he want","what stew","briny stew"}},{q="Why does Jasper need stew?",a="Jasper says the animals are hungry and he needs food to keep them in check.",al={"why stew","hungry animals","animals in trouble"}},{q="Where should I bring the stew?",a="Bring the Briny Seafood Stew to Jasper Geartoggle in Powderfuse Port.",al={"where is jasper","bring stew where","powderfuse port"}},{q="Why are animals being left with Jasper?",a="People keep leaving their horses, wolves, and other animals with Jasper.",al={"abandoned animals","who left the animals","why animals here"}}},kw={"briny seafood stew","horses","hungry animals","jasper geartoggle","not my circus","powderfuse port","wolves"},m={id=95982},src={"In-game quest text: Not My Circus"},fv=true}
E["quest:95983"] = {t="quest",n="A Feast for Buzzards",z="riverglades",s="A sun-bleached skeleton lies mangled by teeth and claws under the open sky. Taking the victim's gnawed skull to Watcher Cornelius at Terral's Watch is the only way to learn who died here.",h="A sun-bleached skeleton lies mangled by teeth and claws under the open sky.",sec={{t="Bones in the Sun",b="Out under the blazing sun lie the brittle, mangled bones of an unknown traveler. Deep gouges from teeth and claws score the limbs, leaving no clue who the person once was. Taking the gnawed skull to Watcher Cornelius at nearby Terral's Watch might uncover what brought them down.",sp=0},{t="A Grim Burden",b="Watcher Cornelius traces the claw marks carved across the bone with growing dread. The grim discovery brings him trouble he wanted to avoid, dragging his post into whatever violence struck down the traveler.",sp=1}},faq={{q="Who is Watcher Cornelius?",a="Watcher Cornelius is a watchman stationed at Terral's Watch.",al={"who is cornelius","watcher cornelius","terrals watch watchman"}},{q="What is Terral's Watch?",a="Terral's Watch is a post manned by Watcher Cornelius near the remains.",al={"what is terrals watch","terral watch"}},{q="Whose skeleton is this?",a="The remains are too heavily weathered by the sun and chewed by teeth and claws to tell who died.",al={"who died here","whose bones are these","skeleton identity"}},{q="What attacked the skeleton?",a="The deep markings gouged into the bones match the claw and tooth patterns of beasts.",al={"what killed the victim","who attacked the body"}}},kw={"a feast for buzzards","gnawed skull","skeleton","terral's watch","watcher cornelius"},m={faction="Alliance",id=95983},src={"In-game quest text: A Feast for Buzzards"},fv=true}
E["quest:95984"] = {t="quest",n="Song of the Strider",z="riverglades",s="Watcher Cornelius has found signs of an unusually large lion near Terral’s Watch. He wants a tallstrider beak to make a whistle that can lure the beast out.",h="Watcher Cornelius has found signs of an unusually large lion near Terral’s Watch.",sec={{t="A Lion’s Tracks",b="Watcher Cornelius reads the markings as those of a lion, likely the leader of a nearby pride. He fears Demar’s anger if word spreads that a man-eater prowls under his watch. So he plans to draw the lion out with a whistle that sounds like a wounded tallstrider. You are asked to bring him an intact beak for its call.",sp=0}},faq={{q="What did Cornelius find?",a="Watcher Cornelius found markings he believes came from an especially large lion, likely the leader of a nearby pride.",al={"lion tracks","what markings"}},{q="Why does Cornelius want a tallstrider beak?",a="Cornelius needs a tallstrider beak to make a whistle that mimics the call of a wounded tallstrider.",al={"beak for what","whistle beak"}},{q="What does Cornelius plan to do with the whistle?",a="Cornelius plans to use the whistle to lure the large lion out.",al={"lure lion","whistle plan"}},{q="Who might be angry if rumors spread?",a="Cornelius fears Demar will be furious if rumors spread about a man-eating lion prowling on his watch.",al={"who is Demar","Demar mad"}}},kw={"demar","lion","song of the strider","tallstrider beak","terral's watch","watcher cornelius","whistle"},m={faction="Alliance",id=95984},src={"In-game quest text: Song of the Strider"},fv=true}
E["quest:95986"] = {t="quest",n="King of the Wild Plains",z="riverglades",s="Watcher Cornelius asks you to face the leader of the lion pride near Terral's Watch. He wants its hide, and the matter kept from Demar.",h="Watcher Cornelius asks you to face the leader of the lion pride near Terral's Watch.",sec={{t="A Call for the Pride",b="Watcher Cornelius at Terral's Watch has made a Tallstrider Call for you. He sends you to the hill just north, where the lions gather. Blow the whistle there to draw out the pride's leader, then bring its hide back to Cornelius.",sp=0},{t="Cornelius's Concern",b="Cornelius is satisfied that the lion is slain. He asks you to keep the matter from Demar, saying Demar has already sent him out here and he wants no more attention from him.",sp=1}},faq={{q="Who asks me to hunt the lion?",a="Watcher Cornelius at Terral's Watch asks you to bring him the hide of the lion pride's leader.",al={"cornelius lion quest","who wants the hide","watcher cornelius"}},{q="Where is the lion's hill?",a="The hill where the lions gather is just north of Cornelius at Terral's Watch.",al={"lion hill where","where are the lions","hill north of here"}},{q="What does the whistle do?",a="The Tallstrider Call draws out the leader of the lion pride when blown at the hill.",al={"tallstrider call","whistle lion","call the pride leader"}},{q="What does Cornelius want from the lion?",a="Cornelius asks you to retrieve the leader's hide.",al={"lion hide","what do i bring back","pride leader hide"}}},kw={"demar","king of the wild plains","lion hide","lion pride","pride leader","tallstrider call","terral's watch","watcher cornelius"},m={faction="Alliance",id=95986},src={"In-game quest text: King of the Wild Plains"},fv=true}
E["quest:95992"] = {t="quest",n="WANTED: Ghostmaw",z="riverglades",s="Tan'jani offers a competition to catch Ghostmaw, a white crocolisk stalking the rivers. Bring its fang back to Rog'mar to claim the pot.",h="Tan'jani offers a competition to catch Ghostmaw, a white crocolisk stalking the rivers.",sec={{t="Riverside Contest",b="Tan'jani in Rog'mar has a competition for you. A white crocolisk called Ghostmaw stalks the rivers, and even the headhunters have not caught it. Bring Ghostmaw's Fang to Tan'jani; the winner claims the pot.",sp=0}},faq={{q="Who is Ghostmaw?",a="Ghostmaw is a white crocolisk that stalks the rivers.",al={"ghostmaw","white crocolisk","ghostmaw croc"}},{q="Who wants Ghostmaw's fang?",a="Tan'jani in Rog'mar asks you to bring Ghostmaw's Fang.",al={"tan'jani fang","who wants the fang","fang for who"}},{q="What does Tan'jani want me to bring?",a="Tan'jani wants Ghostmaw's Fang.",al={"ghostmaw fang","what do i bring","fang"}},{q="What is the competition about?",a="Tan'jani says the winner of the competition to catch Ghostmaw claims the pot.",al={"tan'jani competition","the pot","why catch ghostmaw"}}},kw={"crocolisk","fang","ghostmaw","headhunter","rivers","rog'mar","tan'jani"},m={faction="Horde",id=95992},src={"In-game quest text: WANTED: Ghostmaw"},fv=true}
E["quest:96009"] = {t="quest",n="High Stakes",z="riverglades",s="Bertrand Ironbrow needs wood bundles brought from Turner's Logging Camp to Farholde Keep. The lumber will help the keep finish its gate as orcs grow more feisty.",h="Bertrand Ironbrow needs wood bundles brought from Turner's Logging Camp to Farholde Keep.",sec={{t="Wood for the Keep",b="Bertrand Ironbrow needs lumber for Farholde Keep, where people are building amid a warzone filled with orcs and cultists. You are asked to bring bundles from Turner's Logging Camp because dangerous roads have slowed the shipments. The keep's gate is still being built, and the orcs are growing more feisty.",sp=0}},faq={{q="Who needs the wood?",a="Bertrand Ironbrow needs the wood at Farholde Keep.",al={"who wants wood","bertrand lumber","wood bundles for who"}},{q="Where do the bundles come from?",a="The bundles come from Turner's Logging Camp, northwest of Farholde Keep.",al={"where is the lumber","turners camp wood","wood camp"}},{q="Why is lumber running late?",a="Dangerous roads have slowed the lumber shipments from the mill to the northwest.",al={"why slow shipments","roads dangerous","lumber delay"}},{q="What is the wood for?",a="The wood is for Farholde Keep, where it may help finish the gate.",al={"why need wood","gate lumber","keep building"}},{q="What makes the roads dangerous?",a="Crocodiles and murlocs are along the way from the keep to the mill.",al={"crocs and murlocs","what is on road","road danger"}}},kw={"bertrand ironbrow","farholde keep","gate","high stakes","lumber","murlocs","turner's logging camp","wood bundles"},rel={"topic:murloc","topic:human"},m={faction="Alliance",id=96009},src={"In-game quest text: High Stakes"},fv=true}
E["quest:96026"] = {t="quest",n="Step Two: More Rock",z="riverglades",s="Hamur in Bolder'ok wants Heavy Weightstones to strengthen a weapon. He says rock makes rock stronger, and asks you to bring more.",h="Hamur in Bolder'ok wants Heavy Weightstones to strengthen a weapon.",sec={{t="Hamur's Request",b="Hamur in Bolder'ok says a weapon needs a finishing touch: more rock. He has seen small folk make Heavy Weightstones, and asks you to bring them so he can strengthen the weapon.",sp=0}},faq={{q="Who wants the Heavy Weightstones?",a="Hamur in Bolder'ok asks you to bring Heavy Weightstones.",al={"who needs weightstones","hamur request"}},{q="What does Hamur want them for?",a="Hamur says he will use the Heavy Weightstones to strengthen a weapon.",al={"why heavy weightstones","what are they for"}},{q="What does Hamur say makes rock stronger?",a="Hamur says that only rock can make rock stronger.",al={"rock stronger how","more rock"}}},kw={"bolder'ok","hamur","heavy weightstones","more rock","rock","weapon","weightstones"},m={faction="Horde",id=96026},src={"In-game quest text: Step Two: More Rock"},fv=true}
E["quest:96063"] = {t="quest",n="Gaseous Gold",z="riverglades",s="Sleebo Fizzlespout wants marsh gas from the ponds southwest of here. He hopes to use it to fuel a new engine.",h="Sleebo Fizzlespout wants marsh gas from the ponds southwest of here.",sec={{t="A New Fuel",b="Sleebo Fizzlespout sees gas rising from vents near the water in the marshy ponds to the southwest. He is developing an engine that runs on the gas and asks you to gather marsh gas vials for him. The work could help put this fuel to use in science and industry.",sp=0}},faq={{q="Who is asking for marsh gas?",a="Sleebo Fizzlespout asks you to gather marsh gas vials for him.",al={"who wants gas","Sleebo Fizzlespout"}},{q="Why does Sleebo want the gas?",a="Sleebo is developing a new kind of engine that runs on marsh gas.",al={"what's the gas for","gas engine"}},{q="Where does the marsh gas come from?",a="The gas rises from vents near the water in marshy ponds southwest of Sleebo.",al={"where is the gas","gas vents"}},{q="What is marsh gas used for?",a="Sleebo hopes to use marsh gas as fuel for his new engine.",al={"marsh gas purpose","gas fuel"}}},kw={"engine","gas vials","gaseous gold","industry","marsh gas","science","sleebo fizzlespout","vents"},m={id=96063},src={"In-game quest text: Gaseous Gold"},fv=true}
E["quest:96067"] = {t="quest",n="Rock 'em and Sock 'em",z="riverglades",s="Sleebo asks you to test G45-B4G, his gas-powered engine prototype. The trial will give him notes for repairs and changes.",h="Sleebo asks you to test G45-B4G, his gas-powered engine prototype.",sec={{t="A Mechanical Trial",b="Sleebo has one working prototype of his gas-powered engine, housed in G45-B4G's burlap chest. He can power the mechanical companion with gas you have collected. You are asked to test the machine in a fight so Sleebo can see how it performs.",sp=0},{t="Sleebo's Notes",b="After the test, Sleebo is pleased with the spectacle and the notes he gathered. He plans to repair G45-B4G and adjust the engine before the next test.",sp=1}},faq={{q="Who is G45-B4G?",a="G45-B4G is Sleebo's mechanical companion and houses the working prototype of his gas-powered engine in a burlap chest.",al={"g45-b4g","who is g45","mechanical companion"}},{q="What does Sleebo want tested?",a="Sleebo wants you to test G45-B4G, the working prototype of his gas-powered engine, in a fight.",al={"sleebo test","test the engine","what am i testing"}},{q="What powers G45-B4G?",a="Sleebo can power G45-B4G with gas you have collected.",al={"gas powered robot","engine fuel","what powers g45"}},{q="Can G45-B4G feel pain?",a="No. Sleebo says G45-B4G cannot feel anything.",al={"does g45 feel","hurt the machine","robot pain"}},{q="Why is Sleebo testing his invention?",a="Sleebo wants to stress test the gas-powered engine prototype and gather notes on how it performs.",al={"why test g45","engine stress test","sleebo invention"}}},kw={"g45-b4g","gas","gas-powered engine","mechanical companion","prototype","sleebo","stress test"},m={id=96067},src={"In-game quest text: Rock 'em and Sock 'em"},fv=true}
E["quest:96081"] = {t="quest",n="Wound Dressings",z="riverglades",s="Brother Lowley at Farholde Keep needs cloth for bandages. Farholde has no steady way to make cloth, and its supply is running low.",h="Brother Lowley at Farholde Keep needs cloth for bandages.",sec={{t="A Short Supply",b="At Farholde Keep, Brother Lowley asks you to help as quality cloth grows scarce. The keep relies on imports from goblins or cloth taken from orcs. Without more, Lowley may have to make bandages from old shirts, while the fighting force needs them to save lives.",sp=0}},faq={{q="Why does Brother Lowley need cloth?",a="Farholde needs cloth to make bandages, and its supply of quality cloth is running low.",al={"why cloth","Lowley bandages","need cloth"}},{q="Why can't Farholde make its own cloth?",a="Farholde has no reliable way to manufacture cloth, so it depends on imports from goblins or cloth taken from orcs.",al={"Farholde cloth supply","no cloth made","where cloth from"}},{q="What happens if the cloth runs out?",a="Brother Lowley may have to make bandages from old shirts.",al={"no bandages","old shirts","cloth shortage"}},{q="Who asks for the cloth?",a="Brother Lowley at Farholde Keep asks you to gather Mageweave Cloth.",al={"who needs cloth","Brother Lowley","cloth request"}}},kw={"bandages","brother lowley","cloth","farholde","farholde keep","goblins","mageweave cloth","orcs"},rel={"topic:goblin"},m={faction="Alliance",id=96081},src={"In-game quest text: Wound Dressings"},fv=true}
E["quest:96103"] = {t="quest",n="A Feast for Buzzards",z="riverglades",s="A battered skeleton on the plains bears marks that may tell a hunter what happened. You bring its skull to Neza Bloodsnout at Rog'mar for her judgment.",h="A battered skeleton on the plains bears marks that may tell a hunter what happened.",sec={{t="A Skull on the Plains",b="The bones lie battered beneath the sun, their pale surface marked with shapes like teeth and claws. The damage leaves the victim unknown. You carry the skull to Neza Bloodsnout at Rog'mar, where a hunter may read what the marks reveal.",sp=0}},faq={{q="What happened to the skeleton?",a="Its limbs bear marks resembling teeth and claws, but the attacker remains unclear.",al={"skeleton on the plains","what killed it"}},{q="Why bring the skull to Neza?",a="Neza is a hunter at Rog'mar who may recognize what the markings mean.",al={"why skull to Neza","Neza Bloodsnout"}},{q="Who was the victim?",a="The skeleton is badly damaged, and its identity is unknown before Neza examines the skull.",al={"whose skeleton","who is the dead person"}},{q="Where is Neza Bloodsnout?",a="Neza Bloodsnout is at Rog'mar.",al={"Neza location","where is Rog'mar"}}},kw={"a feast for buzzards","claw marks","gnawed skull","neza bloodsnout","rog'mar","skeleton","teeth marks"},m={faction="Horde",id=96103},src={"In-game quest text: A Feast for Buzzards"},fv=true}
E["quest:96104"] = {t="quest",n="Song of the Strider",z="riverglades",s="Neza Bloodsnout finds signs of a great lion near Rog'mar and offers to help draw it out. You bring her a tallstrider beak so she can shape a hunting whistle.",h="Neza Bloodsnout finds signs of a great lion near Rog'mar and offers to help draw it out.",sec={{t="A Hunter's Whistle",b="At Rog'mar, Neza Bloodsnout reads the marks as those of a lion, likely the leader of a nearby pride. She offers you first claim on the hunt and will help draw the beast out. For that, she needs a tallstrider beak to shape a whistle that sounds like a wounded tallstrider.",sp=0}},faq={{q="Who is Neza Bloodsnout?",a="Neza Bloodsnout is a hunter at Rog'mar who can make whistles and animal calls.",al={"Neza","who's Neza","Neza Bloodsnout"}},{q="What does Neza think made the markings?",a="Neza thinks the markings came from a lion, likely the leader of a nearby pride.",al={"what made these marks","lion tracks","markings at Rog'mar"}},{q="Why does Neza need a tallstrider beak?",a="Neza needs a tallstrider beak to shape a whistle that mimics a wounded tallstrider's call.",al={"why beak","tallstrider beak for what","whistle beak"}},{q="What is the whistle for?",a="The whistle is meant to lure the lion out by sounding like a wounded tallstrider.",al={"what's the whistle do","lure lion","lion whistle"}},{q="Where does Neza ask you to bring the beak?",a="Bring the intact tallstrider beak to Neza Bloodsnout at Rog'mar.",al={"where bring beak","Neza location","beak turn in"}}},kw={"beak","lion","neza bloodsnout","rog'mar","song of the strider","tallstrider","whistle"},m={faction="Horde",id=96104},src={"In-game quest text: Song of the Strider"},fv=true}
E["quest:96105"] = {t="quest",n="King of the Wild Plains",z="riverglades",s="Neza Bloodsnout at Rog'mar sends you after the leader of a lion pride. A Tallstrider Call will summon the beast on the hill to the south where the lions dwell.",h="Neza Bloodsnout at Rog'mar sends you after the leader of a lion pride.",sec={{t="The Call",b="Neza Bloodsnout at Rog'mar has a Tallstrider Call ready for you. Take it to the top of the hill to the south where the lions dwell, then use it when you are prepared to face the pride's leader. Neza asks you to bring back the beast's hide, and the hunt will test your strength on these plains.",sp=0}},faq={{q="Who wants the lion's hide?",a="Neza Bloodsnout at Rog'mar asks you to bring back the leader of the lion pride's hide.",al={"who sent me","Neza Bloodsnout","hide for Neza"}},{q="What does the Tallstrider Call do?",a="The Tallstrider Call summons the leader of the lion pride when used.",al={"what's the whistle for","call whistle","summon lion"}},{q="Where should I use the Tallstrider Call?",a="Use the Tallstrider Call at the top of the hill to the south where the lions dwell.",al={"where's the hill","lion hill","where to call it"}},{q="What am I hunting?",a="You are hunting the leader of the lion pride.",al={"which beast","king of wild plains","lion leader"}}},kw={"hide","hill","king of the wild plains","leader","lion pride","neza bloodsnout","rog'mar","tallstrider call"},m={faction="Horde",id=96105},src={"In-game quest text: King of the Wild Plains"},fv=true}
E["quest:96107"] = {t="quest",n="Feathers for Fletching",z="riverglades",s="Neza Bloodsnout at Rog'mar makes her own arrows and asks for Plains Buzzard Feathers. Their coarse texture makes them useful for fletching.",h="Neza Bloodsnout at Rog'mar makes her own arrows and asks for Plains Buzzard Feathers.",sec={{t="Neza's Arrows",b="At Rog'mar, Neza Bloodsnout asks you to gather feathers from nearby buzzards. She makes her arrows by hand and trusts her own work. The coarse feathers are suited to fletching, the vanes that help an arrow fly true.",sp=0}},faq={{q="Why does Neza want buzzard feathers?",a="Neza uses the coarse Plains Buzzard Feathers for fletching on the arrows she makes by hand.",al={"buzzard feather reason","why feathers","neza feathers"}},{q="Who is Neza Bloodsnout?",a="Neza Bloodsnout is an arrow maker at Rog'mar who prefers to make her arrows by hand.",al={"who is neza","neza bloodsnout","neza at rogmar"}},{q="Where can I find Neza?",a="Neza Bloodsnout is at Rog'mar.",al={"where neza","neza location","rogmar neza"}}},ang={["class:Hunter"]="As a hunter, you know arrows are a regular need; Neza makes her own and trusts her handiwork."},kw={"arrows","feathers","fletching","hunter","neza bloodsnout","plains buzzard","rog'mar"},rel={"topic:hunter"},m={faction="Horde",id=96107},src={"In-game quest text: Feathers for Fletching"},fv=true}
E["quest:96108"] = {t="quest",n="Poison Tips",z="riverglades",s="Neza Bloodsnout wants Glade Viper venom from the pools south of Rog'mar. She plans to coat arrows with it, though the poison ruins the meat.",h="Neza Bloodsnout wants Glade Viper venom from the pools south of Rog'mar.",sec={{t="A Deadly Coating",b="Poison can make an arrow more potent, though it spoils the meat. Neza Bloodsnout at Rog'mar believes you can gather venom from the vipers by the pools to the south. Their venom is dangerous to handle, so care matters as you collect it.",sp=0}},faq={{q="Who wants the viper venom?",a="Neza Bloodsnout at Rog'mar wants Glade Viper venom.",al={"who asked for venom","Neza Bloodsnout venom","who is Neza"}},{q="What is the venom for?",a="Neza plans to use the venom as a poison coating for arrows.",al={"why venom","poison arrows","what's it used for"}},{q="Where does the venom come from?",a="The Glade Vipers by the pools to the south produce the venom.",al={"where are the vipers","viper venom location","pools vipers"}},{q="Why coat arrows with poison?",a="Poison coatings make arrows more potent against prey, but ruin the meat.",al={"why poison arrows","poison tips why","make arrows stronger"}},{q="Is Glade Viper venom dangerous to gather?",a="Yes. Neza warns that you could succumb to the vipers' venom while gathering it.",al={"can venom hurt me","viper poison danger","venom warning"}}},kw={"glade viper","neza bloodsnout","poison arrows","poison tips","rog'mar","viper venom"},m={faction="Horde",id=96108},src={"In-game quest text: Poison Tips"},fv=true}
E["quest:96109"] = {t="quest",n="A Hunter's Quiver",z="riverglades",s="Neza Bloodsnout at Rog'mar needs lion hides for a hunter's quiver. You gather pelts from the lions on the southern hill.",h="Neza Bloodsnout at Rog'mar needs lion hides for a hunter's quiver.",sec={{t="A hunter's gear",b="A hunter's weapons need a quiver that holds many arrows without slowing its wearer. Neza Bloodsnout at Rog'mar asks you to gather prized lion hides for one. The lions hunt in packs, so Neza warns you to watch for being surrounded.",sp=0}},faq={{q="Who needs the lion hides?",a="Neza Bloodsnout at Rog'mar needs prized lion hides for a hunter's quiver.",al={"who wants hides","Neza Bloodsnout hides"}},{q="What are the hides for?",a="The lion hides are material for a durable quiver that fits snugly and can hold many arrows without slowing its wearer.",al={"lion hide purpose","quiver hides"}},{q="Where are the lions?",a="The lions gather on a hill to the south, visible from Rog'mar.",al={"lion hill","where lions"}},{q="Why does Neza want lion pelts?",a="Neza says lion pelts are well suited to life as a hunter on the plains.",al={"why lion hides","lions for quiver"}},{q="What warning does Neza give?",a="Neza warns that the lions hunt in packs and may surround you.",al={"lion warning","packs"}}},ang={["class:Hunter"]="As a hunter, you need a quiver that carries many arrows without slowing you down."},kw={"arrows","hunter","hunter's quiver","lion hides","lions","neza bloodsnout","prized lion hides","rog'mar"},rel={"topic:hunter","quest:95329"},m={faction="Horde",id=96109},src={"In-game quest text: A Hunter's Quiver"},fv=true}
E["quest:96125"] = {t="quest",n="In Need of Relief",z="riverglades",s="A guard south of Bolder'ok needs relief after the lion hides are gathered and orcish poachers are culled. Dunston Willis has not returned from the ogre settlement, and you are asked to find him.",h="A guard south of Bolder'ok needs relief after the lion hides are gathered and orcish poachers are culled.",sec={{t="A Missing Relief",b="The watch remains without its promised relief. Dunston Willis, an explorer, went to investigate the ogre settlement to the north a few days ago and was expected back to take over the post. The guard asks you to find him among the ogres. If Dunston is alive, bring him back; if not, bring proof so Demar can send someone else.",sp=0}},faq={{q="Who is Dunston Willis?",a="Dunston Willis is an explorer who went to investigate Bolder'ok, the ogre settlement to the north.",al={"Dunston","who is Dunston","explorer Willis"}},{q="Why is the guard looking for Dunston?",a="Dunston was expected to return and take over the guard's post, but he has not come back.",al={"why find Dunston","missing relief","guard needs help"}},{q="Where did Dunston go?",a="Dunston went to investigate the ogre settlement at Bolder'ok.",al={"Dunston location","where is Willis","ogre settlement"}},{q="What does the guard ask me to do?",a="You are asked to find Dunston among the ogres. If he is alive, bring him back; otherwise, bring proof so Demar can send another guard.",al={"what do I do","find Dunston","relief request"}},{q="What happened before Dunston went missing?",a="The lion hides were collected and the orcish poachers were culled before the guard expected Dunston to relieve the watch.",al={"lion hides","poachers culled","what came first"}}},kw={"bolder'ok","demar","dunston willis","in need of relief","lion hides","ogres","orcish poachers","watch"},m={faction="Alliance",id=96125},src={"In-game quest text: In Need of Relief"},fv=true}
E["subzone:sunnyglade"] = {t="subzone",n="Sunnyglade",z="riverglades",s="Twilight's Hammer zealots now occupy Sunnyglade's ruins in the Riverglades. Once a wealthy human settlement under Stormwind, it was devastated during the First War and abandoned as the Horde advanced.",h="Twilight's Hammer zealots now occupy Sunnyglade's ruins in the Riverglades.",sec={{t="Fall of a Golden Town",b="Before the First War, Sunnyglade was a wealthy human town. Then the Old Horde invasion shattered its peace. Orc raiders attacked and enslaved the residents who survived. Only a wizard's tower remained intact, for human conjurers to study the arcane arts.\n\nStormwind forces tried to free the captive peasants and rebuild Sunnyglade. But the Horde kept advancing through the Riverglades. Stormwind's commanders judged the outer province lost and drew resources back to defend the homeland. The town was left in ruins.",sp=0},{t="A Blighted Refuge",b="Sunnyglade lies far beyond the safe borders of Stormwind's restored realm. Its stone mage tower survived the First War and the years of abandonment. The peaceful township around it is gone, and Twilight's Hammer zealots now occupy the secluded ruins. They use the once-prosperous valley for their own designs.",sp=0}},faq={{q="What happened to Sunnyglade?",a="The Old Horde attacked and sacked Sunnyglade during the First War, enslaving its surviving residents. Human forces freed captive peasants and tried to rebuild, but Stormwind later abandoned the Riverglades to defend its homeland.",al={"what is sunnyglade","sunnyglade history","why is sunnyglade destroyed"}},{q="Who controls Sunnyglade now?",a="Twilight's Hammer cultists occupy Sunnyglade's ruins, including its broken houses and ancient wizard's tower.",al={"who lives in sunnyglade","sunnyglade enemies","sunnyglade twilight"}},{q="Why did the orcs leave the mage tower standing during the First War?",a="The Old Horde spared Sunnyglade's arcane tower so its warlocks and commanders could study human magic and seek to unravel its secrets.",al={"orc mage tower sunnyglade","sunnyglade tower lore"}},{q="Why didn't Stormwind reclaim the town after the war?",a="Stormwind's leaders judged the Riverglades lost as the First War intensified and redirected military resources to defend the homeland, leaving Sunnyglade behind.",al={"why abandoned","stormwind sunnyglade"}}},ang={["class:Mage"]="As a mage, Sunnyglade's lone wizard's tower recalls early human spellcraft. The Old Horde spared it so they could study human arcane knowledge.",["race:Human"]="As a human, Sunnyglade's overgrown stones recall the outer settlements Stormwind abandoned when it pulled back during the First War."},kw={"first war","mage tower","old horde","riverglades","stormwind","sunnyglade","twilight's hammer"},rel={"zone:riverglades","topic:twilight-s-hammer","topic:first-war","topic:old-horde","topic:stormwind-kingdom","zone:redridge"},src={"Sunnyglade"}}
E["zone:riverglades"] = {t="zone",n="Riverglades",z="riverglades",s="In Riverglades, human loyalists and Horde outposts still contest a valley east of the Badlands and Burning Steppes. Stormwind once claimed the region, but the Old Horde overran it in the First War. The Redridge Mountains lie southwest, the Swamp of Sorrows south, and Tanaris across the sea.",h="In Riverglades, human loyalists and Horde outposts still contest a valley east of the Badlands and Burning...",sec={{t="A Forgotten Borderland",b="Before the First War, Riverglades belonged to the Kingdom of Stormwind. Then the Old Horde swept through. Orcs sacked Sunnyglade but spared its mage tower to study human sorcery. They enslaved the townsfolk who survived. Stormwind soldiers tried to free the captives and rebuild, but the kingdom judged the valley lost and sent its strength to defend the core homelands. For years, the crown gave Riverglades little formal support.",sp=0},{t="The Struggle for Farholde",b="Stormwind's leaders left Riverglades behind, yet its human defenders never fully surrendered their homeland. Knight Commander Demar Brant leads the remaining loyalists of the legendary brotherhood of the horse. They hold farholde keep against the wilderness and hostile invaders. Nearby, the modern Horde keeps a strong presence at outposts such as rog'mar and bolder'ok. The old struggle over the glades continues.",sp=0},{t="Geography and Travel",b="Riverglades follows the coast of the Forbidding Sea, among mountains and winding waterways. You can cross west through Blackrock Pass to the Burning Steppes, or travel southwest through Redridge Pass to the Redridge Mountains. South lies the Swamp of Sorrows. To the northwest, trails pass Twilight's Shroud into the Badlands. At powderfuse port, you can take a boat across the sea to steamwheedle port in Tanaris.",sp=0}},faq={{q="What is the Riverglades?",a="Riverglades lies east of the Badlands and Burning Steppes, along the Forbidding Sea. Stormwind once claimed the region. Now the Alliance holds Farholde Keep while the Horde keeps Rog'mar.",al={"riverglades overview","what is this zone","about riverglades"}},{q="What happened to Sunnyglade?",a="The Old Horde raided and destroyed Sunnyglade during the First War. Orcs enslaved the surviving villagers but kept a local mage tower intact to study human magic. Stormwind soldiers tried to free the captives and rebuild, but the kingdom finally abandoned the area to defend its western borders.",al={"sunnyglade history","fall of sunnyglade","what happened to the town"}},{q="Who controls Farholde Keep?",a="Alliance loyalists hold Farholde Keep under Knight Commander Demar Brant of the Brotherhood of the Horse. His forces have spent years fighting to reclaim Riverglades after Stormwind gave the territory up as lost.",al={"who leads farholde","alliance in riverglades","Brotherhood of the Horse"}},{q="How do you reach Tanaris from the Riverglades?",a="From Powderfuse Port on Riverglades' eastern shore, a coastal boat runs regularly to Steamwheedle Port in Tanaris, crossing directly over the sea.",al={"boat to tanaris","Powderfuse Port boat","how to get to tanaris"}},{q="What passes lead into other zones?",a="You can travel southwest through Redridge Pass to reach the Redridge Mountains, or head south toward the Swamp of Sorrows. Westward, Blackrock Pass leads past the Bristle Hills to the Burning Steppes. Trails north of Twilight's Shroud run directly into the Badlands.",al={"how to get to redridge","passes from riverglades","exits from riverglades"}},{q="What is Krol'dok Stronghold?",a="Krol'dok Stronghold is a fortified dungeon complex in Riverglades and a major seat of hostile power in the contested territory.",al={"kroldok stronghold","riverglades dungeon","what dungeon is here"}}},ang={["faction:Alliance"]="As an Alliance soldier, you find old wounds laid bare in Riverglades. Remnants of the Brotherhood of the Horse continue their quiet crusade to retake land Stormwind abandoned during the First War.",["faction:Horde"]="For the Horde, outposts such as Rog'mar secure a coastal foothold and keep pressure on the old human strongholds east of Redridge.",["race:Human"]="As a human, you can see a tragic chapter of your heritage in Sunnyglade. It recalls the heavy toll the First War took on your kingdom's eastern frontier."},kw={"blackrock pass","Brotherhood of the Horse","demar brant","Farholde Keep","krol'dok stronghold","Powderfuse Port","redridge pass","riverglades","Rog'mar","sunnyglade"},rel={"subzone:sunnyglade","subzone:blackrock-pass","zone:redridge","zone:badlands","zone:swampofsorrows","zone:burningsteppes","subzone:steamwheedle-port"},src={"Riverglades"}}
